# Keep a handle to the original getpass prompt function so we can provide a
# confirmed-password wrapper without recursion.
_RAW_GETPASS = getpass.getpass


def _prompt_password_with_confirmation(prompt: str = "Password: ", stream=None):
    """Prompt for a password and require confirmation before returning.

    This wrapper is intentionally used for all interactive password entry so
    operators can correct mistyped passwords inline without restarting flows.
    """
    while True:
        _pw = _RAW_GETPASS(prompt, stream=stream)
        _confirm_prompt = "  Confirm password: "
        _pw_confirm = _RAW_GETPASS(_confirm_prompt, stream=stream)
        if _pw == _pw_confirm:
            return _pw
        print("  ⚠️  Passwords do not match. Please re-enter.")


# Enforce confirmation for all subsequent getpass.getpass(...) calls in this script.
getpass.getpass = _prompt_password_with_confirmation

# OPT: compile LOADER prompt regex once at module level instead of per-iteration
_LOADER_PROMPT_RE = re.compile(r'LOADER-\w+>')

# Cluster shell prompt: e.g. "clustername::>" (admin) or "clustername::*>" (diag)
_CLUSTER_PROMPT_RE = re.compile(r'\S+::\*?>\s*$')

# Loose cluster shell prompt (matches anywhere in tail buffer, not anchored).
# Used by parallel shell command helpers; hoisted to module scope so the
# regex is compiled once instead of on every helper invocation.
_SHELL_PROMPT_RE = re.compile(r"::\*?>")

# ANSI/VT100 escape sequence stripper — PTY and system-console sessions inject
# these codes for colour / cursor movement; strip before text parsing.
_ANSI_RE = re.compile(r'\x1b(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])')
_BRACKETED_IPV4_RE = re.compile(
    r"\[(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\]"
)
_INLINE_TS_RE = re.compile(r"\|\s\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}")
_PREFIX_TS_RE = re.compile(r"^\[\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}\]")

# Timeout-warning flood guard for direct_read_until_any().
_WAIT_TIMEOUT_LOG_SUPPRESS_WINDOW_SEC = 10.0
_WAIT_TIMEOUT_LOG_SUMMARY_INTERVAL_SEC = 60.0
_wait_timeout_log_state: "dict[tuple, dict[str, float | int]]" = {}
_wait_timeout_log_lock = threading.Lock()


def _log_wait_timeout_throttled(timeout: int, look_for_list, elapsed: float) -> None:
    """Throttle repetitive timeout warnings for identical matcher sets.

    Also emits a periodic summary so we still preserve troubleshooting signal
    without writing millions of duplicate lines under hot-loop conditions.
    """
    if not _session_log:
        return
    _safe_timeout = int(timeout or 0)
    _sigs = tuple(str(s or "").strip().lower() for s in (look_for_list or []))
    _key = (_safe_timeout, _sigs)
    _now = time.monotonic()
    _msg = f"Timeout ({_safe_timeout}s) waiting for any of {list(look_for_list or [])}"
    _fast_return = elapsed < max(1.0, float(_safe_timeout) * 0.8)
    with _wait_timeout_log_lock:
        _state = _wait_timeout_log_state.setdefault(
            _key,
            {"last_emit": 0.0, "last_summary": 0.0, "suppressed": 0},
        )
        _last_emit = float(_state.get("last_emit") or 0.0)
        _last_summary = float(_state.get("last_summary") or 0.0)
        _suppressed = int(_state.get("suppressed") or 0)

        if _now - _last_emit >= _WAIT_TIMEOUT_LOG_SUPPRESS_WINDOW_SEC:
            if _suppressed > 0:
                _session_log.log(
                    f"Suppressed {_suppressed} duplicate timeout warning(s) for matcher set {_sigs}",
                    prefix="WARN",
                )
                _suppressed = 0
            _session_log.log(_msg, prefix="WARN")
            if _fast_return:
                _session_log.log(
                    f"Timeout wait returned early ({elapsed:.2f}s < requested {_safe_timeout}s); "
                    "this usually indicates rapid reconnect/shutdown churn.",
                    prefix="WARN",
                )
            _state["last_emit"] = _now
            _state["last_summary"] = _now
            _state["suppressed"] = _suppressed
            return

        _suppressed += 1
        _state["suppressed"] = _suppressed
        if _now - _last_summary >= _WAIT_TIMEOUT_LOG_SUMMARY_INTERVAL_SEC:
            _session_log.log(
                f"Still timing out for matcher set {_sigs}; suppressed {_suppressed} duplicate warning(s) "
                f"in the last {int(_now - _last_summary)}s",
                prefix="WARN",
            )
            _state["last_summary"] = _now
            _state["suppressed"] = 0

# ---------------------------------------------------------------------------
# Per-reinit elapsed-time / node-label tracking
# ---------------------------------------------------------------------------
# Set at AUTOBOOT detection so every status line that follows shows how far
# into the reinit sequence the node is.
_reinit_t0: "float | None" = None   # time.monotonic() when reinit started
_reinit_label: str = ""             # BMC IP or node identifier


def _elapsed_str() -> str:
    """Return ' (+Xs)' or ' (+MmSs)' since _reinit_t0, or '' if not set."""
    if _reinit_t0 is None:
        return ""
    secs = int(time.monotonic() - _reinit_t0)
    if secs < 60:
        return f" (+{secs}s)"
    return f" (+{secs // 60}m{secs % 60:02d}s)"


def _phase_elapsed_str(phase_start: float) -> str:
    """Return '(Xs in this phase (+YmZs))' for long-running wait updates."""
    _phase_secs = max(0, int(time.monotonic() - phase_start))
    return f"({_phase_secs}s in this phase{_elapsed_str()})"


def _node_pfx(label: str = "") -> str:
    """Return '[label] ' using *label* if given, else _reinit_label."""
    lbl = _augment_role_label_with_ip(str(label or _reinit_label or "").strip(), mode=_operation_mode)
    return f"[{lbl}] " if lbl else ""


def _print_wait_log_hint(*, node_log=None, log_path: str = "") -> None:
    """Print a standard 'for details' hint for long-running wait states."""
    _path = str(log_path or "").strip()
    if not _path and node_log is not None:
        _path = str(getattr(node_log, "name", "") or "").strip()
    if not _path and _session_log:
        _path = str(getattr(_session_log, "log_file", "") or "").strip()
    if not _path:
        return
    print(f"   For details, see log at:\n   {_path}\n   (open in a separate SSH session)")


_log_sequence_lock = threading.Lock()
_log_sequence_by_scope: dict = {}


def _log_sequence_scope(log_dir: str = "", scope_dir: str = "") -> str:
    """Return the scope key used to number log files in creation order."""
    _scope = str(scope_dir or "").strip() or str(log_dir or "").strip()
    if not _scope and "_session_log" in globals() and _session_log:
        _scope = str(getattr(_session_log, "log_dir", "") or "").strip()
    if not _scope:
        _scope = os.getcwd()
    _scope = os.path.abspath(_scope)
    if os.path.basename(_scope).lower() == "ssh_logs":
        _parent = os.path.dirname(_scope)
        if _parent:
            _scope = _parent
    return _scope


def _build_numbered_log_path(log_dir: str, filename: str, scope_dir: str = "") -> str:
    """Return a log path prefixed with an incrementing creation-order number."""
    os.makedirs(log_dir, exist_ok=True)
    _scope = _log_sequence_scope(log_dir, scope_dir)
    with _log_sequence_lock:
        _seq = _log_sequence_by_scope.get(_scope, 0) + 1
        _log_sequence_by_scope[_scope] = _seq
    _base = os.path.basename(filename)
    if not re.match(r"^\d+-", _base):
        _base = f"{_seq}-{_base}"
    return os.path.join(log_dir, _base)

# ---------------------------------------------------------------------------
# Checkpoint manager
# ---------------------------------------------------------------------------

class CheckpointManager:
    """Persists run state to a JSON file so a 4.2 run can resume from the last
    completed phase rather than starting over from scratch.

    Phases tracked (per-node unless noted):
      ``bmc_connected``       — BMC SSH shell established
      ``at_loader``           — Node reached LOADER prompt
      ``install_done``        — Netboot + option 6 complete; node at ONTAP login
      ``option6_done``        — Boot menu option 6 confirmation accepted.
                                Marked as soon as the 'y' confirmation
                                is sent so that failures during the
                                post-option-6 boot wait (where most
                                runs die) do not force a re-install on
                                resume. Treated as install-equivalent
                                by the resume skip logic.
      ``reinit_loader``       — Reconnected to BMC for reinit; back at LOADER
      ``primary_node_mgmt_done`` — (global) primary node-management prompts
                                were answered and the cluster-setup wizard is
                                about to begin. Used by 4.2 resume so the
                                primary does not get reset again after node
                                configuration is already complete.
      ``primary_bootmenu_done`` — (global) primary node has cleared the
                                  ONTAP boot menu (option 9 for mode 1.2/3,
                                  option 4 for mode 2). Cluster setup
                                  wizard is about to begin.
      ``cluster_formed``      — (global) ``cluster create`` succeeded;
                                cluster shell ``::>`` reachable.
      ``primary_setup_done``  — (global) primary cluster-setup wizard
                                returned successfully (license / SSH
                                post-steps may still be pending).
      ``peer_option4_done``   — (per-peer, mode 3) peer cleared boot
                                menu option 4, finished format, and
                                reached the join barrier. Format work
                                does not need to be re-run on resume.
      ``peer_joined``         — (per-peer, mode 3) peer joined the
                                cluster and ``cluster show`` confirmed
                                membership.
      ``option3_complete``    — (global) mode 3 finalize banner printed;
                                the checkpoint file is then deleted.

    Passwords are intentionally NOT saved; the operator will be asked to
    re-enter them on resume.

    Usage::

        cp = CheckpointManager()
        cp.init_run(mode="4.2", bmc_ips=["10.x.x.x"], log_dir="/path")
        cp.mark_node_done("install_done", "10.x.x.x")
        cp.mark_done("cluster_formed")

        # On restart
        cp2 = CheckpointManager()
        if cp2.load():
            if cp2.is_node_done("install_done", "10.x.x.x"):
                ...  # skip install phase

        cp.clear()  # on successful completion
    """

    CHECKPOINT_DIR = "checkpoints"
    CHECKPOINT_FILE = "afx_checkpoint.json"
    MAX_AGE_HOURS = 72  # checkpoints older than this are ignored
    MAX_ARCHIVE_KEEP = 5  # how many archived checkpoints to retain

    def __init__(self, path: "str | None" = None):
        try:
            _script_dir = os.path.dirname(os.path.abspath(__file__))
        except NameError:
            _script_dir = os.getcwd()
        _cp_dir = os.path.join(_script_dir, self.CHECKPOINT_DIR)
        os.makedirs(_cp_dir, exist_ok=True)
        self._path = path or os.path.join(_cp_dir, self.CHECKPOINT_FILE)
        self._data: "dict" = {}
        self._data_lock = threading.RLock()

    # ── Public API ─────────────────────────────────────────────────────────

    @classmethod
    def list_all(cls) -> "list[CheckpointManager]":
        """Return all valid, non-expired checkpoints in the checkpoint dir,
        sorted newest-first by their ``created`` timestamp.

        Both the active checkpoint (``afx_checkpoint.json``) and any archived
        checkpoints (``afx_checkpoint_YYYYMMDDTHHMMSS.json``) are included.
        """
        try:
            _script_dir = os.path.dirname(os.path.abspath(__file__))
        except NameError:
            _script_dir = os.getcwd()
        _cp_dir = os.path.join(_script_dir, cls.CHECKPOINT_DIR)
        _results: "list[CheckpointManager]" = []
        if not os.path.isdir(_cp_dir):
            return _results
        for _fname in os.listdir(_cp_dir):
            if not (_fname.startswith("afx_checkpoint") and _fname.endswith(".json")):
                continue
            _cm = cls(path=os.path.join(_cp_dir, _fname))
            if _cm.load():
                _results.append(_cm)
        _results.sort(key=lambda c: c.created or "", reverse=True)
        return _results

    def _prune_archives(self) -> None:
        """Remove archived checkpoint files beyond ``MAX_ARCHIVE_KEEP``."""
        _cp_dir = os.path.dirname(self._path)
        try:
            _archives = sorted(
                [
                    _f for _f in os.listdir(_cp_dir)
                    if _f.startswith("afx_checkpoint_") and _f.endswith(".json")
                ],
                reverse=True,  # newest filename-timestamp first
            )
            for _old in _archives[self.MAX_ARCHIVE_KEEP:]:
                with suppress(Exception):
                    os.remove(os.path.join(_cp_dir, _old))
        except Exception:
            pass

    def init_run(self, mode: str, bmc_ips: "list[str]",
                 log_dir: str = "", config_path: str = "") -> None:
        """Initialise a fresh checkpoint for a new run.

        The existing active checkpoint (if any) is archived to a timestamped
        file before the new one is written so that the operator can resume a
        previous run even after a new run has been started.
        """
        # Archive the current active checkpoint before overwriting it so the
        # operator can still resume the previous run from the menu.
        with _checkpoint_io_lock:
            if os.path.isfile(self._path):
                with suppress(Exception):
                    _ts_str = datetime.now().strftime("%Y%m%dT%H%M%S")
                    _archive = os.path.join(
                        os.path.dirname(self._path),
                        f"afx_checkpoint_{_ts_str}.json",
                    )
                    os.rename(self._path, _archive)
        self._prune_archives()

        now = datetime.now().isoformat()
        with self._data_lock:
            self._data = {
                "version": 1,
                "created": now,
                "updated": now,
                "mode": mode,
                "log_dir": log_dir,
                "config_path": config_path,
                "bmc_ips": list(bmc_ips),
                "current_phase": {
                    "name": "Run initialization",
                    "state": "in_progress",
                    "next_phase": "(pending completion of current phase)",
                    "node_ip": "",
                    "ts": now,
                },
                "phases": {},        # phase_name -> {"done": bool, "ts": str}
                "node_phases": {},   # phase_name -> {ip -> {"done": bool, "ts": str}}
                "selections": {      # Operator selections to persist across resume
                    "enable_autosupport": None,      # bool or None
                    "physical_zeroing": None,        # bool or None
                    "prevent_bios_fw_update": None,  # bool or None
                    "setup_passwordless_ssh": None,  # bool or None
                    "netboot_before_reinit": None,   # bool or None
                    "loader_env_stage_enabled": None, # bool or None
                    "skip_loader_env_backup": None,  # bool or None
                },
            }
        self._save()

    def load(self) -> bool:
        """Load a checkpoint from disk.  Returns True if a valid,
        non-expired checkpoint was loaded, False otherwise.
        """
        with _checkpoint_io_lock:
            if not os.path.isfile(self._path):
                return False
            try:
                with open(self._path, "r", encoding="utf-8") as f:
                    data = json.load(f)
            except Exception:
                return False
        if data.get("version") != 1:
            return False
        created_str = data.get("created", "")
        if created_str:
            try:
                created_dt = datetime.fromisoformat(created_str)
                age_hours = (datetime.now() - created_dt).total_seconds() / 3600
                if age_hours > self.MAX_AGE_HOURS:
                    return False
            except Exception:
                pass
        with self._data_lock:
            self._data = data
        return True

    def save(self) -> None:
        """Public wrapper — call after modifying state externally."""
        self._save()

    def clear(self) -> None:
        """Delete the checkpoint file (call on successful run completion)."""
        with _checkpoint_io_lock:
            with suppress(Exception):
                os.remove(self._path)
        with self._data_lock:
            self._data = {}

    @property
    def path(self) -> str:
        """Return the checkpoint file path."""
        return self._path

    # ── Phase helpers ───────────────────────────────────────────────────────

    def mark_done(self, phase: str) -> None:
        """Mark a global (non-per-node) phase as complete."""
        _marked = False

        def _mutate(data) -> bool:
            nonlocal _marked
            if bool(data.get("phases", {}).get(phase, {}).get("done")):
                return False
            data.setdefault("phases", {})[phase] = {
                "done": True, "ts": datetime.now().isoformat(),
            }
            _marked = True
            return True

        self._save(mutator=_mutate)
        if not _marked:
            return
        _log_pending_checkpoint_test_target(phase)
        _maybe_inject_checkpoint_failure(phase)

    def is_done(self, phase: str) -> bool:
        """Return True if a global phase is marked complete."""
        return bool(self._data.get("phases", {}).get(phase, {}).get("done"))

    def mark_node_done(self, phase: str, ip: str) -> None:
        """Mark a per-node phase as complete for *ip*."""
        _marked = False
        _blocked = False

        def _mutate(data) -> bool:
            nonlocal _marked, _blocked
            if _checkpoint_test_should_block_mode3_peer_checkpoint(phase, ip):
                _blocked = True
                return False
            _existing = data.get("node_phases", {}).get(phase, {}).get(ip, {})
            if bool(_existing.get("done")):
                return False
            np = data.setdefault("node_phases", {})
            np.setdefault(phase, {})[ip] = {
                "done": True, "ts": datetime.now().isoformat(),
            }
            _checkpoint_test_prepare_mode3_abort_barrier(phase, ip)
            _marked = True
            return True

        self._save(mutator=_mutate)
        if _blocked:
            _slog(
                f"mode 3 checkpoint abort barrier active; skipping {phase} for {ip}",
                prefix="WARN",
            )
            return
        if not _marked:
            return
        _log_pending_checkpoint_test_target(phase, ip)
        _maybe_inject_checkpoint_failure(phase, ip)

    def is_node_done(self, phase: str, ip: str) -> bool:
        """Return True if the per-node phase is marked complete for *ip*."""
        return bool(
            self._data.get("node_phases", {})
                      .get(phase, {})
                      .get(ip, {})
                      .get("done")
        )

    def nodes_done_for(self, phase: str) -> "list[str]":
        """Return the list of IPs that have completed *phase*."""
        return [
            ip for ip, v in
            self._data.get("node_phases", {}).get(phase, {}).items()
            if v.get("done")
        ]

    def set_current_phase(self, phase: str, state: str = "in_progress",
                          node_ip: str = "", next_phase: str = "") -> None:
        """Record the run's current phase in the checkpoint file.

        Used by live status helpers so --checkpoint-status can show where
        a running job currently is.
        """
        _state = str(state or "").strip() or "in_progress"
        _name = str(phase or "").strip()
        _next = str(next_phase or "").strip()
        if not _next:
            if _state == "in_progress":
                _next = "(pending completion of current phase)"
            else:
                _next = "(pending)"
        if _name and _next == _name:
            _next = "(pending completion of current phase)"
        with self._data_lock:
            self._data["current_phase"] = {
                "name": _name,
                "state": _state,
                "next_phase": _next,
                "node_ip": str(node_ip or "").strip(),
                "ts": datetime.now().isoformat(),
            }
        self._save()

    def summary(self) -> str:
        """Return a human-readable description of the loaded checkpoint.

        Lists run metadata (mode, created/updated timestamps, log dir, config
        path), every global phase recorded, and per-node phase completion
        keyed by BMC IP. Intended for the ``--checkpoint-status`` CLI flag so
        an operator can see exactly where a previous run left off without
        opening the JSON file by hand.
        """
        if not self._data:
            return f"No checkpoint loaded (file: {self._path})."

        lines = []
        lines.append(f"Checkpoint file : {self._path}")
        lines.append(
            f"Mode            : {_format_checkpoint_mode(self._data.get('mode', '?'))}"
        )
        lines.append(f"Created         : {self._data.get('created', '?')}")
        lines.append(f"Updated         : {self._data.get('updated', '?')}")
        try:
            created_dt = datetime.fromisoformat(self._data.get("created", ""))
            age_min = int((datetime.now() - created_dt).total_seconds() // 60)
            lines.append(f"Age             : {age_min} minute(s)")
        except Exception:
            pass
        if self._data.get("log_dir"):
            lines.append(f"Log directory   : {self._data['log_dir']}")
        if self._data.get("config_path"):
            lines.append(f"Config path     : {self._data['config_path']}")
        bmc_ips = self._data.get("bmc_ips") or []
        if bmc_ips:
            lines.append(f"BMC IPs         : {', '.join(bmc_ips)}")
        _mode_raw = str(self._data.get("mode") or "").strip().lower()
        _cur = self._data.get("current_phase") or {}
        _cur_name = ""
        _cur_state = ""
        _next_phase = ""
        if _cur:
            _cur_name = str(_cur.get("name") or "").strip() or "(unknown)"
            _cur_state = str(_cur.get("state") or "").strip() or "in_progress"
            _next_phase = str(_cur.get("next_phase") or "").strip() or "(not recorded)"
            _cur_node = str(_cur.get("node_ip") or "").strip()
            _cur_ts = str(_cur.get("ts") or "").strip()
            _cur_parts = [f"{_cur_name} [{_cur_state}]"]
            if _cur_node:
                _cur_parts.append(f"node={_cur_node}")
            if _cur_ts:
                _cur_parts.append(f"as of {_cur_ts}")
            lines.append(f"Current phase   : {', '.join(_cur_parts)}")
            _placeholder_next = {
                "(pending completion of current phase)",
                "(pending)",
                "(not recorded)",
            }
            if _mode_raw in ("1", "2", "3", "4.1", "4.2", "4.3") and _next_phase in _placeholder_next:
                with suppress(Exception):
                    _inferred_cp_id = _checkpoint_resume_phase_id(self)
                    if _inferred_cp_id:
                        _inferred_cp_desc = _checkpoint_phase_description(_inferred_cp_id)
                        _next_phase = (
                            f"{_inferred_cp_id} - {_inferred_cp_desc}"
                            if _inferred_cp_desc else _inferred_cp_id
                        )
            lines.append(f"Next expected phase: {_next_phase}")
        else:
            lines.append("Current phase   : (not recorded)")
            lines.append("Next expected phase: (not recorded)")

        phases = self._data.get("phases") or {}
        lines.append("")
        lines.append("Global phases:")
        if not phases:
            lines.append("  (none recorded)")
        else:
            _prev_ts = None
            for name, meta in phases.items():
                mark = "✅" if meta.get("done") else "  "
                ts = meta.get("ts", "")
                _formatted = _format_checkpoint_phase_with_delta(name, ts, _prev_ts)
                lines.append(f"  {mark} {_formatted} {ts}")
                if ts:
                    _prev_ts = ts

        node_phases = self._data.get("node_phases") or {}
        lines.append("")
        lines.append("Per-node phases:")
        def _display_ip(_node_id: str) -> str:
            _raw = str(_node_id or "").strip()
            if _raw.startswith("node_peer:"):
                return str(_raw.split(":", 1)[1] or "").strip()
            return _raw

        _all_ips = sorted({
            _display_ip(ip) for per_ip in node_phases.values() for ip in per_ip.keys()
            if _display_ip(ip)
        } | set(bmc_ips))

        def _node_phase_done_for_display(_phase_name: str, _ip: str) -> bool:
            _per = node_phases.get(_phase_name, {}) or {}
            if bool(_per.get(_ip, {}).get("done")):
                return True
            _peer_key = _mode3_peer_checkpoint_node(_ip)
            return bool(_per.get(_peer_key, {}).get("done"))
        _synthetic_done_by_ip = {}
        if bmc_ips:
            _primary_done = []
            for _phase_name in (
                "primary_bootmenu_done",
                "primary_node_mgmt_done",
                "primary_setup_done",
            ):
                if phases.get(_phase_name, {}).get("done"):
                    _primary_done.append(_phase_name)
            if _primary_done:
                _synthetic_done_by_ip[bmc_ips[0]] = _primary_done
        if not _all_ips and not _synthetic_done_by_ip:
            lines.append("  (none recorded)")
        else:
            # Build a phase x ip matrix so each node's progress is easy to scan.
            all_ips = _all_ips or list(bmc_ips)
            phase_names = list(node_phases.keys())
            _phase_done_counts = {
                _phase: sum(
                    1 for _ip in all_ips
                    if _node_phase_done_for_display(_phase, _ip)
                )
                for _phase in phase_names
            }
            _phase_done_ips = {
                _phase: [
                    _ip for _ip in all_ips
                    if _node_phase_done_for_display(_phase, _ip)
                ]
                for _phase in phase_names
            }
            _primary_ip = bmc_ips[0] if bmc_ips else ""
            _wizard_waiting_mode3 = (
                _mode_raw == "4.2-3"
                and _cur_state == "in_progress"
                and _cur_name in {
                    "Cluster Setup Wizard (mode 1)",
                    "4.2 – Cluster Initialization (primary)",
                    "4.2 – Cluster Initialization (primary resume)",
                }
                and bool(phases.get("primary_node_mgmt_done", {}).get("done"))
                and not bool(phases.get("cluster_formed", {}).get("done"))
            )
            for ip in all_ips:
                completed = [
                    p for p in phase_names
                    if _node_phase_done_for_display(p, ip)
                ]
                display_done = completed + [
                    _p for _p in _synthetic_done_by_ip.get(ip, [])
                    if _p not in completed
                ]
                pending = [p for p in phase_names if p not in completed]
                _all_known_node_phases_done = bool(phase_names) and not pending
                if (_wizard_waiting_mode3 and _all_known_node_phases_done
                        and "reinit_loader" in completed):
                    if ip == _primary_ip:
                        node_current = _cur_name
                    else:
                        node_current = "(waiting on primary cluster setup)"
                    node_next = _next_phase or "2.2 – Parallel Node Add"
                elif pending:
                    _pending_phase = pending[0]
                    _peer_progress_on_pending = _phase_done_counts.get(_pending_phase, 0) > 0
                    if not completed and _peer_progress_on_pending:
                        _done_peers = [
                            _peer for _peer in _phase_done_ips.get(_pending_phase, [])
                            if _peer != ip
                        ]
                        if _done_peers:
                            node_current = (
                                f"(waiting on other nodes for {_pending_phase}: "
                                f"{', '.join(_done_peers)})"
                            )
                        else:
                            node_current = f"(waiting on other nodes for {_pending_phase})"
                        node_next = _pending_phase
                    else:
                        node_current = _pending_phase
                        node_next = pending[1] if len(pending) > 1 else "(none)"
                elif completed:
                    node_current = "(complete)"
                    node_next = "(none)"
                elif _synthetic_done_by_ip.get(ip):
                    node_current = "(complete)"
                    node_next = "(none)"
                else:
                    node_current = "(not started)"
                    node_next = phase_names[0] if phase_names else "(none)"
                if ip == _primary_ip:
                    _role_label = "primary"
                elif ip in bmc_ips:
                    _role_label = f"secondary-{bmc_ips.index(ip):02d}"
                else:
                    _role_label = "node"
                lines.append(f"  [{_role_label} | {ip}]")
                lines.append(f"      current : {node_current}")
                lines.append(f"      next    : {node_next}")
                lines.append(f"      done    : {', '.join(display_done) or '(none)'}")
                if pending:
                    lines.append(f"      pending : {', '.join(pending)}")

        return "\n".join(lines)

    # ── Accessors ───────────────────────────────────────────────────────────

    @property
    def mode(self) -> str:
        return self._data.get("mode", "")

    @property
    def log_dir(self) -> str:
        return self._data.get("log_dir", "")

    @property
    def config_path(self) -> str:
        return self._data.get("config_path", "")

    @property
    def bmc_ips(self) -> "list[str]":
        return list(self._data.get("bmc_ips", []))

    @property
    def created(self) -> str:
        return self._data.get("created", "")

    def set_param(self, key: str, value) -> None:
        """Store an arbitrary non-sensitive run parameter. Saved immediately."""
        with self._data_lock:
            self._data.setdefault("params", {})[key] = value
        self._save()

    def get_param(self, key: str, default=None):
        """Retrieve a stored run parameter, or *default* if not present."""
        return self._data.get("params", {}).get(key, default)

    def resume_run(self, mode: str, log_dir: str = "") -> None:
        """Update metadata for a resumed run without clearing phase data."""
        with self._data_lock:
            self._data["mode"] = mode
            if log_dir:
                self._data["log_dir"] = log_dir
            self._data["current_phase"] = {
                "name": "Resume initialization",
                "state": "in_progress",
                "next_phase": "(pending completion of current phase)",
                "node_ip": "",
                "ts": datetime.now().isoformat(),
            }
        self._save()

    # ── Selection persistence (for operator choices like AutoSupport, physical zeroing, etc.)

    def set_selection(self, key: str, value: "bool | None") -> None:
        """Store an operator selection (e.g., AutoSupport y/n) for re-use on resume."""
        if key:
            with self._data_lock:
                self._data.setdefault("selections", {})[key] = value
            self._save()

    def get_selection(self, key: str) -> "bool | None":
        """Retrieve a stored operator selection, or None if not set."""
        return self._data.get("selections", {}).get(key)

    def get_saved_selections(self) -> "dict[str, bool | None]":
        """Return dict of all saved selections."""
        return self._data.get("selections", {})

    def _get_mode_filtered_selections(self, operation_mode: int = None) -> "dict[str, bool | None]":
        """Return saved selections filtered for the current operation mode."""
        _selections = dict(self.get_saved_selections() or {})
        if operation_mode == 2:
            _selections.pop("setup_passwordless_ssh", None)
        return _selections

    def has_saved_selections(self, operation_mode: int = None) -> bool:
        """Return True if any selections are saved."""
        return bool(any(v is not None for v in self._get_mode_filtered_selections(operation_mode).values()))

    def print_saved_selections_summary(self, operation_mode: int = None) -> None:
        """Print a formatted summary of all saved selections."""
        selections = self._get_mode_filtered_selections(operation_mode)
        if not selections or not any(v is not None for v in selections.values()):
            return
        
        print("\n  📋 Saved operator selections from previous run:")
        print("  " + "─" * 56)
        
        label_map = {
            "enable_autosupport": "AutoSupport after reinit",
            "physical_zeroing": "Physical disk zeroing",
            "prevent_bios_fw_update": "BIOS firmware update prevention",
            "setup_passwordless_ssh": "Passwordless SSH setup",
            "netboot_before_reinit": "Install ONTAP version before reinit",
            "loader_env_stage_enabled": "LOADER env backup (printenv capture)",
            "skip_loader_env_backup": "Skip LOADER env backup",
        }
        
        for key, label in label_map.items():
            val = selections.get(key)
            if val is not None:
                val_str = "✅ enabled" if val else "❌ disabled"
                print(f"    {label:<45} {val_str}")
        
        print("  " + "─" * 56)

    # ── Internal ────────────────────────────────────────────────────────────

    def _save(self, mutator=None) -> bool:
        tmp = (
            f"{self._path}.{os.getpid()}."
            f"{threading.get_ident()}.{time.time_ns()}.tmp"
        )
        try:
            with _checkpoint_io_lock:
                with self._data_lock:
                    if callable(mutator) and not bool(mutator(self._data)):
                        return False
                    self._data["updated"] = datetime.now().isoformat()
                    _payload = copy.deepcopy(self._data)
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump(_payload, f, indent=2)
                    f.write("\n")
                os.replace(tmp, self._path)
        except Exception as exc:
            with suppress(Exception):
                if os.path.exists(tmp):
                    os.remove(tmp)
            raise RuntimeError(
                f"Checkpoint save failed for {self._path}: {exc}"
            ) from exc
        return True


def _handle_checkpoint_confirmation_with_selective_mod(checkpoint, diag_mode=False, operation_mode=None):
    """
    Handle checkpoint confirmation with optional selective modification.
    
    Returns: tuple of (selections_dict, was_modified)
      - selections_dict: dict of all selections (with values or None)
      - was_modified: bool indicating if operator chose to modify any selections
    
    Flow:
      1. If checkpoint has saved selections, show summary
      2. Ask: "Keep these selections? [Y/n/c]"
         - Y = Use all saved
         - N = Re-answer all (clear all, return as modified)
         - C = Selective modification (show menu, return as modified)
    """
    if not checkpoint or not checkpoint.has_saved_selections(operation_mode):
        return None, False
    
    checkpoint.print_saved_selections_summary(operation_mode)
    
    while True:
        _choice = _prompt(
            "  Keep these selections and continue? [Y/n/c] (c = change): ", "y"
        ).strip().lower()
        
        if _choice in ("y", "yes", ""):
            # Use all saved selections
            print("\n  ✅ Using saved selections. Proceeding...\n")
            saved = checkpoint._get_mode_filtered_selections(operation_mode)
            if diag_mode:
                _diag_bootargs = _load_diag_bootargs()
            return saved, False
        
        elif _choice in ("n", "no"):
            # Clear all and re-prompt
            print("\n  ℹ️   Clearing saved selections. Please answer the questions again:\n")
            for key in checkpoint.get_saved_selections().keys():
                checkpoint.set_selection(key, None)
            return {}, True
        
        elif _choice in ("c", "customize"):
            # Selective modification
            return _handle_selective_modification(checkpoint, diag_mode, operation_mode), True
        
        else:
            print("  Please enter Y, N, or C.")


def _handle_selective_modification(checkpoint, diag_mode=False, operation_mode=None):
    """
    Show a menu for selective modification of checkpoint selections.
    Operator can choose which selections to keep and which to re-enter.
    
    Returns: dict of selections (values that weren't cleared)
    """
    print("\n  📋 Selective modification - choose which selections to keep:")
    print("  " + "─" * 56)
    
    label_map = {
        "enable_autosupport": "AutoSupport after reinit",
        "physical_zeroing": "Physical disk zeroing",
        "prevent_bios_fw_update": "BIOS firmware update prevention",
        "setup_passwordless_ssh": "Passwordless SSH setup",
        "netboot_before_reinit": "Install ONTAP version before reinit",
        "loader_env_stage_enabled": "LOADER env backup (printenv capture)",
        "skip_loader_env_backup": "Skip LOADER env backup",
    }
    
    selections = checkpoint._get_mode_filtered_selections(operation_mode)
    keys_to_show = [k for k, v in selections.items() if v is not None]
    
    if not keys_to_show:
        print("  No saved selections to modify.")
        return {}
    
    menu_items = []
    for idx, key in enumerate(keys_to_show, 1):
        val = selections[key]
        val_str = "✅" if val else "❌"
        label = label_map.get(key, key)
        print(f"    {idx}. {label:<40} {val_str}")
        menu_items.append(key)
    
    print("  " + "─" * 56)
    print("  Enter selection numbers to CLEAR (comma-separated, e.g., '1,3,5')")
    print("  or press Enter to keep all: ", end="", flush=True)
    
    try:
        _clear_input = input().strip()
    except (EOFError, KeyboardInterrupt):
        _clear_input = ""
    
    if _clear_input:
        try:
            _clear_indices = [int(x.strip()) for x in _clear_input.split(",")]
            for idx in _clear_indices:
                if 1 <= idx <= len(menu_items):
                    key = menu_items[idx - 1]
                    checkpoint.set_selection(key, None)
                    print(f"    ✓ Cleared: {label_map.get(key, key)}")
        except (ValueError, IndexError):
            print("  Invalid input. Keeping all selections.")
    
    print()
    if diag_mode:
        _diag_bootargs = _load_diag_bootargs()
    
    return checkpoint._get_mode_filtered_selections(operation_mode)


def _format_checkpoint_mode(mode: str) -> str:
    """Return a human-friendly checkpoint mode label for status/summary logs."""
    raw = str(mode or "").strip()
    if not raw:
        return "?"

    display = raw
    desc = ""

    if raw.startswith("4.2-"):
        suffix = raw.split("-", 1)[1]
        if suffix == "3":
            display = "4.2+3"
            desc = "Netboot install + automated cluster reinit"
        elif suffix == "1":
            display = "4.2+1"
            desc = "Netboot install + interactive first-node reinit"
        elif suffix == "no-reinit":
            display = "4.2"
            desc = "Netboot install only (no reinit)"
        else:
            display = f"4.2+{suffix}"
            desc = "Netboot install + reinit"
    elif raw.startswith("4.3-"):
        suffix = raw.split("-", 1)[1]
        if suffix == "no-reinit":
            display = "4.3"
            desc = "Netboot install image only (no reinit)"
        else:
            display = f"4.3+{suffix}"
            desc = "Netboot install image path"
    else:
        desc = {
            "1": "Initialize first node",
            "2": "Add node to existing cluster",
            "3": "End-to-end auto initialize",
            "4.1": "ONTAP upgrade",
            "4.2": "Netboot install",
            "4.3": "Netboot install image only",
        }.get(raw, "")

    return f"{display} ({desc})" if desc else display


# Module-level checkpoint instance (initialised by _run_4b_standalone on each
# run; may be loaded from disk on resume).
_checkpoint: "CheckpointManager | None" = None


# Boot-menu detection signatures shared by all wait-for-boot-menu callers.
_BOOT_MENU_SIGS = [
    "selection (1-9)?",
    "boot menu",
    "please choose one of the following boot options",
    "option",
]

# Unique substring that appears in the BMC shell prompt (e.g. "node-bmc>").
# Used to detect accidental console drops mid-wait.
_BMC_PROMPT_SIG = "bmc>"

# Message the SP/BMC sends when it kills our session to hand control to
# another user or higher-priority session.
_BMC_PREEMPTED_SIG = "this cli session is being preempted"

# Regex that matches any bare BMC/SP shell prompt on its own line.
# Covers: "bmc>", "localhost>", "node-bmc>", "rtp-afx1k-c01-01>", etc.
# Pattern: optional whitespace, then one or more word/hyphen/dot chars, then ">",
# then optional whitespace/CR/LF — and nothing else meaningful on that line.
_BMC_PROMPT_RE = re.compile(
    r'(?:^|\r|\n)\s*[\w][\w\-\.]*>\s*(?:\r|\n|$)',
    re.MULTILINE,
)


def _looks_like_bmc_drop(chunk: str) -> bool:
    """Return True if *chunk* contains what appears to be a bare BMC/SP shell
    prompt or a session-preemption notice — indicating that system console has
    exited and the channel has dropped back to the BMC CLI, or that the SP has
    forcibly ended our session.

    Matches:
      - Any token ending in ``>`` that contains ``bmc`` (e.g. ``node-bmc>``)
      - ``localhost>``
      - Any short token matching ``word[-word]*>`` on its own line (e.g.
        ``rtp-afx1k-c01-01>``) — the regex guards against false positives from
        ONTAP CLI output (``::>``, ``*>``, ``(X)>`` etc.) by requiring the line
        to contain only the prompt token.
      - "This CLI session is being preempted by another user/session"
    """
    cl = chunk.lower()
    # LOADER prompts are part of the normal console path and must never be
    # treated as a drop back to the BMC shell.
    if _LOADER_PROMPT_RE.search(chunk) or "loader-" in cl:
        return False
    # Session preemption notice — SP is kicking us out
    if _BMC_PREEMPTED_SIG in cl:
        return True
    # Fast path: explicit "bmc" substring
    if _BMC_PROMPT_SIG in cl:
        return True
    # Fast path: localhost> (common SP hostname)
    if "localhost>" in cl:
        return True
    # General: any bare word> on its own line (covers node-name prompts)
    return bool(_BMC_PROMPT_RE.search(chunk))

