def _clear_checkpoint_test_config() -> None:
    global _checkpoint_test_enabled, _checkpoint_test_target
    global _checkpoint_test_mode_label, _checkpoint_test_consumed
    global _pending_checkpoint_test_failure, _checkpoint_test_failure_handled
    global _checkpoint_test_parallel_expected_nodes, _checkpoint_test_parallel_seen_nodes
    global _checkpoint_test_targets_by_node, _checkpoint_test_mode3_abort_phase
    _checkpoint_test_enabled = False
    _checkpoint_test_target = ""
    _checkpoint_test_mode_label = ""
    _checkpoint_test_consumed = False
    _pending_checkpoint_test_failure = None
    _checkpoint_test_failure_handled = False
    _checkpoint_test_parallel_expected_nodes = set()
    _checkpoint_test_parallel_seen_nodes = set()
    _checkpoint_test_targets_by_node = {}
    _checkpoint_test_mode3_abort_phase = ""


def _set_checkpoint_test_parallel_scope(node_ids) -> None:
    """Configure node IDs that must hit the injected checkpoint in parallel runs."""
    global _checkpoint_test_parallel_expected_nodes, _checkpoint_test_parallel_seen_nodes
    _nodes = set()
    for _nid in (node_ids or []):
        _clean = str(_nid).strip()
        if not _clean:
            continue
        _identity = _checkpoint_test_node_identity(_clean) or _clean
        _nodes.add(_identity)
    with _checkpoint_test_lock:
        _per_node_targets = dict(_checkpoint_test_targets_by_node)
        if not _checkpoint_test_enabled or _checkpoint_test_consumed:
            _checkpoint_test_parallel_expected_nodes = set()
            _checkpoint_test_parallel_seen_nodes = set()
            return
        if _per_node_targets:
            # Per-node injection is a "first target hit wins" trigger. Do not
            # wait for all targeted nodes when checkpoints differ by node.
            _checkpoint_test_parallel_expected_nodes = set()
            _checkpoint_test_parallel_seen_nodes = set()
            return
        else:
            if not _checkpoint_test_target or len(_nodes) <= 1:
                _checkpoint_test_parallel_expected_nodes = set()
                _checkpoint_test_parallel_seen_nodes = set()
                return
            _checkpoint_test_parallel_expected_nodes = set(_nodes)
            _checkpoint_test_parallel_seen_nodes = set()
    if _checkpoint_test_targets_by_node:
        _mapping = ", ".join(
            f"{_nid}:{_checkpoint_test_target_for_node(_nid, _checkpoint_test_targets_by_node)}"
            for _nid in sorted(_checkpoint_test_parallel_expected_nodes)
        )
        _slog(
            f"--test parallel scope armed for per-node checkpoints: {_mapping}",
            prefix="INFO",
        )
    else:
        _slog(
            f"--test parallel scope armed for checkpoint '{_checkpoint_test_target}': "
            f"{sorted(_nodes)}",
            prefix="INFO",
        )


def _checkpoint_phase_description(phase: str) -> str:
    """Return the human-readable description for a checkpoint phase ID."""
    _phase = str(phase or "").strip()
    if not _phase:
        return ""
    _mode_options = list(_CHECKPOINT_TEST_OPTIONS.get(_operation_mode) or [])
    for _cp_id, _label in _mode_options:
        if _cp_id == _phase:
            return _label
    # Fallback for cross-mode/common phases when mode context is unavailable.
    for _opts in _CHECKPOINT_TEST_OPTIONS.values():
        for _cp_id, _label in _opts:
            if _cp_id == _phase:
                return _label
    return ""


def _checkpoint_test_mode_name(operation_mode: int) -> str:
    return {
        1: "1",
        2: "2",
        3: "3",
        41: "4.1",
        42: "4.2",
        43: "4.3",
    }.get(operation_mode, str(operation_mode))


def _describe_4b_resume_stage(cp) -> str:
    """Return a human-readable resume stage summary for a 4.2 checkpoint."""
    if not cp:
        return "Start of 4.2 workflow (no checkpoint context)."

    _bmc_ips = list(getattr(cp, "bmc_ips", []) or [])
    _install_done = set(_checkpoint_4x_nodes_done_for_runtime_phase(cp, "install_done"))
    _opt6_done = set(_checkpoint_4x_nodes_done_for_runtime_phase(cp, "option6_done"))
    _install_equiv = _install_done | _opt6_done
    _reinit_loader = set(_checkpoint_4x_nodes_done_for_runtime_phase(cp, "reinit_loader"))
    _peer_opt4_done = set(cp.nodes_done_for("peer_option4_done"))
    _peer_joined = set(cp.nodes_done_for("peer_joined"))
    _remaining_install = [ip for ip in _bmc_ips if ip not in _install_equiv]

    if cp.is_done("cluster_formed") or cp.is_done("option3_complete"):
        return "Cluster setup already completed in prior run."

    if cp.is_done("primary_node_mgmt_done") and not cp.is_done("primary_setup_done"):
        return "Primary cluster setup wizard (resume without install replay)."

    if cp.is_done("primary_bootmenu_done") and not cp.is_done("primary_node_mgmt_done"):
        return "Primary node-management prompts in cluster setup wizard."

    if _bmc_ips and not _remaining_install:
        if _peer_opt4_done and len(_peer_joined) < len(_peer_opt4_done):
            return "Peer add-node completion in mode 3 (some peers already prepared)."
        if _reinit_loader:
            return "Reinit boot-menu / cluster initialization stage."
        return "Reinit reconnect stage (install steps already complete for all nodes)."

    if _remaining_install and len(_remaining_install) < len(_bmc_ips):
        return (
            "Netboot/install continuation for remaining node(s): "
            + ", ".join(_remaining_install)
        )

    if _reinit_loader:
        return "Reinit reconnect continuation to LOADER on remaining nodes."

    return "Netboot install phase (pre-option-6 completion)."


_MODE3_PRIMARY_CHECKPOINT_NODE = "node_primary"


def _mode3_peer_checkpoint_node(ip: str) -> str:
    return f"node_peer:{ip}"


def _checkpoint_test_node_aliases(node_id: str) -> "list[str]":
    _node = str(node_id or "").strip()
    if not _node:
        return []
    if _node == _MODE3_PRIMARY_CHECKPOINT_NODE:
        return [_node]
    if _node.startswith("node_peer:"):
        _raw = str(_node.split(":", 1)[1] or "").strip()
        if not _raw:
            return [_node]
        return [_raw, _mode3_peer_checkpoint_node(_raw)]
    return [_node, _mode3_peer_checkpoint_node(_node)]


def _checkpoint_test_node_identity(node_id: str) -> str:
    for _alias in _checkpoint_test_node_aliases(node_id):
        if _alias and _alias != _MODE3_PRIMARY_CHECKPOINT_NODE and not _alias.startswith("node_peer:"):
            return _alias
    _aliases = _checkpoint_test_node_aliases(node_id)
    return _aliases[0] if _aliases else ""


def _checkpoint_test_target_for_node(node_id: str, targets=None) -> str:
    _targets = targets if isinstance(targets, dict) else _checkpoint_test_targets_by_node
    if not isinstance(_targets, dict):
        return ""
    for _alias in _checkpoint_test_node_aliases(node_id):
        _target = str(_targets.get(_alias) or "").strip()
        if _target:
            return _target
    return ""


def _checkpoint_test_arm_mode3_abort_barrier(phase: str, node_id: str = "") -> None:
    global _checkpoint_test_mode3_abort_phase
    _phase = str(phase or "").strip()
    _node = str(node_id or "").strip()
    if _operation_mode == 3 and _phase == "cp_1_5" and _node == _MODE3_PRIMARY_CHECKPOINT_NODE:
        if _checkpoint_test_mode3_abort_phase == _phase:
            return
        _checkpoint_test_mode3_abort_phase = _phase
        _slog(
            "mode 3 checkpoint abort barrier armed at cp_1_5; later peer cp_2_* markers will be skipped",
            prefix="WARN",
        )


def _checkpoint_test_should_arm_mode3_abort_barrier_for_commit(phase: str, node_id: str = "") -> bool:
    _phase = str(phase or "").strip()
    _node_id = str(node_id or "").strip()
    if _operation_mode != 3 or _phase != "cp_1_5" or _node_id != _MODE3_PRIMARY_CHECKPOINT_NODE:
        return False
    if not _checkpoint_test_enabled or _checkpoint_test_consumed:
        return False

    _node_target = ""
    if _checkpoint_test_targets_by_node and _node_id:
        _node_target = _checkpoint_test_target_for_node(_node_id, _checkpoint_test_targets_by_node)
    _active_target = _node_target or str(_checkpoint_test_target or "").strip()
    if not _active_target or _phase != _active_target:
        return False

    with _checkpoint_test_lock:
        if (not _checkpoint_test_enabled
                or _checkpoint_test_consumed
                or _phase != (_node_target or _checkpoint_test_target)):
            return False
        _parallel_expected = set(_checkpoint_test_parallel_expected_nodes)
        if not _parallel_expected:
            return True
        _node_identity = _checkpoint_test_node_identity(_node_id) or _node_id
        _seen_after_commit = set(_checkpoint_test_parallel_seen_nodes)
        _seen_after_commit.add(_node_identity)
        return not (_parallel_expected - _seen_after_commit)


def _checkpoint_test_prepare_mode3_abort_barrier(phase: str, node_id: str = "") -> None:
    if _checkpoint_test_should_arm_mode3_abort_barrier_for_commit(phase, node_id):
        _checkpoint_test_arm_mode3_abort_barrier(phase, node_id)


def _checkpoint_test_should_block_mode3_peer_checkpoint(phase: str, node_id: str = "",
                                                        alias_phase: str = "", alias_node_id: str = "") -> bool:
    if _operation_mode != 3 or _checkpoint_test_mode3_abort_phase != "cp_1_5":
        return False
    _phase = str(phase or "").strip()
    _alias_phase = str(alias_phase or "").strip()
    if not (_phase.startswith("cp_2_") or _alias_phase in ("peer_option4_done", "peer_joined")):
        return False
    _aliases = _checkpoint_test_node_aliases(node_id) + _checkpoint_test_node_aliases(alias_node_id)
    return any(_alias and _alias != _MODE3_PRIMARY_CHECKPOINT_NODE for _alias in _aliases)


def _checkpoint_phase_done(phase: str, node_id: str = "") -> bool:
    if not _checkpoint:
        return False
    try:
        return _checkpoint.is_node_done(phase, node_id) if node_id else _checkpoint.is_done(phase)
    except Exception:
        return False


def _checkpoint_node_phase_ts(checkpoint, phase: str, node_id: str) -> str:
    """Return the ISO timestamp string stored with a node phase, or '' if absent."""
    if not checkpoint:
        return ""
    try:
        return str(
            checkpoint._data
            .get("node_phases", {})
            .get(str(phase or ""), {})
            .get(str(node_id or ""), {})
            .get("ts") or ""
        )
    except Exception:
        return ""


def _checkpoint_phase_resume_evidence_for_peer(checkpoint, phase: str, bmc_ip: str) -> str:
    """Return concrete persisted evidence for a peer-resume compatibility match."""
    if not checkpoint:
        return ""
    _phase = str(phase or "").strip()
    _bmc = str(bmc_ip or "").strip()
    if not _phase:
        return ""

    _node_ids = []
    if _bmc:
        _node_ids.append(_bmc)
        _mode3_peer_id = _mode3_peer_checkpoint_node(_bmc)
        if _mode3_peer_id not in _node_ids:
            _node_ids.append(_mode3_peer_id)

    # Timestamp of the most recent option-4 reinit for this BMC (if any).
    # Used below to detect stale post-reinit marks on the node_peer key.
    _opt4_ts = _checkpoint_node_phase_ts(checkpoint, "peer_option4_done", _bmc) if _bmc else ""

    def _match_phase(_phase_name: str) -> str:
        _phase_name = str(_phase_name or "").strip()
        if not _phase_name:
            return ""
        for _nid in _node_ids:
            try:
                if checkpoint.is_node_done(_phase_name, _nid):
                    # cp_2_5/cp_2_6 on the node_peer key may be stale: they
                    # could have been written by a previous run before the node
                    # was re-wiped by option 4.  Discard if peer_option4_done
                    # on the BMC key is newer, meaning a more recent wipe event
                    # happened after those marks were written.
                    if (
                        _opt4_ts
                        and _nid != _bmc
                        and _phase_name in ("cp_2_5", "cp_2_6")
                    ):
                        _phase_ts = _checkpoint_node_phase_ts(checkpoint, _phase_name, _nid)
                        if _phase_ts and _opt4_ts > _phase_ts:
                            continue  # stale pre-wipe evidence — skip
                    return f"checkpoint:{_phase_name}"
            except Exception:
                pass
        try:
            if checkpoint.is_done(_phase_name):
                return f"checkpoint:{_phase_name}"
        except Exception:
            pass
        return ""

    _phase_evidence = _match_phase(_phase)
    if _phase_evidence:
        return _phase_evidence

    _aliases = {
        "cp_2_4": "peer_option4_done",
        "cp_2_7": "peer_joined",
    }
    _alias = _aliases.get(_phase, "")
    if _alias:
        return _match_phase(_alias)
    return ""


def _checkpoint_phase_done_for_peer_resume(phase: str, bmc_ip: str) -> bool:
    """Checkpoint done check tolerant of legacy/global mode-2 resume markers."""
    if not _checkpoint:
        return False
    return bool(_checkpoint_phase_resume_evidence_for_peer(_checkpoint, phase, bmc_ip))


def _checkpoint_mark_phase(phase: str, node_id: str = "", *, alias_phase: str = "",
                           alias_node_id: str = "", promote_global: bool = False,
                           target_node_ids=None) -> bool:
    if not _checkpoint:
        return False
    marked = False
    blocked = False
    _block_mode3_peer_checkpoint = globals().get("_checkpoint_test_should_block_mode3_peer_checkpoint")
    _prepare_mode3_abort_barrier = globals().get("_checkpoint_test_prepare_mode3_abort_barrier")

    def _node_phase_done_in_data(data, phase_name: str, phase_node_id: str) -> bool:
        return bool(
            data.get("node_phases", {})
                .get(phase_name, {})
                .get(phase_node_id, {})
                .get("done")
        )

    def _global_phase_done_in_data(data, phase_name: str) -> bool:
        return bool(data.get("phases", {}).get(phase_name, {}).get("done"))

    def _mark_phase_in_data(data, phase_name: str, phase_node_id: str, ts_value: str) -> bool:
        if phase_node_id:
            if _node_phase_done_in_data(data, phase_name, phase_node_id):
                return False
            data.setdefault("node_phases", {}).setdefault(phase_name, {})[phase_node_id] = {
                "done": True,
                "ts": ts_value,
            }
            return True
        if _global_phase_done_in_data(data, phase_name):
            return False
        data.setdefault("phases", {})[phase_name] = {
            "done": True,
            "ts": ts_value,
        }
        return True

    def _should_block_phase_commit() -> bool:
        if not callable(_block_mode3_peer_checkpoint):
            return False
        return bool(_block_mode3_peer_checkpoint(
            phase,
            node_id,
            alias_phase=alias_phase,
            alias_node_id=alias_node_id,
        ))

    try:
        def _mutate(data) -> bool:
            nonlocal marked, blocked
            if _should_block_phase_commit():
                blocked = True
                return False

            _ts = datetime.now().isoformat()
            _phase_marked = _mark_phase_in_data(data, phase, node_id, _ts)
            if _phase_marked and callable(_prepare_mode3_abort_barrier):
                _prepare_mode3_abort_barrier(phase, node_id)

            _alias_marked = False
            if alias_phase:
                _alias_marked = _mark_phase_in_data(data, alias_phase, alias_node_id, _ts)

            _promoted_marked = False
            if promote_global:
                _targets = [
                    str(_tid).strip() for _tid in (
                        target_node_ids or getattr(_checkpoint, "bmc_ips", []) or []
                    )
                    if str(_tid).strip(                    )
                ]
                if _targets and all(_node_phase_done_in_data(data, phase, _tid) for _tid in _targets):
                    _promoted_marked = _mark_phase_in_data(data, phase, "", _ts)

            marked = _phase_marked or _promoted_marked
            return bool(_phase_marked or _alias_marked or _promoted_marked)

        _checkpoint._save(mutator=_mutate)
        if blocked:
            _cp_label = f" [{node_id}]" if node_id else ""
            _slog(
                f"mode 3 checkpoint abort barrier active; skipping {phase}{_cp_label}",
                prefix="WARN",
            )
            return False
        if marked:
            _cp_label = f" [{node_id}]" if node_id else ""
            _cp_desc = _checkpoint_phase_description(phase)
            _cp_suffix = f" — {_cp_desc}" if _cp_desc else ""
            _cp_mode_key = _checkpoint_mode_to_test_key(getattr(_checkpoint, "mode", ""))
            _cp_tag = _checkpoint_stage_tag(_cp_mode_key, phase)
            _tag_suffix = f" [{_cp_tag}]" if _cp_tag else ""
            print(f"  ✅ Checkpoint created{_cp_label}: {phase}{_cp_suffix}{_tag_suffix}")
            _slog(f"Checkpoint marked: {phase}{_cp_label}{_cp_suffix}{_tag_suffix}", prefix="INFO")
            _maybe_inject_checkpoint_failure(phase, node_id)
    except _InjectedCheckpointFailure as _e:
        # Test failure injection: exit gracefully to menu instead of crashing.
        # Clear the global pending failure and set the "already handled" flag so
        # _raise_pending_checkpoint_failure() in the main thread (e.g. after joining
        # pipeline peer threads) does not double-fire the same message.
        global _pending_checkpoint_test_failure, _checkpoint_test_failure_handled
        _pending_checkpoint_test_failure = None
        _checkpoint_test_failure_handled = True
        _shutdown_event.set()
        _msg = f"  ↩️  Test checkpoint failure reached - returning to main menu.\n    {_e}"
        print(f"\n{_msg}")
        _slog(_msg, prefix="INFO")
        raise _ReturnToMenu
    except Exception as _cp_exc:
        _cp_label = f" [{node_id}]" if node_id else ""
        _warn = f"Checkpoint save failed for {phase}{_cp_label}: {_cp_exc}"
        print(f"  ⚠️  {_warn}")
        _slog(_warn, prefix="WARN")
        if _session_log:
            with suppress(Exception):
                _session_log.log(_warn, prefix="WARN")
    return marked


def _run_optional_checkpoint_status_checks() -> None:
    for _func_name in ("_check_node_boot_status", "_prompt_checkpoint_continuation"):
        _func = globals().get(_func_name)
        if callable(_func):
            with suppress(Exception):
                _func()


def _checkpoint_test_secondary_nodes_for_mode(operation_mode: int) -> "list[str]":
    """Return candidate per-node --test targets from manifest/runtime state."""
    _nodes = []
    _cfg = globals().get("_config_data")
    if isinstance(_cfg, dict):
        _primary, _secondary = _extract_bmc_lists_from_config_dict(_cfg)
        _cfg_candidates = list(_secondary)
        if operation_mode in (42, 43):
            if _primary:
                _cfg_candidates = [_primary] + _cfg_candidates
        for _bmc in _cfg_candidates:
            _b = str(_bmc).strip()
            if _b and _b not in _nodes:
                _nodes.append(_b)
    for _bmc in (globals().get("_peer_bmc_list") or []):
        _b = str(_bmc).strip()
        if _b and _b not in _nodes:
            _nodes.append(_b)
    if operation_mode == 2:
        for _bmc in (globals().get("other_sps") or []):
            _b = str(_bmc).strip()
            if _b and _b not in _nodes:
                _nodes.append(_b)
    return _nodes


def _checkpoint_injection_min_allowed_index(options, resume_cp=None) -> "tuple[int, str]":
    """Return the earliest checkpoint index allowed for --test injection."""
    _opts = list(options or [])
    if not _opts:
        return 1, ""
    if not resume_cp:
        return 1, ""
    _next_id = str(_checkpoint_resume_phase_id(resume_cp) or "").strip()
    if not _next_id:
        return len(_opts) + 1, "checkpoint is already complete"
    for _idx, (_cp_id, __) in enumerate(_opts, 1):
        if _cp_id == _next_id:
            return _idx, f"resume start is {_next_id}"
    return 1, ""


def _primary_checkpoint_options(operation_mode: int) -> list:
    """Return only cp_1_x (primary-node) checkpoint options for the given mode.

    Falls back to the full list when the mode has no cp_1_x entries (e.g. mode 2
    which is entirely cp_2_x peer phases) so the list is never empty.
    """
    all_opts = list(_CHECKPOINT_TEST_OPTIONS.get(operation_mode) or [])
    primary_only = [(cp_id, cp_desc) for cp_id, cp_desc in all_opts if cp_id.startswith("cp_1_")]
    return primary_only if primary_only else all_opts


def _peer_checkpoint_options(operation_mode: int) -> list:
    """Return only cp_2_x (peer-applicable) checkpoint options for the given mode."""
    return [
        (cp_id, cp_desc)
        for cp_id, cp_desc in (_CHECKPOINT_TEST_OPTIONS.get(operation_mode) or [])
        if cp_id.startswith("cp_2_")
    ]


def _configure_per_node_checkpoint_injection(mode_name: str, options, node_ids,
                                             min_allowed_index: int = 1,
                                             peer_only: bool = False) -> bool:
    """Interactive helper for per-node --test checkpoint injection selection."""
    global _checkpoint_test_enabled, _checkpoint_test_target, _checkpoint_test_mode_label
    global _checkpoint_test_targets_by_node

    _nodes = [str(_nid).strip() for _nid in (node_ids or []) if str(_nid).strip()]
    if len(_nodes) <= 1:
        return False

    _node_label = "secondary node" if peer_only else "node"
    _nodes_label = "secondary nodes" if peer_only else "listed nodes"
    print(f"\n  P-mode: choose checkpoint injection strategy for individual {_node_label}s.")
    print(f"  1. Select a checkpoint per {_node_label}")
    print(f"  2. Select one checkpoint and apply it to all {_nodes_label}")
    _mode_sel = _prompt("  Strategy [1/2]: ", "1").strip()
    if _mode_sel not in ("1", "2"):
        print("  ⚠️  Invalid strategy.")
        return False

    _target_map = {}
    _min_idx = max(1, int(min_allowed_index or 1))

    if _mode_sel == "2":
        print("")
        for _idx, (_phase, _label) in enumerate(options, 1):
            print(f"  {_idx}. {_phase:<22} {_label}")
        _idx_raw = _prompt(
            f"  Checkpoint index for all nodes [{_min_idx}-{len(options)}]: ",
            str(_min_idx),
        ).strip()
        if not _idx_raw.isdigit():
            print("  ⚠️  Enter a valid checkpoint number.")
            return False
        _idx = int(_idx_raw)
        if not (_min_idx <= _idx <= len(options)):
            print("  ⚠️  Out of range.")
            return False
        _phase, _label = options[_idx - 1]
        for _nid in _nodes:
            _target_map[_nid] = _phase
        print(f"  ✅ All nodes mapped to '{_phase}' ({_label}).")
    else:
        _global_fallback = str(_checkpoint_test_target or "").strip()
        _global_fallback_idx = 0
        if _global_fallback:
            for _gi, (_gph, __) in enumerate(options, 1):
                if _gph == _global_fallback:
                    _global_fallback_idx = _gi
                    break
        _enter_hint = (
            f"Enter={_global_fallback_idx} (global {_global_fallback})"
            if _global_fallback_idx else "0=skip"
        )
        print(f"  Enter checkpoint index per node ({_enter_hint}, 0=skip).")
        for _nid in _nodes:
            print("")
            for _idx, (_phase, _label) in enumerate(options, 1):
                print(f"  {_idx}. {_phase:<22} {_label}")
            _idx_raw = _prompt(
                f"    {_nid} checkpoint [0-{len(options)}, Enter={_global_fallback_idx or 0}]: ",
                str(_global_fallback_idx) if _global_fallback_idx else "0",
            ).strip()
            if not _idx_raw.isdigit():
                print(f"  ⚠️  Skipping {_nid} (invalid input).")
                continue
            _idx = int(_idx_raw)
            if _idx == 0:
                continue
            if _idx < _min_idx:
                print(
                    f"  ⚠️  Skipping {_nid} (checkpoint {_idx} is before "
                    f"resume start index {_min_idx})."
                )
                continue
            if 1 <= _idx <= len(options):
                _target_map[_nid] = options[_idx - 1][0]
            else:
                print(f"  ⚠️  Skipping {_nid} (out of range).")

    if not _target_map:
        print("  ⚠️  No per-node checkpoints selected.")
        return False

    _checkpoint_test_enabled = True
    # When peer_only=True, this configures secondary nodes only. Preserve the
    # global _checkpoint_test_target so the primary node (which is not in the
    # per-node map) can still fire its own injection via the global fallback.
    if not peer_only:
        _checkpoint_test_target = ""
    _checkpoint_test_mode_label = mode_name
    _checkpoint_test_targets_by_node = dict(_target_map)
    _global_note = (
        f"; primary global target '{_checkpoint_test_target}' preserved"
        if peer_only and _checkpoint_test_target else ""
    )
    _slog(
        f"--test armed for mode {mode_name}: per-node checkpoints "
        f"{dict(sorted(_target_map.items()))}{_global_note}"
    )
    print("  ✅ Per-node checkpoint failure injection configured:")
    for _nid in sorted(_target_map):
        _cp_id = _target_map[_nid]
        _cp_desc = _checkpoint_phase_description(_cp_id)
        _cp_label = f"{_cp_id} {_cp_desc}".strip()
        print(f"     - {_nid}: {_cp_label}")
    if peer_only and _checkpoint_test_target:
        _primary_desc = _checkpoint_phase_description(_checkpoint_test_target)
        _primary_label = f"{_checkpoint_test_target} {_primary_desc}".strip()
        print(f"  ℹ️  Primary node will still inject at '{_primary_label}' (global target preserved).")
    print("  ℹ️  Failure fires when the first targeted node reaches its configured checkpoint.")
    return True


def _maybe_offer_per_node_checkpoint_injection_upgrade(operation_mode: int, node_ids) -> None:
    """Configure per-node --test injection once multi-node scope is known.

    Called right after the node list is available (config load / peer detection).
    Skips the 'keep global or configure per-node?' dialog — goes directly into
    per-node config so the admin is prompted immediately after the global pick.
    """
    global _checkpoint_test_enabled, _checkpoint_test_target
    global _checkpoint_test_mode_label, _checkpoint_test_targets_by_node
    if operation_mode not in (2, 3, 42, 43):
        return
    if not _checkpoint_test_enabled:
        return
    if _checkpoint_test_targets_by_node:
        return
    _global_target = str(_checkpoint_test_target or "").strip()
    if not _global_target:
        return
    _nodes = []
    for _nid in (node_ids or []):
        _clean = str(_nid).strip()
        if _clean and _clean not in _nodes:
            _nodes.append(_clean)
    if len(_nodes) <= 1:
        return

    _options = list(_CHECKPOINT_TEST_OPTIONS.get(operation_mode) or [])
    if not _options:
        return
    _mode_name = _checkpoint_test_mode_name(operation_mode)

    # For secondary-node-only contexts (modes 3/2 where these are peer BMCs),
    # filter the checkpoint list to only cp_2_x entries — primary cp_1_x phases
    # don't apply to secondary nodes.
    _peer_only = operation_mode in (2, 3)
    _peer_opts = _peer_checkpoint_options(operation_mode) if _peer_only else _options
    if not _peer_opts:
        _peer_opts = _options
        _peer_only = False

    _resume_cp_for_override = None
    _min_allowed_idx = 1
    try:
        _resume_cp_for_override = CheckpointManager()
        if _resume_cp_for_override.load():
            _resume_mode_key = _checkpoint_mode_to_test_key(_resume_cp_for_override.mode)
            if _resume_mode_key == operation_mode:
                _min_allowed_idx, _ = _checkpoint_injection_min_allowed_index(
                    _peer_opts, _resume_cp_for_override
                )
    except Exception:
        _resume_cp_for_override = None

    print(f"\n  🧪 {len(_nodes)} secondary nodes detected — configuring per-node checkpoint injection.")
    print(f"  Global checkpoint '{_global_target}' will be replaced by per-node config below.")
    if _peer_only:
        print("  (Only peer checkpoints (cp_2_x) are shown — cp_1_x applies to the primary node only.)")
    print("  (Press Enter at a node prompt to keep the global target for that node, 0 to skip it.)")

    if _configure_per_node_checkpoint_injection(
        _mode_name,
        _peer_opts,
        _nodes,
        min_allowed_index=_min_allowed_idx,
        peer_only=_peer_only,
    ):
        return

    _slog(
        f"--test mode {_mode_name}: keeping global checkpoint "
        f"'{_global_target}' across {len(_nodes)} nodes",
        prefix="INFO",
    )
    print(
        f"  ℹ️  Keeping global checkpoint '{_global_target}' for all nodes "
        "for this run."
    )


def _configure_checkpoint_test_for_mode(operation_mode: int, enabled: bool) -> None:
    """When ``--test`` is enabled, let the operator choose a checkpoint to fail at."""
    global _checkpoint_test_enabled, _checkpoint_test_target, _checkpoint_test_mode_label
    global _checkpoint_test_targets_by_node
    _clear_checkpoint_test_config()
    if not enabled:
        return

    _options = list(_CHECKPOINT_TEST_OPTIONS.get(operation_mode) or [])
    # For modes that include both primary and secondary phases (e.g. mode 3),
    # restrict this global prompt to primary (cp_1_x) checkpoints only.
    # Secondary node checkpoints (cp_2_x) are configured per-node after config loads.
    _primary_opts = _primary_checkpoint_options(operation_mode)
    _has_peer_phases = len(_primary_opts) < len(_options)
    _options = _primary_opts
    _mode_name = _checkpoint_test_mode_name(operation_mode)
    if not _options:
        print(f"\n🧪 --test: no checkpoint failure injection points are available for mode {_mode_name}.")
        return
    _resume_cp_for_override = None
    _resume_cp_available = False
    try:
        _resume_cp_for_override = CheckpointManager()
        if _resume_cp_for_override.load():
            _resume_mode_key = _checkpoint_mode_to_test_key(_resume_cp_for_override.mode)
            _resume_cp_available = (_resume_mode_key == operation_mode)
    except Exception:
        _resume_cp_for_override = None
        _resume_cp_available = False

    _print_banner(f"🧪 Test failure injection ({_mode_name})")
    _allow_menu_escape = operation_mode == 2
    print("\n  Select a checkpoint to fail immediately after it is saved.")
    print("  This is intended to validate resume/checkpoint pickup on the next run.")
    print("  Press Enter with no value to run without failure injection.")
    if _has_peer_phases:
        print("\n  ℹ️  This list covers the primary node only.")
        print("  Secondary node checkpoints (cp_2_x) are configured per-node after config loads.")
    print("")
    print("  0. Disable injected checkpoint failure for this run")
    if _allow_menu_escape:
        print("  M. Return to main menu")
    if _resume_cp_available:
        print("  B. Back to checkpoint resume-stage override")
    _detected_next_id = ""
    _previous_cp_id = ""
    if _resume_cp_available:
        _detected_next_id = str(_checkpoint_resume_phase_id(_resume_cp_for_override) or "").strip()
        if _detected_next_id:
            for _i, (_cp_id, __) in enumerate(_options):
                if _cp_id == _detected_next_id:
                    if _i > 0:
                        _previous_cp_id = _options[_i - 1][0]
                    break
        elif _options:
            _previous_cp_id = _options[-1][0]

    _min_allowed_idx, _min_reason = _checkpoint_injection_min_allowed_index(
        _options, _resume_cp_for_override if _resume_cp_available else None
    )
    if _min_allowed_idx > 1 and _min_allowed_idx <= len(_options):
        _min_cp_id = _options[_min_allowed_idx - 1][0]
        print(
            f"  ℹ️  Injection targets before index {_min_allowed_idx} "
            f"({_min_cp_id}) are blocked ({_min_reason})."
        )
    elif _min_allowed_idx > len(_options):
        print(
            "  ℹ️  No injection targets are eligible at the current resume stage "
            f"({_min_reason})."
        )
    for _idx, (_phase, _label) in enumerate(_options, 1):
        _markers = []
        if _phase == _previous_cp_id:
            _markers.append("previous checkpoint")
        if _phase == _detected_next_id:
            _markers.append("detected next")
        _marker = f"  <- {', '.join(_markers)}" if _markers else ""
        print(f"  {_idx}. {_phase:<22} {_label}{_marker}")

    _prompt_extras = []
    if _resume_cp_available:
        _prompt_extras.append("B")
    if _allow_menu_escape:
        _prompt_extras.append("M")

    while True:
        _sel = _prompt(
            f"\n  Inject failure after checkpoint [0-{len(_options)}"
            f"{', ' + ', '.join(_prompt_extras) if _prompt_extras else ''}] "
            f"(Enter=0/no injection): ",
            "0",
        ).strip()
        if _sel == "":
            _sel = "0"
        if _allow_menu_escape and _sel.lower() == "m":
            print("  ↩️  Returning to main menu...")
            raise _ReturnToMenu
        if _resume_cp_available and _sel.lower() == "b":
            _changed = _prompt_checkpoint_resume_target_override(_resume_cp_for_override)
            if _changed:
                _min_allowed_idx, _min_reason = _checkpoint_injection_min_allowed_index(
                    _options, _resume_cp_for_override
                )
                _slog(
                    f"--test menu: resume-stage override updated before injection "
                    f"(next={_checkpoint_resume_phase_id(_resume_cp_for_override) or 'complete'})"
                )
                if _min_allowed_idx > len(_options):
                    print(
                        "  ℹ️  Resume override currently points beyond the final checkpoint; "
                        "choose B to move it earlier or 0 to disable injection."
                    )
                elif _min_allowed_idx > 1:
                    _min_cp_id = _options[_min_allowed_idx - 1][0]
                    print(
                        f"  ℹ️  Injection floor updated to index {_min_allowed_idx} "
                        f"({_min_cp_id}) based on resume override."
                    )
            continue
        if not _sel.isdigit():
            print("  ⚠️  Enter a number from the list"
                  + ((" or one of: " + ", ".join(_prompt_extras)) if _prompt_extras else "") + ".")
            continue
        _idx = int(_sel)
        if _idx == 0:
            print("  ✅ Checkpoint failure injection disabled for this run.")
            return
        if _idx < _min_allowed_idx:
            if _min_allowed_idx <= len(_options):
                _min_cp_id = _options[_min_allowed_idx - 1][0]
                print(
                    f"  ⚠️  Not allowed: selected checkpoint is earlier than current "
                    f"resume start ({_min_cp_id})."
                )
            else:
                print(
                    "  ⚠️  Not allowed: no eligible injection checkpoints remain at the "
                    "current resume stage. Use B to set an earlier resume checkpoint."
                )
            continue
        if 1 <= _idx <= len(_options):
            _phase, _label = _options[_idx - 1]
            _checkpoint_test_enabled = True
            _checkpoint_test_target = _phase
            _checkpoint_test_mode_label = _mode_name
            _checkpoint_test_targets_by_node = {}
            _slog(f"--test armed for mode {_mode_name}: checkpoint '{_phase}' ({_label})")
            print(f"  ✅ Will fail after checkpoint '{_phase}' is saved.")
            return
        print("  ⚠️  Out of range.")


def _raise_pending_checkpoint_failure() -> None:
    global _pending_checkpoint_test_failure, _checkpoint_test_failure_handled
    if _pending_checkpoint_test_failure is not None:
        _err = _pending_checkpoint_test_failure
        _pending_checkpoint_test_failure = None
        _shutdown_event.set()
        _msg = f"  Test checkpoint failure reached - returning to main menu.\n    {_err}"
        print(f"\n{_msg}")
        _slog(_msg, prefix="INFO")
        raise _ReturnToMenu
    # The failure was already handled (printed and raised) by the 1977 exception
    # handler in a parallel thread (e.g. a pipeline peer).  Still abort the main
    # thread so the run returns to the menu, but skip re-printing the message.
    if _checkpoint_test_failure_handled:
        _checkpoint_test_failure_handled = False
        _shutdown_event.set()
        _slog("injection failure already handled in peer thread; aborting main thread", prefix="INFO")
        raise _ReturnToMenu


def _log_pending_checkpoint_test_target(phase: str, node_id: str = "") -> None:
    """Log test-mode progress when a non-target checkpoint is saved."""
    _phase = str(phase or "").strip()
    if not _phase:
        return
    if not _checkpoint_test_enabled or _checkpoint_test_consumed:
        return
    _node_id = str(node_id or "").strip()
    _target_phase = ""
    if _checkpoint_test_targets_by_node and _node_id:
        _target_phase = _checkpoint_test_target_for_node(_node_id, _checkpoint_test_targets_by_node)
    if not _target_phase:
        _target_phase = str(_checkpoint_test_target or "").strip()
    if not _target_phase or _phase == _target_phase:
        return
    _node_suffix = f" for {_node_id}" if _node_id else ""
    _msg = (
        f"--test armed for checkpoint '{_target_phase}'; "
        f"saved '{_phase}'{_node_suffix}, waiting for target"
    )
    _slog(_msg, prefix="INFO")


def _maybe_inject_checkpoint_failure(phase: str, node_id: str = "") -> None:
    """Abort once when the configured checkpoint phase is saved."""
    global _checkpoint_test_consumed, _pending_checkpoint_test_failure
    global _checkpoint_test_parallel_seen_nodes

    _phase = str(phase or "").strip()
    if not _checkpoint_test_enabled or _checkpoint_test_consumed or not _phase:
        return

    _node_id = str(node_id or "").strip()
    _node_target = ""
    if _checkpoint_test_targets_by_node and _node_id:
        _node_target = _checkpoint_test_target_for_node(_node_id, _checkpoint_test_targets_by_node)
    _active_target = _node_target or str(_checkpoint_test_target or "").strip()
    if not _active_target or _phase != _active_target:
        return

    _pending_err = None
    _fire_msg = ""
    _wait_msg = ""
    with _checkpoint_test_lock:
        if (not _checkpoint_test_enabled
                or _checkpoint_test_consumed
                or _phase != (_node_target or _checkpoint_test_target)):
            return

        _per_node_targets = dict(_checkpoint_test_targets_by_node)
        _parallel_expected = set(_checkpoint_test_parallel_expected_nodes)
        _node_identity = _checkpoint_test_node_identity(_node_id) or _node_id
        _target_desc = _node_target or _phase
        if _node_id and _parallel_expected and _per_node_targets:
            _checkpoint_test_parallel_seen_nodes.add(_node_identity)
            _remaining = sorted(_parallel_expected - _checkpoint_test_parallel_seen_nodes)
            if _remaining:
                _rem = ", ".join(
                    f"{_nid}:{_checkpoint_test_target_for_node(_nid, _per_node_targets) or '?'}"
                    for _nid in _remaining
                )
                _wait_msg = (
                    f"--test checkpoint '{_target_desc}' hit for {_node_id}; "
                    f"waiting for remaining node targets: {_rem}"
                )
            else:
                _checkpoint_test_consumed = True
                _all = ", ".join(
                    f"{_nid}:{_checkpoint_test_target_for_node(_nid, _per_node_targets) or '?'}"
                    for _nid in sorted(_parallel_expected)
                )
                _fire_msg = (
                    f"Injected --test failure after checkpoint '{_target_desc}' "
                    f"was saved for {_node_id} "
                    f"(all targeted per-node checkpoints reached: {_all})"
                )
                _checkpoint_test_arm_mode3_abort_barrier(_phase, _node_id)
                _pending_checkpoint_test_failure = _InjectedCheckpointFailure(_fire_msg)
                _pending_err = _pending_checkpoint_test_failure
        elif _node_id and _parallel_expected:
            _checkpoint_test_parallel_seen_nodes.add(_node_identity)
            _remaining = sorted(_parallel_expected - _checkpoint_test_parallel_seen_nodes)
            if _remaining:
                _wait_msg = (
                    f"--test checkpoint '{_phase}' hit for {_node_id}; "
                    f"waiting for remaining node(s): {', '.join(_remaining)}"
                )
            else:
                _checkpoint_test_consumed = True
                _fire_msg = (
                    f"Injected --test failure after checkpoint '{_phase}' "
                    f"was saved for {_node_id} "
                    f"(all targeted nodes reached: {', '.join(sorted(_parallel_expected))})"
                )
                _checkpoint_test_arm_mode3_abort_barrier(_phase, _node_id)
                _pending_checkpoint_test_failure = _InjectedCheckpointFailure(_fire_msg)
                _pending_err = _pending_checkpoint_test_failure
        else:
            _checkpoint_test_consumed = True
            _fire_msg = f"Injected --test failure after checkpoint '{_phase}' was saved"
            if _node_id:
                _fire_msg += f" for {_node_id}"
            _checkpoint_test_arm_mode3_abort_barrier(_phase, _node_id)
            _pending_checkpoint_test_failure = _InjectedCheckpointFailure(_fire_msg)
            _pending_err = _pending_checkpoint_test_failure

    if _wait_msg:
        _slog(_wait_msg, prefix="INFO")
    if _fire_msg:
        print(f"\n🧪 {_fire_msg}")
        _shutdown_event.set()
        _slog(_fire_msg, prefix="FATAL")
        if _session_log:
            with suppress(Exception):
                _session_log.log(_fire_msg, prefix="FATAL")
    if _pending_err is not None:
        raise _pending_err


def _prompt(prompt: str, default: str = "") -> str:
    """``input(prompt).strip()`` with EOFError/KeyboardInterrupt swallowed.

    Returns ``default`` if the user interrupts (Ctrl+C/Ctrl+D). Whitespace
    is always trimmed from the real input. Callers that need lowercase can
    chain ``.lower()`` on the return value.

    Typing ``menu`` at any prompt raises ``_ReturnToMenu`` which the main
    dispatch loop catches to return to the option selection menu.
    """
    try:
        val = input(prompt).strip()
        if val.lower() == "menu":
            print("  ↩️  Returning to main menu...")
            try:
                input("  Press Enter to return to the main menu...")
            except (EOFError, KeyboardInterrupt):
                pass
            try:
                input("  Press Enter to return to the main menu...")
            except (EOFError, KeyboardInterrupt):
                pass
            raise _ReturnToMenu
        return val
    except (EOFError, KeyboardInterrupt):
        return default


def _prompt_with_timeout(prompt: str, default: str = "", timeout: int = 0) -> str:
    """Prompt with a timeout (seconds), returning ``default`` on timeout.

    Supports ``menu`` escape behavior like ``_prompt``.
    """
    if timeout <= 0:
        return _prompt(prompt, default=default)

    _strict_yn = _prompt_is_yes_no(prompt)
    _yn_default_to = ""
    if _strict_yn:
        _yn_m_to = re.search(r"\[([Yy])/([Nn])\]", str(prompt or ""))
        if _yn_m_to:
            _yn_default_to = "y" if _yn_m_to.group(1).isupper() else "n"
    _deadline = time.monotonic() + timeout
    try:
        while True:
            _remaining = _deadline - time.monotonic()
            if _remaining <= 0:
                print("")
                print(f"  ⏱️  No response in {timeout}s; defaulting to '{default or ''}'.")
                return default

            if os.name != "nt":
                # POSIX: wait for stdin readability, then read one line.
                sys.stdout.write(prompt)
                sys.stdout.flush()
                ready, _, _ = select.select([sys.stdin], [], [], _remaining)
                if not ready:
                    print("")
                    print(f"  ⏱️  No response in {timeout}s; defaulting to '{default or ''}'.")
                    return default
                val = sys.stdin.readline()
                if val == "":
                    return default
                val = val.strip()
            else:
                # Windows console fallback.
                import msvcrt
                sys.stdout.write(prompt)
                sys.stdout.flush()
                buf = []
                while time.monotonic() < _deadline:
                    if msvcrt.kbhit():
                        ch = msvcrt.getwche()
                        if ch in ("\r", "\n"):
                            print("")
                            break
                        if ch == "\003":  # Ctrl+C
                            raise KeyboardInterrupt
                        if ch == "\b":
                            if buf:
                                buf.pop()
                            continue
                        buf.append(ch)
                    else:
                        time.sleep(0.05)
                else:
                    print("")
                    print(f"  ⏱️  No response in {timeout}s; defaulting to '{default or ''}'.")
                    return default
                val = "".join(buf).strip()

            if val.lower() == "menu":
                print("  ↩️  Returning to main menu...")
                raise _ReturnToMenu
            if _strict_yn and val == "" and _yn_default_to:
                _record_choice(prompt, _yn_default_to)
                return _yn_default_to
            if _strict_yn and not _is_valid_yes_no_input(val):
                print("  Please enter y, n, yes, or no.")
                continue
            _record_choice(prompt, val)
            return val
    except (EOFError, KeyboardInterrupt):
        return default


# ── Interactive-prompt wait-time tracker ────────────────────────────────────
# Wraps the builtin ``input`` once at import time so every blocking prompt
# (whether it goes through ``_prompt`` or calls ``input`` directly) is
# measured. The accumulated wait time is surfaced in the run summary so that
# operator idle time at prompts can be distinguished from real work time and
# the unaccounted-time gap between phase totals and wall-clock runtime is
# explained.
import builtins as _builtins

_prompt_wait_seconds = 0.0
_prompt_wait_count = 0
_prompt_wait_lock = threading.Lock()
_prompt_wait_max = 0.0
_prompt_wait_max_label = ""
# Threshold (seconds) above which a single prompt is considered an
# "extended" operator wait worth flagging in the summary.
_PROMPT_WAIT_EXTENDED_THRESHOLD = 60.0
_prompt_wait_extended = []  # list[(label, seconds)]

_orig_input = _builtins.input


def _record_choice(prompt: str, answer: str) -> None:
    """Log a prompt→answer pair to the choices log.

    If the session log exists, delegates immediately to ``log_choice``.
    Otherwise the pair is buffered in ``_pre_session_choices`` and will be
    flushed (in order) once a session log is created by ``_make_session_log``.
    """
    if _session_log:
        with suppress(Exception):
            _session_log.log_choice(prompt, answer)
    else:
        try:
            _pre_session_choices.append((str(prompt or ""), str(answer or "")))
        except Exception:
            pass


def _prompt_is_yes_no(prompt="") -> bool:
    _p = str(prompt or "")
    if re.search(r"\[[Yy]\s*/\s*[Nn]\]", _p):
        return True
    _pl = _p.lower()
    return ("yes" in _pl) and ("no" in _pl)


def _is_valid_yes_no_input(value: str) -> bool:
    return str(value or "").strip().lower() in {"y", "n", "yes", "no"}


def _tracked_input(prompt=""):
    """Drop-in replacement for the builtin ``input`` that records how long
    the operator spent at each prompt. Behaves identically otherwise; raised
    exceptions (EOFError/KeyboardInterrupt) are re-raised after the wait
    time is still recorded so the totals include aborted prompts.
    """
    global _prompt_wait_seconds, _prompt_wait_count
    global _prompt_wait_max, _prompt_wait_max_label
    _start = time.monotonic()
    _non_phase_token = None
    if _session_log:
        with suppress(Exception):
            _non_phase_token = _session_log.push_non_phase_reason(
                "operator prompt wait"
            )
    try:
        if not _prompt_is_yes_no(prompt):
            _answer = _orig_input(prompt)
            _record_choice(prompt, _answer)
            return _answer
        # Determine the default answer from the prompt bracket, e.g. [y/N] → "n", [Y/n] → "y".
        _yn_default = ""
        _yn_m = re.search(r"\[([Yy])/([Nn])\]", str(prompt or ""))
        if _yn_m:
            _yn_default = "y" if _yn_m.group(1).isupper() else "n"
        while True:
            _val = _orig_input(prompt)
            _vl = str(_val or "").strip().lower()
            if _vl == "menu":
                return _val
            # Blank Enter accepts the capitalised default when one is present.
            if _vl == "" and _yn_default:
                _record_choice(prompt, _yn_default)
                return _yn_default
            if _is_valid_yes_no_input(_val):
                _record_choice(prompt, _val)
                return _val
            print("  Please enter y, n, yes, or no.")
    finally:
        _elapsed = time.monotonic() - _start
        if _session_log:
            with suppress(Exception):
                _session_log.pop_non_phase_reason(_non_phase_token)
        # Strip ANSI/whitespace from the label so the summary stays readable.
        try:
            _label = re.sub(r"\x1b\[[0-9;]*m", "", str(prompt))
            _label = _label.strip().splitlines()[-1] if _label.strip() else ""
            if len(_label) > 60:
                _label = _label[:57] + "..."
        except Exception:
            _label = ""
        with _prompt_wait_lock:
            _prompt_wait_seconds += _elapsed
            _prompt_wait_count += 1
            if _elapsed > _prompt_wait_max:
                _prompt_wait_max = _elapsed
                _prompt_wait_max_label = _label
            if _elapsed >= _PROMPT_WAIT_EXTENDED_THRESHOLD:
                _prompt_wait_extended.append((_label, _elapsed))


_builtins.input = _tracked_input


# ── Console echo suppression ────────────────────────────────────────────────
# When True, _recv_loop / drain_channel skip writing raw BMC/cluster console
# chunks to stdout. They still forward chunks to the session log file via
# _session_log.log_console, so nothing is lost — just hidden from the
# operator's terminal during noisy stages (e.g. system console hand-off and
# cluster login probing).
_console_quiet = False


@contextmanager
def _suppress_console():
    """Temporarily silence raw console echo to stdout while leaving session
    log capture intact. Restored on exit even if the block raises.
    """
    global _console_quiet
    _prev = _console_quiet
    _console_quiet = True
    try:
        yield
    finally:
        _console_quiet = _prev


def _menu_confirm(prompt: str = "  Enter 'yes' to continue or 'no' to go back: ") -> bool:
    """Return True for yes/y, False for no/n. Re-prompt on invalid input."""
    while True:
        try:
            _ans = input(prompt).strip().lower()
        except (EOFError, KeyboardInterrupt):
            return False
        if _ans in ("yes", "y"):
            return True
        if _ans in ("no", "n"):
            return False
        print("  Please enter y, n, yes, or no.")


def _print_banner(title: str, *, width: int = 60) -> None:
    """Print a ``"=" * width`` divider, a ``"  <title>"`` line, then another
    divider. Equivalent to the common 3-line banner block sprinkled across
    the script.
    """
    bar = "=" * width
    print("\n" + bar)
    print(f"  {title}")
    print(bar)


def _print_autopilot_banner() -> None:
    """Print the 'no more admin interaction required' transition notice."""
    _msg = "✅ Autopilot engaged. Check back periodically for job completion."
    bar = "=" * max(60, len(_msg) + 4)
    _ts_print(bar)
    _ts_print(_msg)
    _ts_print(bar)


def _print_wrapped_warning(message: str, *, indent: str = "  ", max_width: int = 100) -> None:
    """Print a WARNING line wrapped to terminal width with aligned continuation."""
    cols = min(shutil.get_terminal_size((80, 24)).columns, max_width)
    wrapped = textwrap.fill(
        message,
        width=max(cols, 40),
        initial_indent=f"{indent}⚠️  WARNING: ",
        subsequent_indent=indent,
    )
    print(f"\n{wrapped}")


def _open_shell(client, **kwargs):
    """``client.invoke_shell(**kwargs)`` with ``settimeout(0)`` already
    applied. Returns the channel.
    """
    ch = client.invoke_shell(**kwargs)
    ch.settimeout(0)
    return ch


def _looks_like_session_takeover_prompt(text: str) -> bool:
    """Return True when console output looks like a BMC session-takeover prompt."""
    _t = str(text or "").lower()
    if not _t:
        return False
    if "another user has an active cli session" in _t:
        return True
    if "disconnect that session" in _t:
        return True
    if "start yours [y/n" in _t:
        return True
    if "do you want to disconnect the other session" in _t:
        return True
    return ("active session" in _t and "[y/n" in _t)


def _reach_bmc_prompt(ch, *, timeout=15, node_log=None, takeover_msg=None):
    """Read until the BMC ``'>'`` prompt, transparently answering ``y`` to a
    ``y/n`` takeover prompt if another session is active.

    Returns ``True`` if the ``'>'`` prompt was reached (immediately or after
    takeover), ``False`` if no prompt was observed within *timeout*. When a
    takeover happens and *takeover_msg* is non-empty, it is forwarded to
    ``_slog`` so the operator sees a single consistent log line.
    """
    _out, matched = direct_read_until_any(
        ch,
        [
            "y/n",
            ">",
            "another user has an active cli session",
            "disconnect that session",
            "start yours [y/n",
        ],
        timeout=timeout,
        node_log=node_log,
    )
    if matched and ">" in matched:
        return True
    if not ((matched and "y/n" in matched.lower()) or _looks_like_session_takeover_prompt(_out)):
        return False
    if takeover_msg:
        _slog(takeover_msg)

    _deadline = time.monotonic() + max(20, int(timeout) * 3)
    _round = 0
    while time.monotonic() < _deadline:
        _round += 1
        try:
            ch.send("y\r")
        except OSError:
            _slog(
                "Socket closed while answering BMC session takeover prompt",
                prefix="WARN",
            )
            return False
        time.sleep(1.5)
        _remain = max(1, int(_deadline - time.monotonic()))
        _out2, _m2 = direct_read_until_any(
            ch,
            [
                "y/n",
                ">",
                "another user has an active cli session",
                "disconnect that session",
                "start yours [y/n",
            ],
            timeout=min(max(5, timeout), _remain),
            node_log=node_log,
        )
        if _m2 and ">" in _m2:
            if _round > 1:
                _slog(f"BMC prompt reached after {_round} stacked session takeovers")
            return True
        if (_m2 and "y/n" in _m2.lower()) or _looks_like_session_takeover_prompt(_out2):
            if _round == 1:
                _slog("Detected stacked BMC takeover prompt; continuing auto-disconnect", prefix="WARN")
            continue
        break
    return False


def load_config_file(path: str) -> dict:
    """Load and validate a JSON configuration file. Returns dict on success,
    raises ValueError with a friendly message on failure.
    """
    if not os.path.isfile(path):
        raise ValueError(f"Config file not found: {path}")
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in {path}: {e}")
    if not isinstance(data, dict):
        raise ValueError(f"Config file root must be a JSON object: {path}")
    return data


# ── Config file discovery helpers ───────────────────────────────────────────
# Multiple code paths (modes 1/3 startup, mode 44 license-only, mode 46
# gather/add, mode 47 BMC list, the 4.2 reinit re-prompt) all need to locate a
# reinit-style JSON config. Previously the same search loop was copy-pasted in
# 4+ places with subtle variants (different filename lists, different search
# dirs, some with interactive selection, some with silent first-match). These
# helpers centralise the search so callers only choose: (a) the candidate
# filename list, (b) the search directories, and (c) whether to deep-scan
# arbitrary JSONs as a fallback.

# Canonical reinit-config filename list, ordered by preference.
_DEFAULT_CONFIG_FILENAMES = (
    "reinit-config.json",
    "reinit_config.json",
    "reinit-afx-config.json",
    "reinit_afx_config.json",
    "afx-reinit-config.json",
    "config.json",
)


def _script_dir() -> str:
    """Return the directory holding this script. Falls back to CWD when
    ``__file__`` is undefined (e.g. interactive ``exec()`` contexts).
    """
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except NameError:
        return os.getcwd()


def _default_config_search_dirs() -> list:
    """Return the canonical search order: ``configs/`` subdir, the script
    directory, then CWD (skipped if it duplicates one of the first two).
    """
    sd = _script_dir()
    cwd = os.getcwd()
    dirs = [os.path.join(sd, "configs"), sd]
    if os.path.abspath(cwd) not in [os.path.abspath(d) for d in dirs]:
        dirs.append(cwd)
    return dirs


def _find_config_files(candidate_names=None, search_dirs=None,
                       deep_scan=False, deep_scan_keys=("cluster", "nodes")):
    """Return a list of absolute config-file paths discovered on disk.

    ``candidate_names``: filenames to look for in priority order; defaults to
    ``_DEFAULT_CONFIG_FILENAMES``.
    ``search_dirs``: directories to scan in order; defaults to
    ``_default_config_search_dirs()``.
    ``deep_scan``: when True and no exact-name match is found, also scan
    every ``*.json`` in the search dirs and keep those whose top-level dict
    contains ALL of ``deep_scan_keys``. This catches oddly-named files.

    Order of returned paths follows search-dir order, then filename order.
    Duplicates (by absolute path) are filtered.
    """
    names = candidate_names or _DEFAULT_CONFIG_FILENAMES
    dirs = search_dirs or _default_config_search_dirs()

    found = []
    seen = set()
    for d in dirs:
        for name in names:
            p = os.path.join(d, name)
            ap = os.path.abspath(p)
            if ap in seen:
                continue
            if os.path.isfile(p):
                found.append(p)
                seen.add(ap)

    if found or not deep_scan:
        return found

    # Fallback: scan *.json in the search dirs and keep schema-matching ones.
    for d in dirs:
        try:
            for fn in sorted(os.listdir(d)):
                if not fn.lower().endswith(".json"):
                    continue
                p = os.path.join(d, fn)
                ap = os.path.abspath(p)
                if ap in seen or not os.path.isfile(p):
                    continue
                try:
                    with open(p, "r", encoding="utf-8") as f:
                        data = json.load(f)
                except Exception:
                    continue
                if not isinstance(data, dict):
                    continue
                if all(k in data for k in deep_scan_keys):
                    found.append(p)
                    seen.add(ap)
        except OSError:
            continue
    return found


def _select_config_path_interactive(detected, indent="  ", header_emoji="📄"):
    """Given a list of detected config paths, prompt the operator to pick
    one. Returns the chosen path, or ``None`` if the operator declines.

    For one detected file the prompt is yes/no (default yes). For multiple,
    a numbered selector is shown with ``0`` meaning "none".
    """
    if not detected:
        return None
    pad = indent
    global _use_detected_config_choice
    if len(detected) == 1:
        found = detected[0]
        print(f"\n{pad}{header_emoji} Found config file: {found}")
        _saved_pref = None
        _cp_pref = CheckpointManager()
        if _cp_pref.load():
            _saved_pref = _cp_pref.get_param("use_detected_config")
        if _saved_pref is None and _use_detected_config_choice in (True, False):
            _saved_pref = _use_detected_config_choice
        if _saved_pref is True:
            print(f"{pad}ℹ️  Using saved checkpoint choice: yes")
            return found
        if _saved_pref is False:
            print(f"{pad}ℹ️  Using saved checkpoint choice: no")
            return None
        use_it = _prompt(f"{pad}Use this config file? [Y/n]: ", "y").lower()
        _use_config = use_it in ("", "y", "yes")
        _use_detected_config_choice = _use_config
        if _cp_pref.load():
            _cp_pref.set_param("use_detected_config", _use_config)
        return found if _use_config else None

    print(f"\n{pad}{header_emoji} Found multiple config files:")
    for i, p in enumerate(detected, 1):
        print(f"{pad}   {i}. {p}")
    print(f"{pad}   0. None — continue without a config file")
    while True:
        sel = _prompt(
            f"{pad}Select [0-{len(detected)}, default 1]: "
        , "1")
        if sel == "":
            sel = "1"
        if not sel.isdigit():
            print(f"{pad}  ⚠️  Enter a number.")
            continue
        idx = int(sel)
        if idx == 0:
            return None
        if 1 <= idx <= len(detected):
            return detected[idx - 1]
        print(f"{pad}  ⚠️  Out of range.")


def _run_parallel(items, target, *, with_index=False, join_timeout=None):
    """Spawn one daemon thread per item, then join them all.

    - ``target`` is called as ``target(item)`` by default, or
      ``target(item, idx)`` when ``with_index=True``.
    - ``join_timeout`` (seconds) is forwarded to each ``Thread.join`` call
      (``None`` waits indefinitely).
    - Returns the list of threads (already joined).
    """
    threads = []
    for idx, item in enumerate(items):
        args = (item, idx) if with_index else (item,)
        def _wrapped_target(*_args):
            try:
                target(*_args)
            except _InjectedCheckpointFailure:
                return
        t = threading.Thread(target=_wrapped_target, args=args, daemon=True)
        threads.append(t)
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=join_timeout) if join_timeout is not None else t.join()
    _raise_pending_checkpoint_failure()
    return threads


def _join_threads_with_deadline(threads, label="", timeout_seconds=None, log=None):
    """Join ``threads`` with an optional global deadline.

    Returns ``True`` when all threads exited, else ``False`` after deadline.
    """
    if timeout_seconds is None:
        timeout_seconds = _DEFAULT_PARALLEL_JOIN_TIMEOUT
    if timeout_seconds <= 0:
        for _t in threads:
            _t.join()
        return True

    _deadline = time.monotonic() + float(timeout_seconds)
    while True:
        _alive = [t for t in threads if t.is_alive()]
        if not _alive:
            return True
        _remaining = _deadline - time.monotonic()
        if _remaining <= 0:
            _names = [t.name for t in _alive if t.name]
            _suffix = f" for {label}" if label else ""
            print(
                f"\n  ❌ Timed out waiting for {len(_alive)} worker thread(s){_suffix} "
                f"after {int(timeout_seconds)}s."
            )
            if _names:
                print(f"  Still running: {', '.join(_names)}")
            if log:
                log.log(
                    f"thread join timeout{_suffix}: alive={_names or len(_alive)}",
                    prefix="ERROR",
                )
            return False
        _sleep_for = min(2.0, max(0.1, _remaining))
        for _t in _alive:
            _t.join(timeout=min(0.2, _sleep_for))
        if any(t.is_alive() for t in threads):
            time.sleep(_sleep_for)


def _bmc_fallback_passwords(ip, bmc_passwords):
    """Build the silent-fallback password list for a BMC connect attempt.

    Appends the cluster admin password (if different from the BMC password)
    and an empty/blank password (BMC passwords can be reset to blank by some
    SP firmware events) so both are tried silently before the operator is
    asked to re-enter credentials.
    """
    cluster_admin_pw = (_cluster_config.get("admin_password")
                        if isinstance(_cluster_config, dict) else None)
    fb = []
    if cluster_admin_pw and cluster_admin_pw != bmc_passwords.get(ip):
        fb.append(cluster_admin_pw)
    # Always include blank as a last-resort silent fallback (SP reset events
    # can leave the BMC with an empty password).
    if bmc_passwords.get(ip, "") != "":
        fb.append("")
    return fb


def _discover_and_prompt_config(ctx):
    """Discover config files and prompt the operator to select one.

    Writes ``ctx.config_data`` and ``ctx.retain_preselected`` and syncs back
    to the legacy module globals via ``ctx.apply_to_globals()``. Used by the
    4.2 reinit path so that the same config file that drives a normal
    1.1/1.2/3 run is offered when reinit is triggered from within 4.2.

    Returns the config path that was loaded, or None.
    """
    # Pull current globals into ctx so the final apply_to_globals() does not
    # clobber fields that legacy code (e.g. 4.2's reinit-mode selection that
    # set _operation_mode / _auto_setup / _auto_add) updated since the ctx
    # was last snapshotted.
    ctx.refresh_from_globals()

    detected_configs = _find_config_files(deep_scan=True)
    config_path = _select_config_path_interactive(detected_configs)

    if not detected_configs and not config_path:
        print("\n  ℹ️  No config file auto-detected.")
        ans = _prompt("  Enter path to a JSON config file, or blank to skip: ")
        if ans:
            if len(ans) >= 2 and ans[0] == ans[-1] and ans[0] in ("'", '"'):
                ans = ans[1:-1]
            expanded = os.path.expanduser(os.path.expandvars(ans))
            if os.path.isfile(expanded):
                config_path = expanded
            else:
                print(f"  ⚠️  File not found: {expanded}; continuing without config.")

    if config_path:
        try:
            ctx.config_data = load_config_file(config_path)
            print(f"  📄 Loaded config: {config_path}")
            ctx.retain_preselected = (False, False, False)
        except ValueError as e:
            print(f"  ⚠️  {e}")
            print("  Continuing without a config file (manual prompts).")
            ctx.config_data = {}
            config_path = None

    ctx.apply_to_globals()
    return config_path


def _cd(ctx=None) -> dict:
    """Resolve the active config-data dict.

    Preference order: explicit ``ctx`` argument → module-level
    ``_run_context`` → legacy ``_config_data`` global. Returns ``{}`` if all
    three are absent. Keeps callers decoupled from the global as helpers
    migrate toward ctx-style parameters.
    """
    if ctx is not None:
        return ctx.config_data or {}
    if _run_context is not None:
        return _run_context.config_data or {}
    return _config_data or {}


def _node_cfg_for(bmc: str, ctx=None) -> dict:
    """Return the node entry from the config that matches `bmc`, or {}.
    Searches primary_node, secondary_nodes, and legacy nodes[].
    """
    cd = _cd(ctx)
    pn = cd.get("primary_node")
    if isinstance(pn, dict) and pn.get("bmc") == bmc:
        return pn
    for node in (cd.get("secondary_nodes") or []):
        if isinstance(node, dict) and node.get("bmc") == bmc:
            return node
    for node in (cd.get("nodes") or []):
        if isinstance(node, dict) and node.get("bmc") == bmc:
            return node
    return {}


def _config_primary_node(ctx=None) -> dict:
    """Return the primary node dict from config (new or legacy format), or {}."""
    cd = _cd(ctx)
    pn = cd.get("primary_node")
    if isinstance(pn, dict) and pn.get("bmc"):
        return pn
    nodes = cd.get("nodes") or []
    if nodes and isinstance(nodes[0], dict):
        return nodes[0]
    return {}


def _config_secondary_nodes(ctx=None) -> list:
    """Return the list of secondary (peer) node dicts from config, or []."""
    cd = _cd(ctx)
    sn = cd.get("secondary_nodes")
    if isinstance(sn, list):
        return [n for n in sn if isinstance(n, dict)]
    nodes = cd.get("nodes") or []
    return [n for n in nodes[1:] if isinstance(n, dict)]


def _display_node_label(bmc_host: str = "", mode=None) -> str:
    """Return a user-facing node label such as primary or secondary-01."""
    _mode = _operation_mode if mode is None else mode
    _host = str(bmc_host or "").strip()

    if _mode == 1:
        return "primary"

    if _mode in (2, 41, 42):
        _pn = _config_primary_node()
        if str(_pn.get("bmc") or "").strip() == _host:
            return "primary"
        for _idx, _node in enumerate(_config_secondary_nodes(), start=1):
            if str(_node.get("bmc") or "").strip() == _host:
                return f"secondary-{_idx:02d}"
        return "secondary-01" if _mode == 2 else (_host or "node")

    if _mode == 3:
        _pn = _config_primary_node()
        if str(_pn.get("bmc") or "").strip() == _host:
            return "primary"
        for _idx, _node in enumerate(_config_secondary_nodes(), start=1):
            if str(_node.get("bmc") or "").strip() == _host:
                return f"secondary-{_idx:02d}"
        return "primary" if not _host else _host

    return _host or "node"


def _augment_role_label_with_ip(label: str = "", mode=None) -> str:
    """Expand role labels to include BMC IP (e.g. primary -> primary/10.x.x.x)."""
    _mode = _operation_mode if mode is None else mode
    _lbl = str(label or "").strip()
    if not _lbl or "/" in _lbl:
        return _lbl
    if re.match(r"^\d{1,3}(?:\.\d{1,3}){3}$", _lbl):
        _role = _display_node_label(_lbl, mode=_mode)
        return f"{_role}/{_lbl}" if _role and _role != _lbl else _lbl
    if _lbl == "primary":
        _pn = _config_primary_node()
        _ip = str(_pn.get("bmc") or "").strip()
        return f"{_lbl}/{_ip}" if _ip else _lbl
    _m = re.match(r"^secondary-(\d{2})$", _lbl)
    if _m:
        _idx = int(_m.group(1)) - 1
        _secs = _config_secondary_nodes()
        if 0 <= _idx < len(_secs):
            _ip = str((_secs[_idx] or {}).get("bmc") or "").strip()
            return f"{_lbl}/{_ip}" if _ip else _lbl
    return _lbl


def _display_ontap_node_label(nodename: str, node_mgmt_by_name: dict | None = None) -> str:
    """Return primary / secondary-## for an ONTAP node name when possible."""
    _name = str(nodename or "").strip()
    _ip = ""
    if isinstance(node_mgmt_by_name, dict):
        _ip = str(node_mgmt_by_name.get(_name) or "").strip()

    _pn = _config_primary_node()
    if _ip and str(_pn.get("node_mgmt_ip") or "").strip() == _ip:
        return "primary"

    for _idx, _node in enumerate(_config_secondary_nodes(), start=1):
        if _ip and str(_node.get("node_mgmt_ip") or "").strip() == _ip:
            return f"secondary-{_idx:02d}"

    return _name or "node"

# ---------------------------------------------------------------------------
# Per-node log writer – redirects sys.stdout during automated phases
# ---------------------------------------------------------------------------

# Saved reference to the real terminal stdout; set once at startup so it
# survives any later sys.stdout replacement.
def _inject_ip_timestamp_line(line: str) -> str:
    """Add a timestamp to lines that contain a bracketed IPv4 address.

    Example:
      "  ✅ [10.0.0.1] Connected"
    becomes:
      "  ✅ [10.0.0.1] | 2026-06-12 22:21:25 | Connected"
    """
    if not line or not _BRACKETED_IPV4_RE.search(line):
        return line
    if _INLINE_TS_RE.search(line) or _PREFIX_TS_RE.match(line.lstrip()):
        return line
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    
    def _replace_ip(m):
        bracketed_ip = m.group(0)
        pos = m.end()
        # Check if there's any text after the IP (non-whitespace)
        remaining = line[pos:].lstrip()
        if remaining and not remaining.startswith("|"):
            # Text exists after IP; add extra pipe separator
            # Preserve original spacing from pos to first non-space char
            spacing = line[pos:pos + len(line[pos:]) - len(remaining)]
            return bracketed_ip + f" | {ts} |{spacing}"
        # No text after IP
        return bracketed_ip + f" | {ts}"
    
    result = _BRACKETED_IPV4_RE.sub(_replace_ip, line, count=1)
    return result


def _inject_ip_timestamp_text(text: str) -> str:
    """Apply IPv4-bracket timestamp injection to every line in *text*."""
    if not text:
        return text
    out = []
    for seg in text.splitlines(keepends=True):
        if seg.endswith("\r\n"):
            core, ending = seg[:-2], "\r\n"
        elif seg.endswith("\n"):
            core, ending = seg[:-1], "\n"
        else:
            core, ending = seg, ""
        out.append(_inject_ip_timestamp_line(core) + ending)
    return "".join(out)


class _RealStdoutProxy:
    """Proxy around the terminal stdout used by direct _real_stdout writes."""

    def __init__(self, raw_stdout):
        self._raw = raw_stdout

    def write(self, text):
        self._raw.write(_inject_ip_timestamp_text(text))

    def flush(self):
        self._raw.flush()

    def fileno(self):
        return self._raw.fileno()

    def isatty(self):
        return self._raw.isatty()

    def __getattr__(self, name):
        return getattr(self._raw, name)


_real_stdout = _RealStdoutProxy(sys.stdout)


def _ts_print(msg: str) -> None:
    """Print a milestone line with an injected timestamp directly to the real
    terminal, bypassing any sys.stdout wrapper.  Uses the same bracket-injection
    logic as _NodeLogWriter so the format is consistent everywhere.
    """
    injected = _inject_ip_timestamp_line(msg)
    if injected == msg:
        ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        injected = f"[{ts}] " + msg.lstrip()
    _real_stdout.write(injected + "\n")
    _real_stdout.flush()


# When True (--debug flag), _NodeLogWriter forwards ALL output to the terminal
# instead of filtering to milestone lines only.
_debug_console = False

# ---------------------------------------------------------------------------
# Terminal state restoration
# ---------------------------------------------------------------------------
# getpass and paramiko temporarily set stdin to raw / no-echo mode.  If the
# script is interrupted mid-call the terminal is left broken (no echo, history
# keys not working).  We snapshot the TTY attributes at startup and restore
# them on every exit path, including the os._exit() force-exit path that
# normally bypasses atexit.

_saved_term_attrs = None
_term_fd = None
try:
    import termios as _termios_mod
    _term_fd = sys.stdin.fileno()
    if os.isatty(_term_fd):
        _saved_term_attrs = _termios_mod.tcgetattr(_term_fd)
except Exception:
    pass


def _restore_terminal():
    """Restore TTY to the state captured at script startup."""
    try:
        if _saved_term_attrs is not None and _term_fd is not None:
            import termios as _t
            _t.tcsetattr(_term_fd, _t.TCSADRAIN, _saved_term_attrs)
    except Exception:
        pass
    # Belt-and-suspenders: stty sane resets the line discipline even when
    # the saved snapshot pre-dates a getpass/paramiko raw-mode transition.
    try:
        if sys.platform != "win32":
            subprocess.run(
                ["stty", "sane"],
                stderr=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                check=False,
            )
    except (FileNotFoundError, OSError):
        pass


atexit.register(_restore_terminal)


class _NodeLogWriter:
    """A sys.stdout replacement that tees all output to a per-node log file.

    In *filtering* mode (``interactive=False``, the default for automated
    phases) only milestone lines (those that begin with one of the emoji /
    keyword prefixes defined below) are forwarded to the real terminal.  All
    other output – raw console chunks, verbose status lines – goes to the log
    file only.

    In *pass-through* mode (``interactive=True``, set around
    InteractiveSession.run() and for the interactive-only modes 1.1/2.1) every
    byte is written to both the log file *and* the real terminal, preserving
    the existing interactive experience.
    """

    _MILESTONE_STARTS = (
        "✅", "❌", "⚠️", "🤖", "🔄", "📋", "🔢", "🔒",
        "📡", "📝", "🌐", "🧩", "🔁", "🛑", "⏳", "↻",
        "Now monitoring boot output",
        "Mode 1", "Mode 2.2", "Auto-init", "Auto-join",
        "Monitoring for AUTOBOOT", "Detected LOADER prompt",
        "Boot menu", "Selecting option",
    )

    def __init__(self, node_file, interactive: bool = False):
        self._nf = node_file
        self.interactive = interactive
        self._buf = ""          # incomplete-line buffer for milestone scan

    def write(self, data: str) -> None:
        # Always write to the per-node log file.
        try:
            self._nf.write(data)
        except Exception:
            pass

        if self.interactive or _debug_console:
            # Pass-through: also write to real terminal.
            _real_stdout.write(data)
            _real_stdout.flush()
            return

        # Filtering mode: scan completed lines for milestone prefixes.
        self._buf += data
        while "\n" in self._buf:
            line, self._buf = self._buf.split("\n", 1)
            stripped = line.lstrip()
            if stripped and any(stripped.startswith(m) for m in self._MILESTONE_STARTS):
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                # Inject timestamp after the first [label] bracket group, or
                # prepend it if no bracket group is present.
                _ts_injected = re.sub(
                    r'(\[[^\]]+\])',
                    lambda m: m.group(0) + f" | {ts}",
                    line,
                    count=1,
                )
                if _ts_injected == line:
                    # No bracket group found – prepend timestamp.
                    _ts_injected = f"[{ts}] " + line.lstrip()
                _real_stdout.write(_ts_injected + "\n")
                _real_stdout.flush()

    def flush(self) -> None:
        try:
            self._nf.flush()
        except Exception:
            pass

    def isatty(self) -> bool:
        return False

    def fileno(self):
        raise OSError("fileno not supported on _NodeLogWriter")


# ---------------------------------------------------------------------------
# Session logging with phase timing
# ---------------------------------------------------------------------------

class _TeeStdout:
    """Mirrors all write() calls to both the real stdout and a log file.

    Installed by SessionLogger so every print() during a run is captured
    to ``screen_output_*.log`` in the session log directory.  ANSI escape
    codes are stripped from the file copy so the log is clean plain text.
    Thread-safe: a lock guards the file write so concurrent threads don't
    interleave partial lines in the log.
    """

    def __init__(self, real_stdout, log_file):
        self._real = real_stdout
        self._log = log_file
        self._lock = threading.Lock()

    def write(self, text):
        transformed = _inject_ip_timestamp_text(text)
        self._real.write(transformed)
        try:
            if not self._log.closed:
                clean = _ANSI_RE.sub("", transformed)
                with self._lock:
                    self._log.write(clean)
        except Exception:
            pass

    def flush(self):
        self._real.flush()
        try:
            if not self._log.closed:
                self._log.flush()
        except Exception:
            pass

    def fileno(self):
        return self._real.fileno()

    def isatty(self):
        return self._real.isatty()

    def __getattr__(self, name):
        return getattr(self._real, name)


class SessionLogger:
    # Background heartbeat tick interval (seconds). While a step is running
    # the logger writes a "still running" line at this cadence so long
    # operations are visible in the log file as time progresses, without
    # cluttering the console.
    _HEARTBEAT_INTERVAL = 15.0
    _DEFAULT_NON_PHASE_REASON = "startup / inter-phase transition"

    @staticmethod
    def _dir_suffix_from_label(label: str) -> str:
        """Return a '_optionX.Y' dir suffix derived from *label*, or ''."""
        if not label:
            return ""
        # "option 5.12", "option 3", "option4.1" — explicit user-facing number
        _m = re.search(r'\boption\s*(\d+(?:\.\d+)?)\b', label, re.IGNORECASE)
        if _m:
            return f"_option{_m.group(1)}"
        # "Mode 5.12:", "5.99:", "Mode 2.3:", etc. — dotted number in label
        _m = re.search(r'\b(\d+\.\d+)\b', label)
        if _m:
            return f"_option{_m.group(1)}"
        return ""

    @staticmethod
    def _normalize_resume_suffix(suffix: str) -> str:
        _raw = str(suffix or "").strip()
        if not _raw:
            return ""
        if not _raw.startswith("_"):
            _raw = "_" + _raw
        _safe = re.sub(r"[^A-Za-z0-9_.-]", "_", _raw)
        return _safe

    def __init__(self, bg_mode: bool = False, label: str = "", resume_suffix: str = ""):
        try:
            _script_dir = os.path.dirname(os.path.abspath(__file__))
        except NameError:
            _script_dir = os.getcwd()
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        _resume_suffix = self._normalize_resume_suffix(resume_suffix)
        self.log_dir = os.path.join(
            _script_dir, "logs", timestamp + self._dir_suffix_from_label(label) + _resume_suffix
        )
        os.makedirs(self.log_dir, exist_ok=True)
        self.log_file = _build_numbered_log_path(
            self.log_dir, f"bmc_session_primary_{timestamp}.log", scope_dir=self.log_dir
        )
        self.summary_file = _build_numbered_log_path(
            self.log_dir, f"summary_{timestamp}.log", scope_dir=self.log_dir
        )
        self._lock = threading.Lock()
        # buffering=1 = line-buffered; auto-flushes on every \n so the file is
        # safe to read even while the script is still running (or backgrounded).
        self._file = open(self.log_file, "w", encoding="utf-8", buffering=1)
        # Screen output log: captures everything printed to the console so a
        # full transcript of the user-visible run output is preserved.
        self.screen_log_file = _build_numbered_log_path(
            self.log_dir, f"screen_output_{timestamp}.log", scope_dir=self.log_dir
        )
        self._screen_log = open(
            self.screen_log_file, "w", encoding="utf-8", buffering=1
        )
        self._orig_stdout = sys.stdout
        self._stdout_restored = False
        sys.stdout = _TeeStdout(self._orig_stdout, self._screen_log)
        self._bg_mode = bg_mode
        self._start_time = datetime.now()
        # Resume tracking: when a checkpoint is loaded, previous_run_end_time
        # is set to the checkpoint's last-updated time; we then calculate
        # resume_gap_seconds as (start_time - previous_run_end_time).
        self._previous_run_end_time: "datetime | None" = None
        self._resume_gap_seconds: "float | None" = None
        self._phase_times = {}
        self._current_phase = None
        self._current_phase_start = None
        self._failure_stage_hint = ""
        # Runtime spent outside any explicit start_phase/end_phase window.
        self._non_phase_seconds = 0.0
        self._non_phase_buckets = {}
        self._current_non_phase_reason = self._DEFAULT_NON_PHASE_REASON
        self._non_phase_anchor = self._start_time

        # Per-step timing. Steps are nested-allowed lightweight measurements
        # driven through `step()` (context manager) or start_step/end_step.
        # `_step_times` accumulates total wall time per step name so the
        # summary table can collapse repeated work (e.g. multiple peer SSH
        # connects) into one row.
        self._step_stack = []   # list of dicts: {name, start}
        # Plain dicts are insertion-ordered as of Python 3.7+, which the
        # script requires.  OrderedDict is no longer needed here.
        self._step_times = {}  # name -> total seconds
        self._step_counts = {}  # name -> int

        # Tracks the timestamp of the previous log entry so each line can
        # show the delta since the previous one.
        self._last_log_time = self._start_time

        # Background heartbeat thread + stop event. Started lazily on the
        # first `start_step` so unit tests / quick runs don't pay for it.
        self._heartbeat_stop = threading.Event()
        self._heartbeat_thread = None

        # ---- Outcome tracking ----
        # Counts of ERROR/WARN prefixed log entries (auto-incremented in log()).
        self._error_count = 0
        self._warn_count = 0
        # Collected message text for every WARN / ERROR / FATAL entry so the
        # summary file can list them without requiring a full log scan.
        self._warnings: "list[tuple[str, str]]" = []   # (HH:MM:SS, message)
        self._errors:   "list[tuple[str, str]]" = []   # (HH:MM:SS, message)
        # Explicit overall outcome – set via set_outcome() before close().
        # None means "not yet set; derive at close() time".
        self._final_outcome: "tuple[str, str] | None" = None
        # Operation label set by _make_session_log (e.g. "Mode 2.3: resume…").
        self._operation_label: str = ""
        # Per-phase outcomes: phase_name -> (status, note)
        # Phases that call end_phase() without set_phase_outcome() get PASS.
        self._phase_outcomes: "dict[str, tuple[str, str]]" = {}
        # Optional ONTAP version snapshots captured by workflows that can
        # query cluster version (for summary "before vs after" visibility).
        self._ontap_version_before: str = ""
        self._ontap_version_after: str = ""
        self._ontap_version_before_source: str = ""
        self._ontap_version_after_source: str = ""
        self._ontap_before_by_node: "dict[str, str]" = {}
        self._ontap_after_by_node: "dict[str, str]" = {}
        self._ontap_previous_version: str = ""
        self._ontap_previous_source: str = ""
        # Optional indented sub-timing rows attached under a parent phase
        # in the summary tables. phase_name -> list[(label, elapsed_seconds)].
        self._phase_subtimings: "dict[str, list[tuple[str, float]]]" = {}
        self._closed = False

        # Per-peer node log files.  Keyed by BMC IP string.
        # {ip: {"file": file_handle, "index": int, "path": str}}
        self._peer_logs: "dict[str, dict]" = {}
        self._peer_logs_lock = threading.Lock()
        self._peer_log_counter = 0  # incremented per open_peer_log call

        self._write_header()
        self.refresh_summary()
        print(f"📝 Session log: {self.log_file}")

    # OPT: context-manager support so the file handle is always closed cleanly
    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    # OPT: centralise timestamp formatting – was duplicated in 5 methods
    def _ts_with_elapsed(self, now=None):
        """Return a timestamp prefix that also includes total elapsed time
        since session start and the delta since the previous log entry. Looks
        like: ``HH:MM:SS.mmm +123.4s Δ0.7s``. Caller must hold the lock.
        """
        now = now or datetime.now()
        total = (now - self._start_time).total_seconds()
        delta = (now - self._last_log_time).total_seconds()
        self._last_log_time = now
        ts = now.strftime("%H:%M:%S.%f")[:-3]
        return f"{ts} +{total:7.1f}s Δ{delta:5.1f}s"

    # ---- Step timing ----------------------------------------------------

    def start_step(self, name):
        """Mark the start of a named step. Multiple steps may be nested;
        each `start_step` must be paired with `end_step`. Returns a token
        that the caller can pass to `end_step` to be safe against mismatched
        nesting; in practice the `step()` context manager is preferred.
        """
        with self._lock:
            now = datetime.now()
            self._step_stack.append({"name": name, "start": now})
            indent = "  " * (len(self._step_stack) - 1)
            self._file.write(
                f"[{self._ts_with_elapsed(now)}] [STEP ▶] {indent}{name}\n"
            )
            self._ensure_heartbeat_locked()
            return len(self._step_stack)

    def end_step(self, name=None):
        """End the most recently started step. If `name` is supplied it is
        validated against the top of the stack and a warning is logged on
        mismatch (so a stray end_step can't silently corrupt the totals).
        """
        with self._lock:
            if not self._step_stack:
                self._file.write(
                    f"[{self._ts_with_elapsed()}] [WARN] end_step called with "
                    f"no active step (name={name!r})\n"
                )
                return
            entry = self._step_stack[-1]
            if name is not None and entry["name"] != name:
                self._file.write(
                    f"[{self._ts_with_elapsed()}] [WARN] end_step name mismatch: "
                    f"expected {entry['name']!r}, got {name!r}\n"
                )
            self._step_stack.pop()
            elapsed = (datetime.now() - entry["start"]).total_seconds()
            self._step_times[entry["name"]] = (
                self._step_times.get(entry["name"], 0.0) + elapsed
            )
            self._step_counts[entry["name"]] = (
                self._step_counts.get(entry["name"], 0) + 1
            )
            indent = "  " * len(self._step_stack)
            self._file.write(
                f"[{self._ts_with_elapsed()}] [STEP ⏹] {indent}{entry['name']} "
                f"({elapsed:.1f}s)\n"
            )

    @contextmanager
    def step(self, name):
        """Context manager: ``with _session_log.step("My Step"): ...``
        Logs start, end, and total duration. Safe across exceptions.
        """
        self.start_step(name)
        try:
            yield
        finally:
            self.end_step(name)

    # ---- Background heartbeat -----------------------------------------

    def _ensure_heartbeat_locked(self):
        """Start the heartbeat thread on first use. Must be called with
        ``self._lock`` held.
        """
        if self._heartbeat_thread is not None:
            return
        self._heartbeat_thread = threading.Thread(
            target=self._heartbeat_loop, name="SessionLogHeartbeat",
            daemon=True,
        )
        self._heartbeat_thread.start()

    def _heartbeat_loop(self):
        """While at least one step is active, periodically log a heartbeat
        line so long-running steps are visible in the log file as time
        progresses. The thread exits when the logger is closed.
        """
        while not self._heartbeat_stop.wait(self._HEARTBEAT_INTERVAL):
            with self._lock:
                if not self._step_stack:
                    continue
                now = datetime.now()
                # Report on the deepest (innermost) active step which is
                # what most callers care about. Outer steps are still
                # being timed and will surface in the summary at close().
                entry = self._step_stack[-1]
                running = (now - entry["start"]).total_seconds()
                indent = "  " * (len(self._step_stack) - 1)
                self._file.write(
                    f"[{self._ts_with_elapsed(now)}] [STEP ⏱] {indent}"
                    f"{entry['name']} still running ({running:.1f}s)\n"
                )

    def _write_header(self):
        self._file.write("=" * 70 + "\n")
        self._file.write("BMC Session Log\n")  # OPT: was an f-string with no interpolation
        self._file.write(f"Started: {self._start_time.strftime('%Y-%m-%d %H:%M:%S')}\n")
        self._file.write(f"Host: {platform.node()}\n")
        self._file.write(f"Python: {sys.version}\n")
        self._file.write("=" * 70 + "\n\n")

    def refresh_summary(self):
        """Write/refresh the live summary snapshot for this active run."""
        with self._lock:
            now = datetime.now()
            # Calculate total elapsed excluding resume gap
            total_elapsed = (now - self._start_time).total_seconds()
            if self._resume_gap_seconds is not None:
                total_elapsed -= self._resume_gap_seconds
            self._write_summary_file(
                now, total_elapsed,
                "IN PROGRESS", "Run is active; phases may still be incomplete.",
                failure_stage="", final=False,
            )

    def set_resume_context(self, previous_end_time: "str | datetime") -> None:
        """Register a resume event with the timestamp when the previous run exited.
        
        Call this after loading a checkpoint to track the gap between runs.
        previous_end_time can be an ISO format string (from checkpoint['updated'])
        or a datetime object.
        """
        try:
            if isinstance(previous_end_time, str):
                _prev = datetime.fromisoformat(previous_end_time)
            else:
                _prev = previous_end_time
            self._previous_run_end_time = _prev
            self._resume_gap_seconds = max(
                0.0, (self._start_time - _prev).total_seconds()
            )
            _slog(f"Resume: previous run ended at {_prev.isoformat()}, "
                  f"gap={self._resume_gap_seconds:.1f}s")
        except Exception as e:
            _slog(f"Could not parse resume time: {e}", prefix="WARN")

    def start_phase(self, phase_name):
        with self._lock:
            now = datetime.now()
            if self._current_phase and self._current_phase_start:
                elapsed = (now - self._current_phase_start).total_seconds()
                self._phase_times[self._current_phase] = elapsed
                # If a new phase starts before end_phase() is called on the
                # previous one, treat that previous phase as completed unless
                # a specific outcome has already been set.
                if self._current_phase not in self._phase_outcomes:
                    self._phase_outcomes[self._current_phase] = ("PASS", "")
            else:
                self._record_non_phase_window_locked(now)
            self._current_phase = phase_name
            self._current_phase_start = now
            self._file.write(
                f"\n[{self._ts_with_elapsed(now)}] [PHASE] ▶ Started: {phase_name}\n"
            )
            self._ensure_heartbeat_locked()
            if _checkpoint:
                with suppress(Exception):
                    _checkpoint.set_current_phase(phase_name, state="in_progress")
            _total = (now - self._start_time).total_seconds()
            if self._resume_gap_seconds is not None:
                _total -= self._resume_gap_seconds
            self._write_summary_file(
                now, _total,
                "IN PROGRESS", "Run is active; phases may still be incomplete.",
                failure_stage="", final=False,
            )

    def end_phase(self, outcome: str = "PASS", note: str = ""):
        """End the current phase.  *outcome* is written into the phase
        outcome table ("PASS", "FAIL", or "PASSED (WITH ERRORS)"). Call
        ``set_phase_outcome()`` *before* ``end_phase()`` to override.
        """
        with self._lock:
            if self._current_phase and self._current_phase_start:
                now = datetime.now()
                elapsed = (now - self._current_phase_start).total_seconds()
                self._phase_times[self._current_phase] = elapsed
                # Record outcome for this phase if not already set explicitly.
                if self._current_phase not in self._phase_outcomes:
                    self._phase_outcomes[self._current_phase] = (outcome, note)
                self._file.write(
                    f"[{self._ts_with_elapsed(now)}] [PHASE] ⏹ Ended: "
                    f"{self._current_phase} ({elapsed:.1f}s) "
                    f"[{self._phase_outcomes[self._current_phase][0]}]\n\n"
                )
                _ended_phase = self._current_phase
                self._current_phase = None
                self._current_phase_start = None
                self._current_non_phase_reason = self._DEFAULT_NON_PHASE_REASON
                self._non_phase_anchor = now
                if _checkpoint:
                    with suppress(Exception):
                        _checkpoint.set_current_phase(_ended_phase, state="completed")
                _total = (now - self._start_time).total_seconds()
                if self._resume_gap_seconds is not None:
                    _total -= self._resume_gap_seconds
                self._write_summary_file(
                    now, _total,
                    "IN PROGRESS", "Run is active; phases may still be incomplete.",
                    failure_stage="", final=False,
                )

    def set_phase_outcome(self, phase_name: str, status: str, note: str = ""):
        """Explicitly record the outcome of a named phase. Call this before
        ``end_phase()`` if the default (PASS) is not correct.
        """
        with self._lock:
            self._phase_outcomes[phase_name] = (status, note)
            now = datetime.now()
            _total = (now - self._start_time).total_seconds()
            if self._resume_gap_seconds is not None:
                _total -= self._resume_gap_seconds
            self._write_summary_file(
                now, _total,
                "IN PROGRESS", "Run is active; phases may still be incomplete.",
                failure_stage="", final=False,
            )

    def record_phase(self, phase_name: str, elapsed: float,
                     outcome: str = "PASS", note: str = ""):
        """Record a phase with a precomputed elapsed time, without using the
        ``start_phase``/``end_phase`` wall-clock pair. Useful when the real
        boundaries of a phase are determined inside worker threads and have
        to be reconstructed after the fact (e.g. the mode-3 parallel peer
        add, where option-4 and node-join sub-phases overlap in time).
        """
        with self._lock:
            self._phase_times[phase_name] = float(elapsed)
            self._phase_outcomes[phase_name] = (outcome, note)
            self._file.write(
                f"[{self._ts_with_elapsed()}] [PHASE] ⏹ Recorded: "
                f"{phase_name} ({elapsed:.1f}s) [{outcome}]\n"
            )
            if _checkpoint:
                with suppress(Exception):
                    _checkpoint.set_current_phase(phase_name, state="completed")
            now = datetime.now()
            self._write_summary_file(
                now, (now - self._start_time).total_seconds(),
                "IN PROGRESS", "Run is active; phases may still be incomplete.",
                failure_stage="", final=False,
            )

    def add_phase_subtiming(self, phase_name: str, label: str, elapsed: float):
        """Attach an indented timing row that will be rendered under
        ``phase_name`` in both the inline and standalone summary tables.
        Safe to call from worker threads.
        """
        with self._lock:
            self._phase_subtimings.setdefault(phase_name, []).append(
                (label, float(elapsed))
            )

    def set_outcome(self, status: str, note: str = ""):
        """Set the overall session outcome ("PASS", "FAIL", or
        "PASSED (WITH ERRORS)"). Should be called before ``close()``.
        """
        with self._lock:
            self._final_outcome = (status, note)

    def set_failure_stage_hint(self, stage: str = ""):
        """Set an explicit failure stage label for summary attribution."""
        with self._lock:
            self._failure_stage_hint = str(stage or "").strip()

    def set_ontap_versions(self, before: str = "", after: str = "",
                           source: str = "",
                           before_by_node: "dict[str, str] | None" = None,
                           after_by_node: "dict[str, str] | None" = None) -> None:
        """Record ONTAP version snapshots for summary reporting."""
        with self._lock:
            _before = str(before or "").strip()
            _after = str(after or "").strip()
            _src = str(source or "").strip()
            _before_map = {
                str(k).strip(): str(v).strip()
                for k, v in (before_by_node or {}).items()
                if str(k).strip() and str(v).strip()
            }
            _after_map = {
                str(k).strip(): str(v).strip()
                for k, v in (after_by_node or {}).items()
                if str(k).strip() and str(v).strip()
            }
            if _before:
                self._ontap_version_before = _before
                if _src:
                    self._ontap_version_before_source = _src
            if _after:
                self._ontap_version_after = _after
                if _src:
                    self._ontap_version_after_source = _src
            if _before_map:
                self._ontap_before_by_node.update(_before_map)
                if _src:
                    self._ontap_version_before_source = _src
            if _after_map:
                self._ontap_after_by_node.update(_after_map)
                if _src:
                    self._ontap_version_after_source = _src
            _msg_parts = []
            if _before:
                _msg_parts.append(f"before={_before}")
            if _after:
                _msg_parts.append(f"after={_after}")
            if _before_map:
                _msg_parts.append(f"before_nodes={len(_before_map)}")
            if _after_map:
                _msg_parts.append(f"after_nodes={len(_after_map)}")
            if _msg_parts:
                if _src:
                    _msg_parts.append(f"source={_src}")
                self._file.write(
                    f"[{self._ts_with_elapsed()}] [INFO] ONTAP version snapshot: "
                    f"{', '.join(_msg_parts)}\n"
                )
            now = datetime.now()
            self._write_summary_file(
                now, (now - self._start_time).total_seconds(),
                "IN PROGRESS", "Run is active; phases may still be incomplete.",
                failure_stage="", final=False,
            )

    def _write_ontap_version_lines(self, out_fh) -> None:
        """Render ONTAP version summary rows into the provided file handle."""
        def _loader_env_previous_version():
            _loader_dir = os.path.join(self.log_dir, "LOADER_ENV")
            if not os.path.isdir(_loader_dir):
                return "", ""
            _candidates = []
            try:
                for _name in os.listdir(_loader_dir):
                    _lname = _name.lower()
                    if not _lname.endswith(".txt"):
                        continue
                    if "loader_env_pre_" not in _lname:
                        continue
                    _path = os.path.join(_loader_dir, _name)
                    if os.path.isfile(_path):
                        _candidates.append(_path)
            except Exception:
                return "", ""
            if not _candidates:
                return "", ""
            _candidates.sort(key=lambda p: os.path.getmtime(p), reverse=True)
            _pat = re.compile(
                r"^\s*last-OS-booted-ver(?:\s*=\s*|\s+)(\S.*?)\s*$",
                re.IGNORECASE,
            )
            for _path in _candidates:
                try:
                    with open(_path, "r", encoding="utf-8", errors="replace") as _fh:
                        for _line in _fh:
                            _m = _pat.match(_line)
                            if not _m:
                                continue
                            _ver = str(_m.group(1) or "").strip()
                            if _ver:
                                return _ver, os.path.basename(_path)
                except Exception:
                    continue
            return "", ""

        _prev_ver, _prev_src = _loader_env_previous_version()
        if _prev_ver:
            self._ontap_previous_version = _prev_ver
            self._ontap_previous_source = _prev_src

        if self._ontap_previous_version:
            _prev_lbl = self._ontap_previous_version
            if self._ontap_previous_source:
                _prev_lbl = f"{_prev_lbl} (LOADER_ENV/{self._ontap_previous_source})"
            out_fh.write(f"  {'Previous ONTAP version':<25} {_prev_lbl}\n")
        if self._ontap_version_before:
            _before_lbl = self._ontap_version_before
            if self._ontap_version_before_source:
                _before_lbl = (
                    f"{_before_lbl} ({self._ontap_version_before_source})"
                )
            out_fh.write(f"  {'ONTAP before run':<25} {_before_lbl}\n")
        if self._ontap_before_by_node:
            out_fh.write(f"  {'ONTAP before run (nodes)':<25}\n")
            for _node in sorted(self._ontap_before_by_node):
                out_fh.write(
                    f"    - {_node:<21} {self._ontap_before_by_node[_node]}\n"
                )
        if self._ontap_version_after:
            _after_lbl = self._ontap_version_after
            if self._ontap_version_after_source:
                _after_lbl = (
                    f"{_after_lbl} ({self._ontap_version_after_source})"
                )
            out_fh.write(f"  {'ONTAP after run':<25} {_after_lbl}\n")
        if self._ontap_after_by_node:
            out_fh.write(f"  {'ONTAP after run (nodes)':<25}\n")
            for _node in sorted(self._ontap_after_by_node):
                out_fh.write(
                    f"    - {_node:<21} {self._ontap_after_by_node[_node]}\n"
                )

    def _infer_failure_stage(self) -> str:
        """Best-effort phase label for where a failed run stopped."""
        if self._failure_stage_hint:
            return self._failure_stage_hint
        # 1) Explicitly failed phase outcome, preferring the latest phase order.
        _failed = {
            _p for _p, (_st, _note) in self._phase_outcomes.items()
            if str(_st).upper() == "FAIL"
        }
        if _failed:
            for _phase in reversed(list(self._phase_times.keys())):
                if _phase in _failed:
                    return _phase
            return next(iter(_failed), "")

        # 2) If a phase was active when the run ended unexpectedly.
        if self._current_phase:
            return self._current_phase

        # 3) Fallback to the latest recorded phase (best effort).
        if self._phase_times:
            return next(reversed(self._phase_times.keys()))
        return ""

    def _non_phase_elapsed(self, now: "datetime | None" = None) -> float:
        """Return wall time spent outside tracked phase windows."""
        _now = now or datetime.now()
        _total = float(self._non_phase_seconds)
        if self._current_phase is None:
            _total += max(0.0, (_now - self._non_phase_anchor).total_seconds())
        return max(0.0, _total)

    def _record_non_phase_window_locked(self, now: "datetime | None" = None) -> None:
        """Roll the current non-phase window into its reason bucket.

        Caller must hold ``self._lock``.
        """
        if self._current_phase is not None:
            return
        _now = now or datetime.now()
        _elapsed = max(0.0, (_now - self._non_phase_anchor).total_seconds())
        if _elapsed <= 0:
            self._non_phase_anchor = _now
            return
        _reason = (
            str(self._current_non_phase_reason or "").strip()
            or self._DEFAULT_NON_PHASE_REASON
        )
        self._non_phase_buckets[_reason] = (
            self._non_phase_buckets.get(_reason, 0.0) + _elapsed
        )
        self._non_phase_seconds += _elapsed
        self._non_phase_anchor = _now

    def push_non_phase_reason(self, reason: str) -> "str | None":
        """Temporarily classify active non-phase time under *reason*.

        Returns the previous reason when a non-phase window is active, otherwise
        ``None`` (e.g. when called while a tracked phase is running).
        """
        with self._lock:
            if self._closed or self._current_phase is not None:
                return None
            _now = datetime.now()
            self._record_non_phase_window_locked(_now)
            _prev = self._current_non_phase_reason
            self._current_non_phase_reason = (
                str(reason or "").strip() or self._DEFAULT_NON_PHASE_REASON
            )
            self._non_phase_anchor = _now
            return _prev

    def pop_non_phase_reason(self, previous_reason: "str | None") -> None:
        """Restore a prior non-phase reason returned by push_non_phase_reason()."""
        if previous_reason is None:
            return
        with self._lock:
            if self._closed or self._current_phase is not None:
                return
            _now = datetime.now()
            self._record_non_phase_window_locked(_now)
            self._current_non_phase_reason = (
                str(previous_reason or "").strip() or self._DEFAULT_NON_PHASE_REASON
            )
            self._non_phase_anchor = _now

    def _non_phase_breakdown(self, now: "datetime | None" = None) -> "dict[str, float]":
        """Return reason-coded non-phase time buckets including the active window."""
        _now = now or datetime.now()
        _out = {
            str(_label): float(_elapsed)
            for _label, _elapsed in self._non_phase_buckets.items()
            if float(_elapsed) > 0
        }
        if self._current_phase is None:
            _active = max(0.0, (_now - self._non_phase_anchor).total_seconds())
            if _active > 0:
                _label = (
                    str(self._current_non_phase_reason or "").strip()
                    or self._DEFAULT_NON_PHASE_REASON
                )
                _out[_label] = _out.get(_label, 0.0) + _active
        return _out

    def record_completion(self, normal_exit: bool = True):
        """Convenience wrapper: sets outcome based on error/warn counters and
        calls close(). Intended to be the single call at the normal exit path
        in main() instead of a manual set_outcome() + close() sequence.
        """
        if normal_exit:
            if self._error_count == 0:
                status, note = "PASS", ""
            else:
                ec, wc = self._error_count, self._warn_count
                note = f"{ec} error(s), {wc} warning(s)" if ec or wc else ""
                status = "PASSED (WITH ERRORS)"
        else:
            status, note = "FAIL", "abnormal exit"
        self.set_outcome(status, note)
        self.close()


    def log_console(self, data):
        with self._lock:
            if self._closed or self._file.closed:
                return
            self._file.write(data)

    def log_user_input(self, data):
        with self._lock:
            if self._closed or self._file.closed:
                return
            self._file.write(f"[{self._ts_with_elapsed()}] [USER_INPUT] {data}\n")

    def log_sent(self, data):
        with self._lock:
            if self._closed or self._file.closed:
                return
            display = repr(data) if any(ord(c) < 32 and c not in '\r\n' for c in data) else data.strip()
            self._file.write(f"[{self._ts_with_elapsed()}] [SENT] {display}\n")

    def log_choice(self, prompt: str, answer: str):
        """Record an operator prompt→answer pair to the choices log.

        Answers to prompts whose text contains password-related keywords are
        masked so credentials are never written to the choices file.
        """
        with self._lock:
            if self._closed:
                return
            try:
                _label = re.sub(r"\x1b\[[0-9;]*m", "", str(prompt or ""))
                _label = _label.strip().splitlines()[-1] if _label.strip() else ""
                _is_secret = any(
                    w in _label.lower()
                    for w in ("password", "passphrase", "secret", "token", "passwd")
                )
                _display = "***" if _is_secret else (answer if answer else "(blank/default)")
                ts = datetime.now().strftime("%H:%M:%S")
                self._choices_log.write(f"[{ts}] {_label}\n         → {_display}\n\n")
            except Exception:
                pass

    def open_peer_log(self, ip: str, index: "int | None" = None) -> "str | None":
        """Create (or return path to) a per-peer BMC session log file.

        The file is named ``bmc_session_secondary-{NN}_{ip}_{ts}.log`` where
        ``NN`` is a zero-padded ordinal so files sort in join order.

        Returns the path to the opened log, or None on failure.  Idempotent —
        calling twice for the same IP returns the already-opened path.
        """
        with self._peer_logs_lock:
            if ip in self._peer_logs:
                return self._peer_logs[ip]["path"]
            if self._closed:
                return None
            self._peer_log_counter += 1
            _idx = index if index is not None else self._peer_log_counter
            _safe_ip = ip.replace(".", "_").replace(":", "_")
            _ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            _fname = f"bmc_session_secondary-{_idx:02d}_{_safe_ip}_{_ts}.log"
            try:
                _path = _build_numbered_log_path(self.log_dir, _fname, scope_dir=self.log_dir)
                _fh = open(_path, "w", encoding="utf-8", buffering=1)
                _fh.write(
                    f"BMC Session Log — secondary node {ip} (index {_idx})\n"
                    f"Started: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"
                    + "=" * 72 + "\n\n"
                )
                self._peer_logs[ip] = {"file": _fh, "index": _idx, "path": _path}
                return _path
            except Exception:
                return None

    def log_peer(self, ip: str, message: str, prefix: str = "INFO") -> None:
        """Write *message* to the per-peer log for *ip* AND to the primary log.

        If no peer log has been opened for *ip*, writes only to the primary log.
        Error/warn accounting is always done on the primary counters so the
        session summary remains accurate regardless of which file is used.
        """
        with self._lock:
            if self._closed or self._file.closed:
                return
            upper = prefix.upper()
            now_str = datetime.now().strftime("%H:%M:%S")
            if upper in ("ERROR", "FATAL"):
                self._error_count += 1
                self._errors.append((now_str, message))
            elif upper == "WARN":
                self._warn_count += 1
                self._warnings.append((now_str, message))
            _line = f"[{self._ts_with_elapsed()}] [{prefix}] {message}\n"
            self._file.write(_line)
        # Write to peer-specific log outside the primary lock to avoid deadlock.
        with self._peer_logs_lock:
            _entry = self._peer_logs.get(ip)
        if _entry:
            with suppress(Exception):
                _entry["file"].write(_line)

    def log(self, message, prefix="INFO"):
        """Write to the primary log and also fan-out to any registered peer log
        whose IP appears in a ``[peer/IP]`` or ``[node_peer:IP]`` tag at the
        start of *message*.
        """
        with self._lock:
            if self._closed or self._file.closed:
                return
            upper = prefix.upper()
            now_str = datetime.now().strftime("%H:%M:%S")
            if upper in ("ERROR", "FATAL"):
                self._error_count += 1
                self._errors.append((now_str, message))
            elif upper == "WARN":
                self._warn_count += 1
                self._warnings.append((now_str, message))
            _line = f"[{self._ts_with_elapsed()}] [{prefix}] {message}\n"
            self._file.write(_line)
        # Fan-out: if message is tagged with a peer IP, also write to its log.
        _m = re.match(r"^\[(?:peer|node_peer)[/:]([^\]]+)\]", str(message or ""))
        if _m:
            _peer_ip = _m.group(1).strip()
            with self._peer_logs_lock:
                _entry = self._peer_logs.get(_peer_ip)
            if _entry:
                with suppress(Exception):
                    _entry["file"].write(_line)

    def close(self):
        # Stop the heartbeat thread BEFORE taking the lock so it can drain
        # any in-flight tick that may already be holding the lock.
        self._heartbeat_stop.set()
        if self._heartbeat_thread is not None:
            try:
                self._heartbeat_thread.join(timeout=2.0)
            except RuntimeError:
                pass
        with self._lock:
            if self._closed:
                return
            self._closed = True
            # OPT: capture now once instead of calling datetime.now() three times
            now = datetime.now()
            if self._current_phase and self._current_phase_start:
                elapsed = (now - self._current_phase_start).total_seconds()
                self._phase_times[self._current_phase] = elapsed
            else:
                self._record_non_phase_window_locked(now)

            # Flush any still-open steps so their partial duration shows up
            # in the summary instead of being silently dropped.
            while self._step_stack:
                entry = self._step_stack.pop()
                elapsed = (now - entry["start"]).total_seconds()
                self._step_times[entry["name"]] = (
                    self._step_times.get(entry["name"], 0.0) + elapsed
                )
                self._step_counts[entry["name"]] = (
                    self._step_counts.get(entry["name"], 0) + 1
                )
                self._file.write(
                    f"[{self._ts_with_elapsed(now)}] [STEP ⏹] {entry['name']} "
                    f"({elapsed:.1f}s, closed at session end)\n"
                )

            total_elapsed = (now - self._start_time).total_seconds()

            # ---- Derive overall outcome ----
            if self._final_outcome is not None:
                outcome_status, outcome_note = self._final_outcome
            elif self._error_count > 0:
                outcome_status = "FAIL"
                outcome_note = f"{self._error_count} error(s) logged"
            elif self._warn_count > 0:
                outcome_status = "PASSED (WITH ERRORS)"
                outcome_note = f"{self._warn_count} warning(s) logged"
            else:
                outcome_status = "PASS"
                outcome_note = ""
            failure_stage = self._infer_failure_stage() if outcome_status == "FAIL" else ""

            self._file.write(f"\n{'=' * 70}\n")
            self._file.write(f"Session ended: {now.strftime('%Y-%m-%d %H:%M:%S')}\n")
            self._file.write(f"Total runtime: {total_elapsed:.1f}s ({total_elapsed/60:.1f} minutes)\n")

            # ---- Result Summary ----
            self._file.write(f"\n{'─' * 70}\n")
            self._file.write("Result Summary\n")
            self._file.write(f"{'─' * 70}\n")
            if self._operation_label:
                self._file.write(f"  {'Operation':<25} {self._operation_label}\n")
            _status_icon = {"PASS": "✅", "FAIL": "❌", "PASSED (WITH ERRORS)": "⚠️"}.get(outcome_status, "❓")
            self._file.write(f"  {'Overall Result':<25} {_status_icon} {outcome_status}\n")
            if outcome_note:
                self._file.write(f"  {'Detail':<25} {outcome_note}\n")
            if failure_stage:
                self._file.write(f"  {'Failure stage':<25} {failure_stage}\n")
            self._file.write(f"  {'Errors logged':<25} {self._error_count}\n")
            self._file.write(f"  {'Warnings logged':<25} {self._warn_count}\n")
            self._write_ontap_version_lines(self._file)
            self._file.write(f"  {'Started':<25} {self._start_time.strftime('%Y-%m-%d %H:%M:%S')}\n")
            self._file.write(f"  {'Ended':<25} {now.strftime('%Y-%m-%d %H:%M:%S')}\n")

            # ---- Phase Timing Summary ----
            self._file.write(f"\n{'─' * 70}\n")
            self._file.write("Phase Timing Summary\n")
            self._file.write(f"{'─' * 70}\n")
            for phase, elapsed in self._phase_times.items():
                minutes = elapsed / 60
                ph_status, ph_note = self._phase_outcomes.get(phase, ("", ""))
                ph_icon = {"PASS": "✅", "FAIL": "❌", "PASSED (WITH ERRORS)": "⚠️"}.get(ph_status, "  ")
                ph_col = f"  {ph_icon} {ph_status}" if ph_status else ""
                self._file.write(
                    f"  {phase:<45} {elapsed:>7.1f}s ({minutes:.1f}m){ph_col}\n"
                )
                _prev_node_elapsed = None
                for sub_label, sub_elapsed in self._phase_subtimings.get(phase, []):
                    if sub_label.startswith("Node [") and _prev_node_elapsed is not None:
                        _delta = sub_elapsed - _prev_node_elapsed
                        _time_str = f"(+{_delta/60:.1f}m)"
                        _prev_node_elapsed = sub_elapsed
                    elif sub_label.startswith("Node ["):
                        _time_str = f"({sub_elapsed/60:.1f}m)"
                        _prev_node_elapsed = sub_elapsed
                    else:
                        _time_str = f"({sub_elapsed/60:.1f}m)"
                    self._file.write(
                        f"     - {sub_label:<41} {sub_elapsed:>7.1f}s "
                        f"{_time_str}\n"
                    )
            self._file.write(f"  {'─' * 55}\n")
            self._file.write(f"  {'TOTAL':<45} {total_elapsed:>7.1f}s ({total_elapsed/60:.1f}m)\n")
            # Prompt/pause totals are informational. True "unaccounted" time is
            # only the residual after tracked phases plus reason-coded
            # non-phase buckets are removed from wall-clock runtime.
            _pw = float(_prompt_wait_seconds)
            _paw = float(_pause_wait_seconds)
            _phase_sum = sum(self._phase_times.values()) if self._phase_times else 0.0
            _non_phase_breakdown = self._non_phase_breakdown(now)
            _non_phase_total = sum(_non_phase_breakdown.values()) if _non_phase_breakdown else 0.0
            _unaccounted = max(0.0, total_elapsed - _phase_sum - _non_phase_total)
            self._file.write(
                f"  {'Time waiting for prompts (x' + str(_prompt_wait_count) + ')':<45} "
                f"{_pw:>7.1f}s ({_pw/60:.1f}m)\n"
            )
            if _prompt_wait_max > 0:
                _lbl = _prompt_wait_max_label or "(no label)"
                self._file.write(
                    f"     - longest single wait: {_prompt_wait_max:.1f}s "
                    f"({_prompt_wait_max/60:.1f}m) at: {_lbl}\n"
                )
            for _ext_lbl, _ext_sec in _prompt_wait_extended:
                self._file.write(
                    f"     - extended wait {_ext_sec:>6.1f}s "
                    f"({_ext_sec/60:.1f}m) at: {_ext_lbl or '(no label)'}\n"
                )
            self._file.write(
                f"  {'Pause wait (x' + str(_pause_wait_count) + ')':<45} "
                f"{_paw:>7.1f}s ({_paw/60:.1f}m)\n"
            )
            if _pause_wait_max > 0:
                _plbl = _pause_wait_max_label or "(no label)"
                self._file.write(
                    f"     - longest single pause: {_pause_wait_max:.1f}s "
                    f"({_pause_wait_max/60:.1f}m) context: {_plbl}\n"
                )
            self._file.write(
                f"  {'Non-phase time (classified)':<45} {_non_phase_total:>7.1f}s ({_non_phase_total/60:.1f}m)\n"
            )
            for _np_label, _np_elapsed in _non_phase_breakdown.items():
                self._file.write(
                    f"     - {_np_label:<39} {_np_elapsed:>7.1f}s ({_np_elapsed/60:.1f}m)\n"
                )
            _residual = _unaccounted
            self._file.write(
                f"  {'Unaccounted time':<45} {_residual:>7.1f}s ({_residual/60:.1f}m)\n"
            )
            self._file.write(
                f"     - {'residual instrumentation gap':<39} {_residual:>7.1f}s ({_residual/60:.1f}m)\n"
            )
            if self._step_times:
                self._file.write(f"\n{'─' * 70}\n")
                self._file.write("Step Timing Summary\n")
                self._file.write(f"{'─' * 70}\n")
                for name, elapsed in self._step_times.items():
                    count = self._step_counts.get(name, 1)
                    avg = elapsed / count if count else elapsed
                    label = f"{name} (x{count})" if count > 1 else name
                    self._file.write(
                        f"  {label:<45} {elapsed:>7.1f}s  avg {avg:>5.1f}s\n"
                    )
            self._file.write("=" * 70 + "\n")
            self._file.close()

            # Write a compact summary-only file alongside the full log.
            self._write_summary_file(
                now, total_elapsed,
                outcome_status, outcome_note, failure_stage,
                final=True,
            )

        # Restore the real stdout and close the screen output log.
        # Done outside the lock so closing the file doesn't block other threads.
        if not self._stdout_restored:
            try:
                sys.stdout = self._orig_stdout
                self._stdout_restored = True
            except Exception:
                pass
        try:
            if not self._screen_log.closed:
                self._screen_log.close()
        except Exception:
            pass
        # Close any open peer log files.
        with self._peer_logs_lock:
            for _entry in self._peer_logs.values():
                with suppress(Exception):
                    if not _entry["file"].closed:
                        _entry["file"].close()

    def _write_summary_file(self, now, total_elapsed, outcome_status, outcome_note,
                            failure_stage: str = "", final: bool = False):
        """Write a human-readable summary file next to the full session log.

        Contains only the result, phase timings, and step timings — none of
        the raw console output — so it is fast to read after a run.
        """
        summary_path = self.summary_file
        _status_icon = {"PASS": "✅", "FAIL": "❌", "PASSED (WITH ERRORS)": "⚠️"}.get(outcome_status, "❓")
        if not final:
            _status_icon = "⏳"
        try:
            with open(summary_path, "w", encoding="utf-8") as sf:
                sf.write("=" * 70 + "\n")
                if final:
                    sf.write("Run Summary\n")
                else:
                    sf.write("Run Summary (LIVE - IN PROGRESS)\n")
                sf.write(f"Full log: {self.log_file}\n")
                sf.write("=" * 70 + "\n\n")

                # ---- Operation ----
                if self._operation_label:
                    sf.write("─" * 70 + "\n")
                    sf.write("Operation\n")
                    sf.write("─" * 70 + "\n")
                    sf.write(f"  {self._operation_label}\n")

                # ---- Result ----
                sf.write("─" * 70 + "\n")
                sf.write("Result\n")
                sf.write("─" * 70 + "\n")
                sf.write(f"  {'Overall Result':<25} {_status_icon} {outcome_status}\n")
                if outcome_note:
                    sf.write(f"  {'Detail':<25} {outcome_note}\n")
                if failure_stage:
                    sf.write(f"  {'Failure stage':<25} {failure_stage}\n")
                sf.write(f"  {'Errors logged':<25} {self._error_count}\n")
                sf.write(f"  {'Warnings logged':<25} {self._warn_count}\n")
                self._write_ontap_version_lines(sf)
                sf.write(f"  {'Started':<25} {self._start_time.strftime('%Y-%m-%d %H:%M:%S')}\n")
                sf.write(f"  {'Ended':<25} {now.strftime('%Y-%m-%d %H:%M:%S')}\n")
                if self._previous_run_end_time and self._resume_gap_seconds is not None:
                    sf.write(f"  {'Previous run ended':<25} {self._previous_run_end_time.strftime('%Y-%m-%d %H:%M:%S')}\n")
                    gap_min = self._resume_gap_seconds / 60
                    sf.write(f"  {'Resume gap':<25} {self._resume_gap_seconds:.1f}s ({gap_min:.1f}m)\n")
                sf.write(f"  {'Total runtime':<25} {total_elapsed:.1f}s ({total_elapsed/60:.1f}m)\n")

                # ---- Phase Timing ----
                sf.write("\n" + "─" * 70 + "\n")
                sf.write("Phase Timing\n")
                sf.write("─" * 70 + "\n")
                _phase_order = list(self._phase_times.keys())
                if self._current_phase and self._current_phase not in _phase_order:
                    _phase_order.append(self._current_phase)
                _phase_total_for_accounting = 0.0
                if _phase_order:
                    for phase in _phase_order:
                        if phase == self._current_phase and self._current_phase_start:
                            elapsed = max(
                                0.0, (now - self._current_phase_start).total_seconds()
                            )
                            ph_status = "IN PROGRESS (not yet completed)"
                            ph_icon = "⏳"
                        else:
                            elapsed = float(self._phase_times.get(phase, 0.0))
                            ph_status, _ = self._phase_outcomes.get(phase, ("", ""))
                            if not ph_status:
                                ph_status = "NOT YET COMPLETED"
                            ph_icon = {"PASS": "✅", "FAIL": "❌", "PASSED (WITH ERRORS)": "⚠️"}.get(ph_status, "⏳")
                        _phase_total_for_accounting += elapsed
                        minutes = elapsed / 60
                        ph_col = f"  {ph_icon} {ph_status}"
                        sf.write(f"  {phase:<45} {elapsed:>7.1f}s ({minutes:.1f}m){ph_col}\n")
                        _prev_node_elapsed = None
                        for sub_label, sub_elapsed in self._phase_subtimings.get(phase, []):
                            if sub_label.startswith("Node [") and _prev_node_elapsed is not None:
                                _delta = sub_elapsed - _prev_node_elapsed
                                _time_str = f"(+{_delta/60:.1f}m)"
                                _prev_node_elapsed = sub_elapsed
                            elif sub_label.startswith("Node ["):
                                _time_str = f"({sub_elapsed/60:.1f}m)"
                                _prev_node_elapsed = sub_elapsed
                            else:
                                _time_str = f"({sub_elapsed/60:.1f}m)"
                            sf.write(
                                f"     - {sub_label:<41} {sub_elapsed:>7.1f}s "
                                f"{_time_str}\n"
                            )
                else:
                    sf.write("  (No phases started yet — all phases not yet completed.)\n")
                sf.write(f"  {'─' * 55}\n")
                sf.write(f"  {'TOTAL':<45} {total_elapsed:>7.1f}s ({total_elapsed/60:.1f}m)\n")
                _pw = float(_prompt_wait_seconds)
                _paw = float(_pause_wait_seconds)
                _non_phase_breakdown = self._non_phase_breakdown(now)
                _non_phase_total = sum(_non_phase_breakdown.values()) if _non_phase_breakdown else 0.0
                _unaccounted = max(
                    0.0, total_elapsed - _phase_total_for_accounting - _non_phase_total
                )
                sf.write(
                    f"  {'Time waiting for prompts (x' + str(_prompt_wait_count) + ')':<45} "
                    f"{_pw:>7.1f}s ({_pw/60:.1f}m)\n"
                )
                if _prompt_wait_max > 0:
                    _lbl = _prompt_wait_max_label or "(no label)"
                    sf.write(
                        f"     - longest single wait: {_prompt_wait_max:.1f}s "
                        f"({_prompt_wait_max/60:.1f}m) at: {_lbl}\n"
                    )
                for _ext_lbl, _ext_sec in _prompt_wait_extended:
                    sf.write(
                        f"     - extended wait {_ext_sec:>6.1f}s "
                        f"({_ext_sec/60:.1f}m) at: {_ext_lbl or '(no label)'}\n"
                    )
                sf.write(
                    f"  {'Pause wait (x' + str(_pause_wait_count) + ')':<45} "
                    f"{_paw:>7.1f}s ({_paw/60:.1f}m)\n"
                )
                if _pause_wait_max > 0:
                    _plbl = _pause_wait_max_label or "(no label)"
                    sf.write(
                        f"     - longest single pause: {_pause_wait_max:.1f}s "
                        f"({_pause_wait_max/60:.1f}m) context: {_plbl}\n"
                    )
                sf.write(
                    f"  {'Non-phase time (classified)':<45} {_non_phase_total:>7.1f}s ({_non_phase_total/60:.1f}m)\n"
                )
                for _np_label, _np_elapsed in _non_phase_breakdown.items():
                    sf.write(
                        f"     - {_np_label:<39} {_np_elapsed:>7.1f}s ({_np_elapsed/60:.1f}m)\n"
                    )
                _residual = _unaccounted
                sf.write(
                    f"  {'Unaccounted time':<45} {_residual:>7.1f}s ({_residual/60:.1f}m)\n"
                )
                sf.write(
                    f"     - {'residual instrumentation gap':<39} {_residual:>7.1f}s ({_residual/60:.1f}m)\n"
                )

                # ---- Step Timing ----
                if self._step_times:
                    sf.write("\n" + "─" * 70 + "\n")
                    sf.write("Step Timing\n")
                    sf.write("─" * 70 + "\n")
                    for name, elapsed in self._step_times.items():
                        count = self._step_counts.get(name, 1)
                        avg = elapsed / count if count else elapsed
                        label = f"{name} (x{count})" if count > 1 else name
                        sf.write(f"  {label:<45} {elapsed:>7.1f}s  avg {avg:>5.1f}s\n")

                # ---- Warnings ----
                if self._warnings:
                    sf.write("\n" + "─" * 70 + "\n")
                    sf.write(f"Warnings ({len(self._warnings)})\n")
                    sf.write("─" * 70 + "\n")
                    # Group identical warning text together so repeated timeout
                    # messages don't produce multiple scattered "Log file"
                    # sections in the summary.
                    _warn_groups = {}
                    _warn_order = []
                    for ts, msg in self._warnings:
                        _msg_key = str(msg)
                        if _msg_key not in _warn_groups:
                            _warn_groups[_msg_key] = []
                            _warn_order.append(_msg_key)
                        _warn_groups[_msg_key].append(ts)
                    sf.write(f"  Log file: {self.log_file}\n")
                    for _idx, _msg_key in enumerate(_warn_order):
                        if _idx > 0:
                            sf.write("\n")
                        for _ts in _warn_groups.get(_msg_key, []):
                            sf.write(f"    [{_ts}] {_msg_key}\n")

                # ---- Errors ----
                if self._errors:
                    sf.write("\n" + "─" * 70 + "\n")
                    sf.write(f"Errors ({len(self._errors)})\n")
                    sf.write("─" * 70 + "\n")
                    for ts, msg in self._errors:
                        sf.write(f"  [{ts}] {msg}\n")

                sf.write("\n" + "=" * 70 + "\n")

            if final:
                print(f"📋 Summary log: {summary_path}")
        except OSError as e:
            # Non-fatal — full log is still written.
            print(f"  ⚠️  Could not write summary log: {e}")


_session_log = None
# Choices logged before _session_log exists are buffered here and flushed
# into the choices log once a session log is created.
_pre_session_choices: list = []


def _write_crash_trace(exc_type, exc_value, exc_tb, context="Unhandled exception"):
    """Write a full crash traceback to a dedicated file under logs/."""
    try:
        _script_dir = os.path.dirname(os.path.abspath(__file__))
    except NameError:
        _script_dir = os.getcwd()

    if _session_log and getattr(_session_log, "log_dir", None):
        _log_dir = _session_log.log_dir
    else:
        _ts_dir = datetime.now().strftime("%Y%m%d_%H%M%S")
        _log_dir = os.path.join(_script_dir, "logs", _ts_dir)
    os.makedirs(_log_dir, exist_ok=True)

    _ts_file = datetime.now().strftime("%Y%m%d_%H%M%S")
    _crash_path = _build_numbered_log_path(
        _log_dir, f"crash_trace_{_ts_file}.log", scope_dir=_log_dir
    )
    with open(_crash_path, "w", encoding="utf-8") as _cf:
        _cf.write("=" * 70 + "\n")
        _cf.write("AFX_reinit crash trace\n")
        _cf.write(f"Timestamp: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
        _cf.write(f"Host: {platform.node()}\n")
        _cf.write(f"Python: {sys.version}\n")
        _cf.write(f"Context: {context}\n")
        _cf.write("=" * 70 + "\n\n")
        traceback.print_exception(exc_type, exc_value, exc_tb, file=_cf)
    return _crash_path


def _slog(msg, prefix="INFO"):
    """Shorthand: write *msg* to the active session log (no-op if none set)."""
    if _session_log:
        _session_log.log(msg, prefix=prefix)


# ---------------------------------------------------------------------------
# Operation mode selection
# ---------------------------------------------------------------------------

_operation_mode = None
# Set to True when 4.1 redirects to 4e for config creation; causes 4e to
# continue directly into 4.1 after the config is written.
_4a_pending_after_4e = False
# Set to True when 5.5 redirects to 4e for config creation; causes 4e to
# return to 5.5 after the config is written.
_5f_pending_after_4e = False
# Set to True when 5.11 redirects to 4e for config creation; causes the
# dispatch loop to run mode 46 instead of returning to the menu.
_46_pending_after_511 = False
# When True (1.2 / 3 primary), the script auto-answers all post-option-9
# prompts and drives the cluster setup wizard non-interactively.
_auto_setup = False
# When True (2.2 / 3 peers), the script auto-drives the join wizard for an
# existing cluster after option 4.
_auto_add = False
# Set when the start menu checkpoint prompt has already confirmed a 4.2 resume.
_resume_from_start_menu = False
# Directory suffix for resumed-run logs (e.g. "_cp_1_2").
_resume_checkpoint_log_suffix = ""
# Global checkpoint-resume context used by connection/setup helpers.
_checkpoint_mode = None
_resume_cp_start = None


def _checkpoint_resume_active() -> bool:
    """Return True when execution is currently in checkpoint-resume flow."""
    _mode = str(globals().get("_checkpoint_mode") or "").strip().lower()
    _start = globals().get("_resume_cp_start")
    return _mode in {"1", "2", "3", "4.2"} and _start not in (None, "")


def _checkpoint_menu_option_label(cp_mode: str) -> str:
    """Best-effort menu-option label for a checkpoint mode string."""
    _m = str(cp_mode or "").strip().lower()
    if _m.startswith("4.2"):
        return "4.2"
    if _m == "3":
        return "3"
    if _m == "2":
        return "2.2"
    if _m == "1":
        return "1 (Automatic reinit of primary node in cluster/cluster creation)"
    return cp_mode or "unknown"


def _checkpoint_mode_to_test_key(raw_mode: str):
    _raw_mode = str(raw_mode or "").strip().lower()
    if _raw_mode.startswith("4.2"):
        return 42
    if _raw_mode.startswith("4.1"):
        return 41
    if _raw_mode.startswith("4.3"):
        return 43
    if _raw_mode == "3":
        return 3
    if _raw_mode == "2":
        return 2
    if _raw_mode == "1":
        return 1
    return None


def _print_checkpoint_list() -> None:
    """Print all available checkpoint IDs grouped by operation mode."""
    _mode_rows = [
        (1, "1", "Initialize first node"),
        (2, "2", "Add nodes"),
        (3, "3", "End-to-end auto initialize"),
        (41, "4.1", "ONTAP rolling upgrade"),
        (42, "4.2", "Netboot + automated cluster reinit"),
        (43, "4.3", "Netboot install image only"),
    ]
    print("Available checkpoints by mode:\n")
    for _mode_key, _mode_label, _mode_desc in _mode_rows:
        _options = list(_CHECKPOINT_TEST_OPTIONS.get(_mode_key) or [])
        if not _options:
            continue
        print(
            f"  Mode {_mode_label} ({_mode_desc}) — "
            f"{len(_options)} checkpoint(s)"
        )
        for _idx, (_cp_id, _cp_desc) in enumerate(_options, 1):
            print(f"    {_idx:>2}. {_cp_id:<18} {_cp_desc}")
        print("")


def _checkpoint_phase_recorded_done(cp, phase_id: str) -> bool:
    if not cp:
        return False
    _phase_id = str(phase_id or "").strip()
    if not _phase_id:
        return False
    try:
        if cp.is_done(_phase_id):
            return True
    except Exception:
        pass
    try:
        return bool(cp.nodes_done_for(_phase_id))
    except Exception:
        return False


def _checkpoint_4x_target_node_ids(cp) -> "list[str]":
    _targets = []
    if not cp:
        return _targets
    for _ip in (getattr(cp, "bmc_ips", []) or []):
        _node_id = str(_ip or "").strip()
        if _node_id and _node_id not in _targets:
            _targets.append(_node_id)
    return _targets


def _checkpoint_4x_nodes_done_for_runtime_phase(cp, phase_id: str) -> "list[str]":
    _done_nodes = []
    if not cp:
        return _done_nodes
    try:
        for _nid in (cp.nodes_done_for(phase_id) or []):
            _node_id = str(_nid or "").strip()
            if _node_id and _node_id not in _done_nodes:
                _done_nodes.append(_node_id)
    except Exception:
        pass
    return _done_nodes


def _checkpoint_4x_parallel_phase_state(cp, mode_key, phase_id: str) -> dict:
    """Return all-target runtime state for 4.2/4.3 parallel checkpoint phases."""
    _state = {
        "requires_all_targets": False,
        "target_node_ids": [],
        "done_node_ids": [],
        "all_targets_done": False,
        "legacy_global_hint": False,
        "requires_transition_evidence": False,
        "transition_node_ids": [],
        "has_transition_evidence": False,
    }
    if not cp or mode_key not in (42, 43):
        return _state

    _phase_id = str(phase_id or "").strip()
    _seq = [str(_cp_id).strip() for _cp_id, __ in (_CHECKPOINT_TEST_OPTIONS.get(mode_key) or [])]
    if _phase_id not in _seq:
        return _state

    _state["requires_all_targets"] = True
    _targets = _checkpoint_4x_target_node_ids(cp)
    _state["target_node_ids"] = _targets

    _done_nodes = []
    def _add_done_nodes(_phase_name: str, *, legacy_global_targets: bool = False) -> None:
        nonlocal _done_nodes
        _source_nodes = (
            _checkpoint_4x_nodes_done_for_runtime_phase(cp, _phase_name)
            if legacy_global_targets else
            list(cp.nodes_done_for(_phase_name) or [])
        )
        for _nid in _source_nodes:
            _node_id = str(_nid or "").strip()
            if _node_id and _node_id not in _done_nodes:
                _done_nodes.append(_node_id)

    _add_done_nodes(_phase_id)
    _phase_idx = _checkpoint_phase_index(mode_key, _phase_id)
    for _later_id, __ in (_CHECKPOINT_TEST_OPTIONS.get(mode_key) or []):
        if _checkpoint_phase_index(mode_key, _later_id) > _phase_idx:
            _add_done_nodes(_later_id)
    for _runtime_phase in (
        ["install_done", "reinit_loader"]
        + (["option6_done"] if mode_key == 43 else [])
    ):
        _add_done_nodes(_runtime_phase, legacy_global_targets=True)
    _state["done_node_ids"] = _done_nodes

    if mode_key == 42 and _phase_id == "cp_42_6":
        _transition_nodes = _checkpoint_4x_nodes_done_for_runtime_phase(cp, "reinit_loader")
        _state["requires_transition_evidence"] = True
        _state["transition_node_ids"] = _transition_nodes
        _target_node_set = set(_targets)
        _state["has_transition_evidence"] = bool(
            set(_transition_nodes) & (_target_node_set or set(_done_nodes))
        )

    _global_done = False
    try:
        _global_done = bool(cp.is_done(_phase_id))
    except Exception:
        _global_done = False

    _done_node_set = set(_done_nodes)
    if _targets:
        _state["all_targets_done"] = all(_nid in _done_node_set for _nid in _targets)
        if (not _state["all_targets_done"]
                and _global_done
                and len(_targets) == 1
                and not _done_nodes):
            _state["all_targets_done"] = True

    _state["legacy_global_hint"] = bool(
        _targets and _global_done and not _state["all_targets_done"]
    )
    return _state


def _checkpoint_4x_highest_legacy_global_hint(cp, mode_key) -> str:
    if not cp or mode_key not in (42, 43):
        return ""
    _hint = ""
    for _cp_id, __ in (_CHECKPOINT_TEST_OPTIONS.get(mode_key) or []):
        _state = _checkpoint_4x_parallel_phase_state(cp, mode_key, _cp_id)
        if _state.get("legacy_global_hint"):
            _hint = _cp_id
    return _hint


def _checkpoint_phase_effectively_done(cp, mode_key, phase_id: str) -> bool:
    """Treat later checkpoints as implying earlier ones for resume/status UX."""
    _phase_id = str(phase_id or "").strip()
    if not _phase_id:
        return False
    _mode_key = mode_key

    def _phase_recorded_done(_cp_id: str) -> bool:
        _id = str(_cp_id or "").strip()
        if not _id:
            return False
        if _mode_key in (2, 3) and _id.startswith("cp_2_"):
            _bmc_ips = [str(_ip).strip() for _ip in (getattr(cp, "bmc_ips", []) or []) if str(_ip).strip()]
            _targets = _bmc_ips[1:] if _mode_key == 3 else _bmc_ips
            if _targets:
                try:
                    if cp.is_done(_id):
                        return True
                except Exception:
                    pass
                return all(_checkpoint_phase_done_for_peer_resume(_id, _nid) for _nid in _targets)
        if _mode_key in (42, 43):
            _state = _checkpoint_4x_parallel_phase_state(cp, _mode_key, _id)
            if _state.get("requires_all_targets"):
                if (_state.get("all_targets_done")
                        and (not _state.get("requires_transition_evidence")
                             or _state.get("has_transition_evidence"))):
                    return True
                if _state.get("target_node_ids"):
                    return False
        return _checkpoint_phase_recorded_done(cp, _id)

    if _phase_recorded_done(_phase_id):
        return True

    _checkpoint_seq = list(_CHECKPOINT_TEST_OPTIONS.get(_mode_key) or [])
    _idx = -1
    for _i, (_cp_id, __) in enumerate(_checkpoint_seq):
        if _cp_id == _phase_id:
            _idx = _i
            break
    if _idx < 0:
        return False

    _family = ""
    if _phase_id.startswith("cp_1_"):
        _family = "cp_1_"
    elif _phase_id.startswith("cp_2_"):
        _family = "cp_2_"

    for _later_id, __ in _checkpoint_seq[_idx + 1:]:
        if _mode_key == 3 and _family:
            if _family == "cp_1_" and not _later_id.startswith("cp_1_"):
                continue
            if _family == "cp_2_" and not (
                _later_id.startswith("cp_2_") or _later_id == "option3_complete"
            ):
                continue
        if _phase_recorded_done(_later_id):
            return True
    return False


def _checkpoint_resume_stage_label(cp) -> str:
    """Human-readable checkpoint stage summary for menu prompt context."""
    if not cp:
        return "Unknown stage"
    _mode = str(getattr(cp, "mode", "") or "").strip().lower()
    _mode_key = _checkpoint_mode_to_test_key(_mode)
    _checkpoint_seq = list(_CHECKPOINT_TEST_OPTIONS.get(_mode_key) or [])
    _legacy_4x_hint = _checkpoint_4x_highest_legacy_global_hint(cp, _mode_key)
    for _cp_id, _cp_desc in _checkpoint_seq:
        if not _checkpoint_phase_effectively_done(cp, _mode_key, _cp_id):
            if _legacy_4x_hint and _mode_key in (42, 43):
                _hint_idx = _checkpoint_phase_index(_mode_key, _legacy_4x_hint)
                _next_idx = _checkpoint_phase_index(_mode_key, _cp_id)
                if _hint_idx > _next_idx:
                    return (
                        f"Legacy {_legacy_4x_hint} global hint detected; "
                        f"earliest safe all-node resume is {_cp_desc}."
                    )
            return _cp_desc

    # If all known checkpoints for this mode are done, keep mode-specific
    # context for clarity in the menu prompt.
    if _mode.startswith("4.2") or _mode.startswith("4.3"):
        return _describe_4b_resume_stage(cp)
    return "All checkpoints completed."


def _checkpoint_resume_phase_id(cp) -> str:
    """Return the next checkpoint ID for the loaded checkpoint, if any."""
    if not cp:
        return ""
    _mode = str(getattr(cp, "mode", "") or "").strip().lower()
    _mode_key = _checkpoint_mode_to_test_key(_mode)
    _checkpoint_seq = list(_CHECKPOINT_TEST_OPTIONS.get(_mode_key) or [])
    for _cp_id, _cp_desc in _checkpoint_seq:
        if not _checkpoint_phase_effectively_done(cp, _mode_key, _cp_id):
            return _cp_id
    return ""


def _checkpoint_phase_index(mode_key, phase_id: str) -> int:
    """Return 1-based checkpoint index for a phase within a mode; 0 when unknown."""
    _phase = str(phase_id or "").strip()
    if not _phase:
        return 0
    _seq = list(_CHECKPOINT_TEST_OPTIONS.get(mode_key) or [])
    for _idx, (_cp_id, __) in enumerate(_seq, 1):
        if _cp_id == _phase:
            return _idx
    return 0


def _checkpoint_stage_tag(mode_key, phase_id: str) -> str:
    """Stable stage tag used to identify checkpoint position and prevent drift."""
    _phase = str(phase_id or "").strip()
    _idx = _checkpoint_phase_index(mode_key, _phase)
    if not _phase or _idx <= 0:
        return ""
    return f"m{mode_key}:i{_idx}:{_phase}"


def _checkpoint_reconcile_runtime_stage(runtime_phase_id: str, *, context: str = "",
                                        cp_obj=None) -> bool:
    """Align selected resume stage with live runtime-detected stage.

    Prevents accidental or intentional wrong checkpoint starts from causing
    repeated or skipped steps when live prompt state disagrees with selection.
    """
    global _resume_cp_start
    _runtime = str(runtime_phase_id or "").strip()
    if not _runtime:
        return False
    _cp = cp_obj or _checkpoint
    if not _cp:
        return False
    _mode_raw = str(getattr(_cp, "mode", "") or "").strip().lower()
    _mode_key = _checkpoint_mode_to_test_key(_mode_raw)
    if _checkpoint_phase_index(_mode_key, _runtime) <= 0:
        return False
    _selected = str(_resume_cp_start or "").strip()
    if not _selected:
        _selected = str(_checkpoint_resume_phase_id(_cp) or "").strip()
    if not _selected or _selected == _runtime:
        return False

    _sel_idx = _checkpoint_phase_index(_mode_key, _selected)
    _run_idx = _checkpoint_phase_index(_mode_key, _runtime)
    if _sel_idx <= 0 or _run_idx <= 0 or _sel_idx == _run_idx:
        return False

    _sel_tag = _checkpoint_stage_tag(_mode_key, _selected)
    _run_tag = _checkpoint_stage_tag(_mode_key, _runtime)
    _ctx = f" ({context})" if context else ""
    _dir = "repeat-risk" if _sel_idx < _run_idx else "skip-risk"
    print(
        f"  ⚠️  Runtime checkpoint guard{_ctx}: selected {_selected} [{_sel_tag}] "
        f"does not match detected {_runtime} [{_run_tag}] ({_dir})."
    )
    print(f"     ✅ Auto-aligning resume stage to {_runtime} to prevent step drift.")
    _slog(
        f"runtime checkpoint guard{_ctx}: selected={_selected}({_sel_tag}) "
        f"detected={_runtime}({_run_tag}) -> auto-align",
        prefix="WARN",
    )

    _applied = _checkpoint_apply_manual_resume_target(_cp, _runtime)
    if _applied:
        _resume_cp_start = _runtime
    return bool(_applied)


def _checkpoint_phase_description(phase_id: str) -> str:
    """Return human-readable description of a checkpoint phase ID."""
    _id = str(phase_id or "").strip()
    
    _all_descs = {
       # Mode 1
       "cp_1_1": "LOADER options set",
       "cp_1_2": "Option 9 confirmed",
       "cp_1_3": "Option-9 abort answered",
       "cp_1_4": "Option 4 started",
       "cp_1_5": "Option 4 completed",
       "cp_1_6": "AutoSupport confirmation answered",
       "cp_1_7": "Cluster setup started",
       **{_cp_id: _cp_desc for _cp_id, _cp_desc in _CP_1_7_SUBCHECKPOINTS},
       "cp_1_8": "Cluster creation complete",
       # Mode 2
       "cp_2_1": "LOADER reached",
       "cp_2_2": "Boot menu issued",
       "cp_2_3": "Option 4 issued",
       "cp_2_4": "Option 4 completed",
       "cp_2_5": "Node management configured",
       "cp_2_6": "Cluster setup menu",
       "cp_2_7": "Node joined",
       "cp_2_8": "Node addition job completed",
       # Mode 4.2
       "cp_4b_1": "Nodes at LOADER",
       "cp_4b_2": "Netboot started",
       "cp_4b_3": "Option 7 selected",
       "cp_4b_4": "Image downloaded",
       "cp_4b_5": "Image installed",
       "cp_4b_6": "Mode 1/2 checkpoints continue",
    }
    return _all_descs.get(_id, "")


def _format_checkpoint_phase_with_delta(phase_id: str, ts_str: str, prev_ts_str: str = "") -> str:
    """Format checkpoint phase with description and optional time delta.
    
    Args:
       phase_id: checkpoint ID (e.g., "cp_1_1")
       ts_str: ISO timestamp string of this phase
       prev_ts_str: ISO timestamp string of previous phase (for delta calculation)
    
    Returns:
       Formatted string like "cp_1_1 LOADER options set  [+12.3s]"
    """
    _desc = _checkpoint_phase_description(phase_id)
    _desc_part = f" {_desc}" if _desc else ""
    
    _delta_part = ""
    if prev_ts_str and ts_str:
       try:
           _prev_dt = datetime.fromisoformat(prev_ts_str)
           _curr_dt = datetime.fromisoformat(ts_str)
           _delta_sec = (_curr_dt - _prev_dt).total_seconds()
           if _delta_sec >= 0:
               _delta_part = f"  [+{_delta_sec:.1f}s]"
       except Exception:
           pass
    
    return f"{phase_id}{_desc_part}{_delta_part}"
def _checkpoint_apply_manual_resume_target(cp, target_phase_id: str) -> bool:
    """Rewrite checkpoint markers so resume starts from *target_phase_id*."""
    if not cp:
        return False
    _mode_key = _checkpoint_mode_to_test_key(getattr(cp, "mode", ""))
    _checkpoint_seq = list(_CHECKPOINT_TEST_OPTIONS.get(_mode_key) or [])
    _target = str(target_phase_id or "").strip()
    if not _target or not _checkpoint_seq:
        return False

    _target_idx = -1
    for _idx, (_cp_id, __) in enumerate(_checkpoint_seq):
        if _cp_id == _target:
            _target_idx = _idx
            break
    if _target_idx < 0:
        return False

    _now = datetime.now().isoformat()
    _phases = cp._data.setdefault("phases", {})
    _node_phases = cp._data.setdefault("node_phases", {})
    _all_bmcs = [
        str(_ip).strip() for _ip in (cp.bmc_ips or [])
        if str(_ip).strip()
    ]
    _primary_bmc = _all_bmcs[0] if _all_bmcs else ""
    _peer_bmcs = _all_bmcs[1:] if _mode_key == 3 else list(_all_bmcs)

    def _phase_node_ids(_cp_id: str) -> "list[str]":
        if _mode_key in (42, 43):
            return list(
                _checkpoint_4x_parallel_phase_state(cp, _mode_key, _cp_id).get("target_node_ids") or []
            )
        if _mode_key == 2:
            return list(_all_bmcs)
        if _mode_key == 3:
            if str(_cp_id or "").startswith("cp_1_"):
                return [_MODE3_PRIMARY_CHECKPOINT_NODE] if _primary_bmc else []
            if str(_cp_id or "").startswith("cp_2_"):
                _ids = []
                for _b in _peer_bmcs:
                    if _b and _b not in _ids:
                        _ids.append(_b)  # backward-compatible legacy node-id form
                    _peer_id = _mode3_peer_checkpoint_node(_b)
                    if _peer_id and _peer_id not in _ids:
                        _ids.append(_peer_id)
                return _ids
        return []

    for _idx, (_cp_id, __) in enumerate(_checkpoint_seq):
        _cp_node_ids = _phase_node_ids(_cp_id)
        _rewrite_4x_nodes = (_mode_key in (42, 43) and bool(_cp_node_ids))
        if _idx < _target_idx:
            _meta = _phases.get(_cp_id) or {}
            if not _meta.get("done"):
                _phases[_cp_id] = {"done": True, "ts": _now}
            if _cp_node_ids:
                if _rewrite_4x_nodes:
                    _node_phases[_cp_id] = {
                        _nid: {"done": True, "ts": _now}
                        for _nid in _cp_node_ids
                    }
                else:
                    _per = _node_phases.setdefault(_cp_id, {})
                    for _nid in _cp_node_ids:
                        _per[_nid] = {"done": True, "ts": _now}
        else:
            _phases.pop(_cp_id, None)
            if _mode_key in (42, 43):
                _node_phases.pop(_cp_id, None)
            elif _cp_node_ids:
                if _cp_id in _node_phases:
                    for _nid in _cp_node_ids:
                        _node_phases[_cp_id].pop(_nid, None)
                    if not _node_phases[_cp_id]:
                        _node_phases.pop(_cp_id, None)
            else:
                _node_phases.pop(_cp_id, None)

    def _set_exact_node_phase(_phase_name: str, _node_ids) -> None:
        _targets = []
        for _nid in (_node_ids or []):
            _node_id = str(_nid or "").strip()
            if _node_id and _node_id not in _targets:
                _targets.append(_node_id)
        if not _targets:
            _node_phases.pop(_phase_name, None)
            return
        _node_phases[_phase_name] = {
            _nid: {"done": True, "ts": _now}
            for _nid in _targets
        }

    if _mode_key in (42, 43):
        for _phase_name in (
            "primary_bootmenu_done",
            "primary_node_mgmt_done",
            "primary_setup_done",
            "cluster_formed",
            "option3_complete",
            "node_joined",
        ):
            _phases.pop(_phase_name, None)
        for _phase_name in list(_phases.keys()):
            if _phase_name.startswith("cp_1_") or _phase_name.startswith("cp_2_"):
                _phases.pop(_phase_name, None)
        for _phase_name in list(_node_phases.keys()):
            if (_phase_name.startswith("cp_1_")
                        or _phase_name.startswith("cp_2_")
                        or _phase_name in (
                            "peer_option4_done",
                            "peer_joined",
                            "install_done",
                            "option6_done",
                            "reinit_loader",
                        )):
                _node_phases.pop(_phase_name, None)
        _last_4x_idx = len(_checkpoint_seq) - 1
        if _target_idx >= _last_4x_idx and _all_bmcs:
            if _mode_key == 42:
                _set_exact_node_phase("install_done", _all_bmcs)
            else:
                _set_exact_node_phase("install_done", [])
                _set_exact_node_phase("option6_done", [])
        else:
            _set_exact_node_phase("install_done", [])
            _set_exact_node_phase("option6_done", [])
        _set_exact_node_phase("reinit_loader", [])

    _global_aliases = [
        ("cp_1_5", "primary_bootmenu_done"),
        ("cp_1_6", "primary_node_mgmt_done"),
        ("cp_1_8", "cluster_formed"),
        ("cp_1_8", "primary_setup_done"),
        ("cp_2_7", "node_joined"),
    ]
    for _src_cp, _alias in _global_aliases:
        _done = _checkpoint_phase_effectively_done(cp, _mode_key, _src_cp)
        if _done:
            _meta = _phases.get(_alias) or {}
            if not _meta.get("done"):
                _phases[_alias] = {"done": True, "ts": _now}
        else:
            _phases.pop(_alias, None)

    _node_aliases = {
        "cp_2_4": "peer_option4_done",
        "cp_2_7": "peer_joined",
    }
    for _src_cp, _alias in _node_aliases.items():
        _done = _checkpoint_phase_effectively_done(cp, _mode_key, _src_cp)
        _alias_node_ids = _all_bmcs if _mode_key == 2 else (_peer_bmcs if _mode_key == 3 else [])
        if _alias_node_ids:
            if _done:
                _per = _node_phases.setdefault(_alias, {})
                for _nid in _alias_node_ids:
                    _per[_nid] = {"done": True, "ts": _now}
            else:
                if _alias in _node_phases:
                    for _nid in _alias_node_ids:
                        _node_phases[_alias].pop(_nid, None)
                    if not _node_phases[_alias]:
                        _node_phases.pop(_alias, None)
        elif not _done:
            _node_phases.pop(_alias, None)

    cp._save()
    return True


def _checkpoint_mode_choice_to_value(choice: str) -> str:
    _c = str(choice or "").strip().lower()
    if _c in ("1", "mode1"):
        return "1"
    if _c in ("2", "2.2", "2x", "mode2"):
        return "2"
    if _c in ("3", "mode3"):
        return "3"
    if _c in ("4.2", "42", "mode4.2"):
        return "4.2"
    return ""


def _extract_bmc_lists_from_config_dict(cfg: dict) -> "tuple[str, list[str]]":
    _primary = ""
    _secondary = []
    if not isinstance(cfg, dict):
        return "", []
    _pn = cfg.get("primary_node")
    if isinstance(_pn, dict):
        _primary = str(_pn.get("bmc") or "").strip()
    _sn = cfg.get("secondary_nodes")
    if isinstance(_sn, list):
        for _n in _sn:
            if isinstance(_n, dict):
                _b = str(_n.get("bmc") or "").strip()
                if _b and _b not in _secondary:
                    _secondary.append(_b)
    if not _primary and not _secondary:
        _nodes = cfg.get("nodes")
        if isinstance(_nodes, list):
            for _idx, _n in enumerate(_nodes):
                if not isinstance(_n, dict):
                    continue
                _b = str(_n.get("bmc") or "").strip()
                if not _b:
                    continue
                if _idx == 0:
                    _primary = _b
                elif _b not in _secondary:
                    _secondary.append(_b)
    return _primary, _secondary


def _load_config_for_checkpoint_override() -> "tuple[dict, str]":
    _detected = _find_config_files(deep_scan=True)
    _path = _select_config_path_interactive(_detected, indent="     ", header_emoji="📄")
    if not _detected and not _path:
        _raw = _prompt("     Config path (optional, Enter to skip): ", "").strip()
        if _raw:
            _candidate = os.path.expanduser(os.path.expandvars(_raw))
            if os.path.isfile(_candidate):
                _path = _candidate
            else:
                print(f"     ⚠️  File not found: {_candidate}")
    if not _path:
        return {}, ""
    try:
        return load_config_file(_path), _path
    except ValueError as _e:
        print(f"     ⚠️  {_e}")
        return {}, ""


def _normalize_node_override_phase(raw_value, default_mode_key: int) -> str:
    _rv = str(raw_value or "").strip().lower()
    if not _rv:
        return ""
    if _rv.startswith("cp_"):
        return _rv
    _suffix = ""
    if _rv.isdigit():
        _suffix = _rv
    elif "." in _rv:
        _parts = _rv.split(".")
        if _parts and _parts[-1].isdigit():
            _suffix = _parts[-1]
    if not _suffix:
        return ""
    return f"cp_{default_mode_key}_{_suffix}"


def _set_node_phase_target(cp, node_id: str, mode_key: int, target_phase_id: str) -> bool:
    _seq = list(_CHECKPOINT_TEST_OPTIONS.get(mode_key) or [])
    if not _seq:
        return False
    _target = str(target_phase_id or "").strip()
    _target_idx = -1
    for _idx, (_cp_id, __) in enumerate(_seq):
        if _cp_id == _target:
            _target_idx = _idx
            break
    if _target_idx < 0:
        return False
    _np = cp._data.setdefault("node_phases", {})
    _now = datetime.now().isoformat()
    _nid = str(node_id or "").strip()
    if not _nid:
        return False
    for _idx, (_cp_id, __) in enumerate(_seq):
        if _idx < _target_idx:
            _np.setdefault(_cp_id, {})[_nid] = {"done": True, "ts": _now}
        else:
            if _cp_id in _np:
                _np[_cp_id].pop(_nid, None)
                if not _np[_cp_id]:
                    _np.pop(_cp_id, None)
    return True


def _apply_node_overrides_from_config(cp) -> int:
    """Apply per-node checkpoint overrides from config JSON when present.

    Supported node keys: checkpoint_override, checkpoint_phase_override,
    resume_checkpoint, checkpoint_phase.
    """
    if not cp:
        return 0
    _cfg_path = str(getattr(cp, "config_path", "") or "").strip()
    if not _cfg_path or not os.path.isfile(_cfg_path):
        return 0
    try:
        _cfg = load_config_file(_cfg_path)
    except Exception:
        return 0

    _mode_key = _checkpoint_mode_to_test_key(cp.mode)
    if _mode_key not in (2, 3):
        return 0

    _applied = 0
    _entries = []
    _pn = _cfg.get("primary_node")
    if isinstance(_pn, dict):
        _entries.append(("primary", _pn))
    for _sn in (_cfg.get("secondary_nodes") or []):
        if isinstance(_sn, dict):
            _entries.append(("secondary", _sn))
    if not _entries:
        for _idx, _n in enumerate(_cfg.get("nodes") or []):
            if isinstance(_n, dict):
                _entries.append(("primary" if _idx == 0 else "secondary", _n))

    for _role, _node in _entries:
        _bmc = str(_node.get("bmc") or "").strip()
        if not _bmc:
            continue
        _raw = (
            _node.get("checkpoint_override")
            or _node.get("checkpoint_phase_override")
            or _node.get("resume_checkpoint")
            or _node.get("checkpoint_phase")
        )
        if not _raw:
            continue

        if _mode_key == 2:
            _target = _normalize_node_override_phase(_raw, 2)
            _node_id = _bmc
        else:
            if _role == "primary":
                _target = _normalize_node_override_phase(_raw, 1)
                _node_id = _MODE3_PRIMARY_CHECKPOINT_NODE
            else:
                _target = _normalize_node_override_phase(_raw, 2)
                _node_id = _mode3_peer_checkpoint_node(_bmc)
        if not _target:
            continue
        _target_mode_key = 1 if (_mode_key == 3 and _role == "primary") else 2
        if not _set_node_phase_target(cp, _node_id, _target_mode_key, _target):
            continue
        if _mode_key == 3 and _role == "primary":
            _phases = cp._data.setdefault("phases", {})
            _now = datetime.now().isoformat()
            _p_alias = [
                ("cp_1_5", "primary_bootmenu_done"),
                ("cp_1_6", "primary_node_mgmt_done"),
                ("cp_1_8", "primary_setup_done"),
                ("cp_1_8", "cluster_formed"),
            ]
            _seq1 = [c for c, __ in (_CHECKPOINT_TEST_OPTIONS.get(1) or [])]
            _ti = _seq1.index(_target) if _target in _seq1 else -1
            for _cp_id, _alias in _p_alias:
                _ci = _seq1.index(_cp_id) if _cp_id in _seq1 else -1
                if _ti >= 0 and _ci >= 0 and _ci < _ti:
                    _phases[_alias] = {"done": True, "ts": _now}
                else:
                    _phases.pop(_alias, None)
        _applied += 1

    if _applied:
        cp._save()
    return _applied


def _create_checkpoint_for_manual_override() -> "CheckpointManager | None":
    print("\n  No checkpoint file found. You can create one now and apply overrides.")
    while True:
        _m = _prompt("  Create manual checkpoint for mode [1/2/3/4.2] (Enter=cancel): ", "").strip().lower()
        if not _m:
            return None
        _mode = _checkpoint_mode_choice_to_value(_m)
        if _mode:
            break
        print("  ⚠️  Invalid mode. Enter 1, 2, 3, or 4.2.")

    _cfg_data, _cfg_path = _load_config_for_checkpoint_override()
    _primary, _secondary = _extract_bmc_lists_from_config_dict(_cfg_data)
    if _mode == "1":
        _bmc_ips = [_primary] if _primary else []
    elif _mode == "2":
        _bmc_ips = list(_secondary)
    else:
        _bmc_ips = []
        if _primary:
            _bmc_ips.append(_primary)
        for _ip in _secondary:
            if _ip and _ip not in _bmc_ips:
                _bmc_ips.append(_ip)

    if _mode in ("2", "3", "4.2") and not _bmc_ips:
        _raw_ips = _prompt(
            "  Enter BMC IP(s), comma-separated (optional): ",
            "",
        ).strip()
        if _raw_ips:
            _bmc_ips = [x.strip() for x in _raw_ips.split(",") if x.strip()]

    _cp = CheckpointManager()
    _cp.init_run(mode=_mode, bmc_ips=_bmc_ips, log_dir="", config_path=_cfg_path)
    print(f"  ✅ Created checkpoint skeleton: mode={_mode}, nodes={len(_bmc_ips)}")
    return _cp


def _per_node_next_checkpoint_groups(cp, mode_key):
    """Group peer BMCs by their individual next pending cp_2_x checkpoint.

    Used to detect when nodes in a multi-node run are at different stages.
    Returns [] when there is only one peer, or all peers share the same next
    checkpoint (no per-group prompting needed).

    Otherwise returns a list of (next_cp_id, next_cp_desc, [bmc, ...])
    sorted by checkpoint sequence order (most behind first).
    """
    _all_bmcs = [str(_ip).strip() for _ip in (getattr(cp, "bmc_ips", []) or []) if str(_ip).strip()]
    _peer_bmcs = _all_bmcs[1:] if mode_key == 3 else list(_all_bmcs)
    if len(_peer_bmcs) < 2:
        return []

    _peer_seq = list(_CHECKPOINT_TEST_OPTIONS.get(2) or [])

    _node_next: dict = {}
    for _bmc in _peer_bmcs:
        _next_id = ""
        _next_desc = "All completed"
        for _cp_id, _cp_desc in _peer_seq:
            if not _checkpoint_phase_resume_evidence_for_peer(cp, _cp_id, _bmc):
                _next_id = _cp_id
                _next_desc = _cp_desc
                break
        _node_next[_bmc] = (_next_id, _next_desc)

    if len({v[0] for v in _node_next.values()}) <= 1:
        return []

    _cp_order = {_cp_id: _idx for _idx, (_cp_id, __) in enumerate(_peer_seq)}
    _groups_map: dict = {}
    for _bmc in _peer_bmcs:
        _next_id, _next_desc = _node_next[_bmc]
        if _next_id not in _groups_map:
            _groups_map[_next_id] = (_next_desc, [])
        _groups_map[_next_id][1].append(_bmc)

    _sorted_ids = sorted(_groups_map, key=lambda cid: _cp_order.get(cid, 9999))
    return [(_cp_id, _groups_map[_cp_id][0], _groups_map[_cp_id][1]) for _cp_id in _sorted_ids]


def _prompt_checkpoint_resume_target_override(cp) -> bool:
    """Let operator optionally override resume start checkpoint.

    For multi-node modes (2/3) where nodes are at different stages, groups
    nodes by their individual next checkpoint and prompts once per group
    instead of asking about every node separately.  When all nodes share the
    same next checkpoint a single prompt is shown (existing behaviour).
    """
    if not cp:
        return False
    _mode_key = _checkpoint_mode_to_test_key(getattr(cp, "mode", ""))
    _checkpoint_seq = list(_CHECKPOINT_TEST_OPTIONS.get(_mode_key) or [])
    if not _checkpoint_seq:
        return False
    _node_applied = _apply_node_overrides_from_config(cp)
    if _node_applied:
        print(f"     Applied {_node_applied} per-node override(s) from config file.")

    _detected_next = _checkpoint_resume_phase_id(cp)
    _display_default = _detected_next or "(first checkpoint)"

    # ── Multi-node path: nodes at different stages ────────────────────────
    _groups = _per_node_next_checkpoint_groups(cp, _mode_key)
    if _groups:
        _peer_seq = list(_CHECKPOINT_TEST_OPTIONS.get(2) or [])
        _id_lookup = {_cp_id.lower(): _cp_id for _cp_id, __ in _peer_seq}
        print(f"     Detected next (overall): {_display_default}")
        print("     Nodes are at different checkpoint stages — review each group below.")
        print()
        for _idx, (_cp_id, _cp_desc) in enumerate(_peer_seq, 1):
            print(f"       {_idx:>2}. {_cp_id:<14} {_cp_desc}")
        print()
        _any_overridden = False
        for _grp_cp_id, _grp_cp_desc, _grp_bmcs in _groups:
            _n = len(_grp_bmcs)
            _node_str = ", ".join(_grp_bmcs)
            print(f"     Group: {_grp_cp_id}  —  {_grp_cp_desc}  [{_n} node{'s' if _n != 1 else ''}]")
            print(f"       Nodes: {_node_str}")
            while True:
                _sel = _prompt(
                    f"     Override [Enter=keep {_grp_cp_id}, number 1-{len(_peer_seq)}, or cp_id]: ",
                    "",
                ).strip().lower()
                if not _sel:
                    break
                _target = ""
                if _sel.isdigit():
                    _pick = int(_sel)
                    if 1 <= _pick <= len(_peer_seq):
                        _target = _peer_seq[_pick - 1][0]
                else:
                    _target = _id_lookup.get(_sel, "")
                if not _target:
                    print("     ⚠️  Invalid selection. Use Enter, a list number, or a cp_id.")
                    continue
                if _target == _grp_cp_id:
                    print("     ℹ️  Selected checkpoint is already this group's detected stage.")
                    break
                _target_desc = next((d for c, d in _peer_seq if c == _target), "")
                _confirm = _prompt(
                    f"     Confirm override to {_target}"
                    f"{f' ({_target_desc})' if _target_desc else ''}"
                    f" for {_n} node(s)? [y/N]: ",
                    "n",
                ).strip().lower()
                if _confirm not in ("y", "yes"):
                    print("     Override not applied. Choose another or press Enter to keep.")
                    continue
                for _bmc in _grp_bmcs:
                    _set_node_phase_target(cp, _bmc, 2, _target)
                    if _mode_key == 3:
                        _set_node_phase_target(cp, _mode3_peer_checkpoint_node(_bmc), 2, _target)
                cp._save()
                _any_overridden = True
                _slog(
                    f"Per-node checkpoint override: {_grp_bmcs} -> {_target}, mode={cp.mode}",
                    prefix="INFO",
                )
                print(f"     ✅ Override applied: {_n} node(s) will resume from {_target}.")
                break
            print()
        if _any_overridden:
            _new_stage = _checkpoint_resume_stage_label(cp)
            print(f"     Updated overall next stage: {_new_stage}")
        return _any_overridden

    # ── Single-group path: all nodes at same stage (or single-node mode) ──
    print("     Resume controls : Press Enter to use detected stage, or pick a checkpoint below.")
    print(f"     Detected next   : {_display_default}")

    _first_pending = ""
    for _cp_id, __ in _checkpoint_seq:
        if not _checkpoint_phase_effectively_done(cp, _mode_key, _cp_id):
            _first_pending = _cp_id
            break
    _previous_cp_id = ""
    if _first_pending:
        for _i, (_cp_id, __) in enumerate(_checkpoint_seq):
            if _cp_id == _first_pending:
                if _i > 0:
                    _previous_cp_id = _checkpoint_seq[_i - 1][0]
                break
    elif _checkpoint_seq:
        _previous_cp_id = _checkpoint_seq[-1][0]

    for _idx, (_cp_id, _cp_desc) in enumerate(_checkpoint_seq, 1):
        _done = _checkpoint_phase_effectively_done(cp, _mode_key, _cp_id)
        _status = "done" if _done else "pending"
        _markers = []
        if _cp_id == _previous_cp_id:
            _markers.append("previous checkpoint")
        if _cp_id == _first_pending:
            _markers.append("detected next")
        _marker = f"  <- {', '.join(_markers)}" if _markers else ""
        print(f"       {_idx:>2}. {_cp_id:<16} {_cp_desc} [{_status}]{_marker}")

    _id_lookup = {_cp_id.lower(): _cp_id for _cp_id, __ in _checkpoint_seq}
    while True:
        _sel = _prompt(
            "     Override start checkpoint [Enter=detected, number, or cp_id]: ",
            "",
        ).strip().lower()
        if not _sel:
            return False
        _target = ""
        if _sel.isdigit():
            _pick = int(_sel)
            if 1 <= _pick <= len(_checkpoint_seq):
                _target = _checkpoint_seq[_pick - 1][0]
        else:
            _target = _id_lookup.get(_sel, "")
        if not _target:
            print("     ⚠️  Invalid selection. Use Enter, a list number, or a cp_id.")
            continue
        if _target == _detected_next:
            print("     ℹ️  Selected checkpoint is already the detected next stage.")
            return False
        _target_desc = next((d for c, d in _checkpoint_seq if c == _target), "")
        _confirm = _prompt(
            f"     Confirm resume override to {_target}"
            f"{f' ({_target_desc})' if _target_desc else ''}? [y/N]: ",
            "n",
        ).strip().lower()
        if _confirm not in ("y", "yes"):
            print("     Override not applied. Choose another checkpoint or press Enter to keep detected stage.")
            continue
        if _checkpoint_apply_manual_resume_target(cp, _target):
            _new_stage = _checkpoint_resume_stage_label(cp)
            print(f"     Manual checkpoint override applied: next stage is {_new_stage} ({_target}).")
            _slog(f"Manual checkpoint override applied: target={_target}, mode={cp.mode}")
            return True
        print("     ⚠️  Could not apply manual checkpoint override.")
        return False


def _set_resume_log_suffix_from_checkpoint(cp) -> None:
    """Set per-run log-dir suffix so resumed runs include the checkpoint phase."""
    global _resume_checkpoint_log_suffix
    _phase_id = _checkpoint_resume_phase_id(cp)
    _resume_checkpoint_log_suffix = f"_{_phase_id}" if _phase_id else "_cp_complete"


def _consume_resume_log_suffix() -> str:
    """Return and clear the pending resume log suffix for the next session logger."""
    global _resume_checkpoint_log_suffix
    _out = str(_resume_checkpoint_log_suffix or "")
    _resume_checkpoint_log_suffix = ""
    return _out


def _latest_primary_checkpoint_done(cp):
    """Return the latest completed primary checkpoint id/description."""
    if not cp:
        return "", ""
    _mode_key = _checkpoint_mode_to_test_key("1")
    _seq = list(_CHECKPOINT_TEST_OPTIONS.get(_mode_key) or [])
    for _cp_id, _cp_desc in reversed(_seq):
        if not str(_cp_id).startswith("cp_1_"):
            continue
        try:
            if _checkpoint_phase_effectively_done(cp, _mode_key, _cp_id):
                return _cp_id, _cp_desc
        except Exception:
            continue
    return "", ""


def _checkpoint_per_node_stage_lines(cp) -> "list[str]":
    """Return per-node checkpoint stage lines for resume summary prompts."""
    if not cp:
        return []
    _mode_raw = str(getattr(cp, "mode", "") or "").strip().lower()
    _is_mode3 = _mode_raw == "3"
    _bmc_ips = [str(_ip).strip() for _ip in (getattr(cp, "bmc_ips", []) or []) if str(_ip).strip()]

    _derived_peer_ips = []
    if _is_mode3:
        _node_phases = {}
        with suppress(Exception):
            _node_phases = dict((getattr(cp, "_data", {}) or {}).get("node_phases") or {})
        _peer_ips = set()
        for _per_node in _node_phases.values():
            if not isinstance(_per_node, dict):
                continue
            for _node_id in _per_node.keys():
                _raw = str(_node_id or "").strip()
                if not _raw:
                    continue
                if _raw.startswith("node_peer:"):
                    _raw = str(_raw.split(":", 1)[1] or "").strip()
                if _is_valid_ipv4(_raw):
                    _peer_ips.add(_raw)
        _derived_peer_ips = sorted(_peer_ips)
        if not _bmc_ips and _derived_peer_ips:
            _bmc_ips = ["(primary ip unavailable)"] + _derived_peer_ips
        elif _bmc_ips:
            for _peer_ip in _derived_peer_ips:
                if _peer_ip not in _bmc_ips:
                    _bmc_ips.append(_peer_ip)

    if not _bmc_ips:
        return []

    _lines = []

    if _is_mode3:
        _primary_ip = _bmc_ips[0]
        _cp_id, _cp_desc = _latest_primary_checkpoint_done(cp)
        if _cp_id:
            _stage = f"{_cp_id} — {_cp_desc}" if _cp_desc else _cp_id
        else:
            _stage = "(no primary checkpoint recorded)"
        _lines.append(f"primary/{_primary_ip}: {_stage}")

    _peer_ips = _bmc_ips[1:] if _is_mode3 else _bmc_ips
    _peer_phase_ids = ["cp_2_8", "cp_2_7", "cp_2_6", "cp_2_5", "cp_2_4", "cp_2_3", "cp_2_2", "cp_2_1"]
    for _idx, _peer_ip in enumerate(_peer_ips, 1):
        _peer_stage_id = ""
        for _phase_id in _peer_phase_ids:
            if _checkpoint_phase_resume_evidence_for_peer(cp, _phase_id, _peer_ip):
                _peer_stage_id = _phase_id
                break
        if _peer_stage_id:
            _peer_desc = _checkpoint_phase_description(_peer_stage_id)
            _peer_stage = f"{_peer_stage_id} — {_peer_desc}" if _peer_desc else _peer_stage_id
        else:
            _peer_stage = "(no peer checkpoint recorded)"
        _peer_label = f"secondary-{_idx:02d}/{_peer_ip}" if _is_mode3 else _peer_ip
        _lines.append(f"{_peer_label}: {_peer_stage}")
    return _lines


def _checkpoint_display_number(cp_id: str) -> str:
    """Extract display number from checkpoint id (e.g. cp_1_4 -> 4)."""
    _parts = str(cp_id or "").split("_")
    return _parts[-1] if _parts else ""


def _list_completed_checkpoints(cp) -> str:
    """List all completed checkpoints for this mode."""
    if not cp:
        return ""
    _mode = str(getattr(cp, "mode", "") or "").strip().lower()
    
    # Define checkpoint descriptions by mode
    _checkpoint_desc = {
        "1": {
            "cp_1_1": "LOADER options set",
            "cp_1_2": "Option 9 confirmed",
            "cp_1_3": "Option-9 abort answered",
            "cp_1_4": "Option 4 started",
            "cp_1_5": "Option 4 completed",
            "cp_1_6": "AutoSupport confirmation answered",
            "cp_1_7": "Cluster setup started",
            **{_cp_id: _cp_desc for _cp_id, _cp_desc in _CP_1_7_SUBCHECKPOINTS},
            "cp_1_8": "Cluster creation complete",
        },
        "2": {
            "cp_2_1": "LOADER reached",
            "cp_2_2": "Boot menu issued",
            "cp_2_3": "Option 4 issued",
            "cp_2_4": "Option 4 completed",
            "cp_2_5": "Node management configured",
            "cp_2_6": "Cluster setup menu",
            "cp_2_7": "Node joined",
            "cp_2_8": "Node addition job completed",
        },
        "4.2": {
            "cp_4b_1": "Nodes at LOADER",
            "cp_4b_2": "Netboot started",
            "cp_4b_3": "Option 7 selected",
            "cp_4b_4": "Image downloaded",
            "cp_4b_5": "Image installed",
            "cp_4b_6": "Mode 1/2 checkpoints continue",
        },
    }
    
    desc_map = _checkpoint_desc.get(_mode, {})
    if not desc_map:
        return ""
    
    completed = []
    _mode_key = _checkpoint_mode_to_test_key(_mode)
    for cp_id, desc in desc_map.items():
        if _checkpoint_phase_effectively_done(cp, _mode_key, cp_id):
            completed.append(f"✅ {desc}")
    
    if not completed:
        return ""
    
    return "\n     Checkpoints created: " + ", ".join(completed)



def select_operation_mode():
    """Return (operation_mode_int, auto_setup_bool, auto_add_bool).

    Modes:
      1  -> Create single node cluster (automated)
      2  -> Add new nodes to an existing cluster
        2.1: format new node, interactive   (auto_add=False)
        2.2: format new node, automatic     (auto_add=True)
      3  -> End-to-end auto initialize: primary + parallel auto-add peers
            for every other BMC discovered/entered.
      4  -> Install/manage ONTAP  (sub-menu)
        4.1: Upgrade ONTAP (rolling takeover/giveback)
        4.2: Netboot + automated cluster reinit (strict sequencing)
        4.3: Netboot and install image only (no cluster create/node add)
      6  -> Script help and instructions
      7  -> Exit.
    """
    global _setup_passwordless_ssh, _netboot_before_reinit, _netboot_pkg_preselected, _physical_zeroing
    global _loader_env_stage_enabled
    global _diag_bootargs, _netboot_static_ip
    global _resume_from_start_menu
    global _checkpoint_mode, _resume_cp_start
    _startup_checkpoint_prompt_done = False
    _menu_checkpoint_available = False
    _checkpoint_mode = None
    _resume_cp_start = None

    def _dispatch_checkpoint_resume(_cp_obj):
        global _resume_from_start_menu, _checkpoint_mode, _resume_cp_start
        _set_resume_log_suffix_from_checkpoint(_cp_obj)
        _cp_mode = str(_cp_obj.mode or "").strip()
        _checkpoint_mode = _cp_mode
        _resume_cp_start = _checkpoint_resume_phase_id(_cp_obj) or "start"
        if _cp_mode.lower().startswith("4.2"):
            _resume_from_start_menu = True
            print("\n  ✅ Resuming checkpoint via menu option 4.2.")
            return 42, False, False
        if _cp_mode == "2":
            print("\n  ✅ Resuming checkpoint via menu option 2.2.")
            return 2, False, True
        if _cp_mode == "3":
            # Only route to 2.3 (add-node continuation) when the cluster
            # actually exists. primary_bootmenu_done and primary_node_mgmt_done
            # are pre-cluster stages — the cluster management LIF is not
            # available yet at those points.  peer_option4_done alone is also
            # insufficient: in mode 3 peers run option 4 in parallel with the
            # primary cluster-setup wizard, so the cluster may not be formed
            # when peers finish option 4.
            _primary_cluster_ready = bool(
                _cp_obj.is_done("cp_1_8")
                or _cp_obj.is_done("cluster_formed")
                or _cp_obj.is_done("primary_setup_done")
            )
            _primary_mgmt_ready = bool(
                _checkpoint_phase_effectively_done(
                    _cp_obj, _checkpoint_mode_to_test_key("3"), "cp_1_7_9"
                )
            )
            if _primary_cluster_ready and _primary_mgmt_ready:
                print(
                    "\n  ✅ Resuming checkpoint via menu option 2.3 "
                    "(safe add-node continuation)."
                )
                return 26, False, False
            if _mode3_peer_opt4:
                print(
                    "\n  ℹ️  Mode 3 peers are staged, but primary milestones for cluster add-node "
                    "(cp_1_7_9 + cp_1_8) are not complete yet; resuming option 3."
                )
            # Primary is not yet done with cluster setup — resume mode 3 from
            # the first incomplete primary checkpoint.  Per-node phases
            # (peer_option4_done etc.) are already tracked and will be skipped
            # when the parallel peer flow re-evaluates each node.
            print("\n  ✅ Resuming checkpoint via menu option 3.")
            return 3, True, True
        if _cp_mode == "1":
            print("\n  ✅ Resuming checkpoint via menu option 1.")
            return 1, True, False
        print("  ⚠️  Checkpoint mode is not auto-routable from the start menu.")
        return None

    while True:
        _print_banner("NetApp AFX BMC Console Automation 🤖")
        print("\n  What do you want to do?\n")
        print("  1.  Create single node cluster")
        print("     Initializes the first node in an ONTAP AFX cluster and creates a new cluster.")
        print("")
        print("  2.  Add new nodes")
        print("    2.1. Reinitialize cluster nodes and leave in un-added state for manual node additions.")
        print("    2.2. Format new nodes. Use automatic add.")
        print("    2.3. Resume interrupted node additions.")
        print("")
        print("  3.  End to end auto initialize")
        print("")
        print("  4.  Install ONTAP")
        print("    4.1. Upgrade ONTAP (rolling takeover/giveback)")
        print("    4.2. Netboot + automated cluster reinit")
        print("    4.3. Netboot and install image only (no cluster create/node add)")
        print("")
        print("  5.  Administration and maintenance")
        print("    5.1. Install license file only")
        print("    5.2. Set up passwordless SSH to cluster management")
        print("    5.3. Create backup cluster configuration")
        print("    5.4. Verify BMC authentication")
        print("    5.5. Check node status (LOADER / cluster prompt)")
        print("    5.6. Cluster health and version check")
        print("    5.7. SSH diagnostics, cleanup, and known_hosts reset")
        print("    5.8. Backup LOADER environment variables (experimental)")
        print("    5.9. Compare LOADER env to defaults (diff) (experimental)")
        print("    5.10. Check boot DNA (cluster shell or LOADER)")
        print("    5.11. Build cluster_IP manifest for node add")
        print("    5.12. Compare and correct cluster node names:IP addresses")
        print("    5.13. Show reinit-config.json (human-readable)")
        print("    5.14. Check cluster node join status")
        print("    5.15. Manage session credentials")
        print("")
        print("    !!Disruptive commands!!")
        print("      5.99. Reset all nodes to LOADER prompt")
        print("")
        print("  6.  Script help and instructions")
        print("  7.  Exit")
        print("")
        print("  " + "─" * 58)
        print("  (type 'menu' at any prompt to return here)")
        print("")
        print("  💡 Screen tips (--screen): Ctrl+A Esc=scroll, arrows/PgUp/PgDn navigate, q exits scroll mode, Ctrl+A d detaches, and 'screen -r afx-reinit' reattaches.")
        print("")
        if not _startup_checkpoint_prompt_done:
            _startup_checkpoint_prompt_done = True
            _all_checkpoints = CheckpointManager.list_all()
            if _all_checkpoints:
                _menu_checkpoint_available = True
                if len(_all_checkpoints) == 1:
                    # Single checkpoint — same UX as before
                    _cp_start = _all_checkpoints[0]
                    _cp_mode = str(_cp_start.mode or "").strip()
                    _cp_age = ""
                    try:
                        _cp_dt = datetime.fromisoformat(_cp_start.created)
                        _cp_mins = int((datetime.now() - _cp_dt).total_seconds() // 60)
                        _cp_age = f" from {_cp_mins} minute(s) ago"
                    except Exception:
                        pass
                    _menu_opt = _checkpoint_menu_option_label(_cp_mode)
                    _stage = _checkpoint_resume_stage_label(_cp_start)
                    _completed = _list_completed_checkpoints(_cp_start)
                    print("=" * 60)
                    print(f"  🔖 Existing checkpoint found{_cp_age}")
                    print(f"     Last menu option : {_menu_opt}")
                    print(f"     Checkpoint mode  : {_format_checkpoint_mode(_cp_mode)}")
                    if _completed:
                        print(_completed)
                    print(f"     Resume stage     : {_stage}")
                    _node_stages = _checkpoint_per_node_stage_lines(_cp_start)
                    if _node_stages:
                        print("     Per-node stage  :")
                        for _node_stage in _node_stages:
                            print(f"       - {_node_stage}")
                    print("=" * 60)
                    _is_fully_completed = (
                        str(_checkpoint_resume_phase_id(_cp_start) or "").strip() == ""
                        and not str(_cp_mode or "").strip().lower().startswith("4.2")
                    )
                    if _is_fully_completed:
                        print("  ℹ️  All checkpoints are complete; there is nothing to resume.")
                        _clear_q = _prompt_with_timeout(
                            "  Clear this completed checkpoint? [Y/n]: ",
                            default="y",
                            timeout=_DEFAULT_INTERACTIVE_TIMEOUT,
                        ).strip().lower()
                        if _clear_q in ("", "y", "yes"):
                            _cp_start.clear()
                            _menu_checkpoint_available = False
                            print("  ✅ Completed checkpoint cleared.\n")
                        else:
                            print("  ℹ️  Completed checkpoint retained.\n")
                    else:
                        while True:
                            _resume_now = _prompt_with_timeout(
                                "  Resume from this checkpoint now? [y/n]: ",
                                default="n",
                                timeout=_DEFAULT_INTERACTIVE_TIMEOUT,
                            ).strip().lower()
                            if _resume_now in ("yes", "y"):
                                _resume_now = "y"
                                break
                            if _resume_now in ("no", "n"):
                                _resume_now = "n"
                                break
                            print("  Please enter y, n, yes, or no.")
                        print("")
                        if _resume_now == "y":
                            _prompt_checkpoint_resume_target_override(_cp_start)
                            _resume_choice = _dispatch_checkpoint_resume(_cp_start)
                            if _resume_choice is not None:
                                return _resume_choice
                        else:
                            # User declined resume — offer to clear the stale checkpoint
                            _clear_q = _prompt_with_timeout(
                                "  Clear this checkpoint? [y/N]: ",
                                default="n",
                                timeout=_DEFAULT_INTERACTIVE_TIMEOUT,
                            ).strip().lower()
                            if _clear_q in ("y", "yes"):
                                _cp_start.clear()
                                _menu_checkpoint_available = False
                                print("  ✅ Checkpoint cleared.\n")
                            else:
                                print("  ℹ️  Checkpoint retained.\n")
                else:
                    # Multiple checkpoints — show numbered list
                    print("=" * 60)
                    print(f"  🔖 {len(_all_checkpoints)} checkpoints available to resume")
                    print("=" * 60)
                    for _idx, _cp in enumerate(_all_checkpoints, 1):
                        _cp_mode_i = str(_cp.mode or "").strip()
                        _cp_age_i = ""
                        try:
                            _cp_dt_i = datetime.fromisoformat(_cp.created)
                            _cp_mins_i = int((datetime.now() - _cp_dt_i).total_seconds() // 60)
                            _cp_age_i = f"{_cp_mins_i} min ago"
                        except Exception:
                            pass
                        _menu_opt_i = _checkpoint_menu_option_label(_cp_mode_i)
                        _stage_i = _checkpoint_resume_stage_label(_cp)
                        _bmc_i = ", ".join(_cp.bmc_ips[:3])
                        if len(_cp.bmc_ips) > 3:
                            _bmc_i += f" (+{len(_cp.bmc_ips) - 3} more)"
                        print(f"  {_idx}. [{_cp_age_i}] option {_menu_opt_i} | {_format_checkpoint_mode(_cp_mode_i)}")
                        print(f"       Stage   : {_stage_i}")
                        if _bmc_i:
                            print(f"       Nodes   : {_bmc_i}")
                    print("  0. Skip (do not resume)")
                    print("=" * 60)
                    _cp_start = None
                    while True:
                        _cp_sel = _prompt_with_timeout(
                            f"  Select checkpoint to resume [1-{len(_all_checkpoints)}] (Enter=1, 0=skip): ",
                            default="1",
                            timeout=_DEFAULT_INTERACTIVE_TIMEOUT,
                        ).strip()
                        if _cp_sel in ("", "1") or _cp_sel == "0":
                            if _cp_sel == "0":
                                _cp_start = None
                            else:
                                _cp_start = _all_checkpoints[0]
                            break
                        try:
                            _cp_sel_i = int(_cp_sel)
                            if 1 <= _cp_sel_i <= len(_all_checkpoints):
                                _cp_start = _all_checkpoints[_cp_sel_i - 1]
                                break
                        except ValueError:
                            pass
                        print(f"  Please enter a number between 0 and {len(_all_checkpoints)}.")
                    print("")
                    if _cp_start is not None:
                        _cp_mode = str(_cp_start.mode or "").strip()
                        _is_fully_completed = (
                            str(_checkpoint_resume_phase_id(_cp_start) or "").strip() == ""
                            and not str(_cp_mode or "").strip().lower().startswith("4.2")
                        )
                        if _is_fully_completed:
                            print("  ℹ️  Selected checkpoint is fully complete; nothing to resume.")
                            _clear_q = _prompt_with_timeout(
                                "  Clear this completed checkpoint? [Y/n]: ",
                                default="y",
                                timeout=_DEFAULT_INTERACTIVE_TIMEOUT,
                            ).strip().lower()
                            if _clear_q in ("", "y", "yes"):
                                _cp_start.clear()
                                print("  ✅ Checkpoint cleared.\n")
                            else:
                                print("  ℹ️  Checkpoint retained.\n")
                            _cp_start = None
                        if _cp_start is not None:
                            _prompt_checkpoint_resume_target_override(_cp_start)
                            _resume_choice = _dispatch_checkpoint_resume(_cp_start)
                            if _resume_choice is not None:
                                return _resume_choice
                    else:
                        print("  ℹ️  Checkpoint resume skipped.\n")
                    if _cp_start is None:
                        _menu_checkpoint_available = False
        if _menu_checkpoint_available:
            choice = input(
                '❯❯  Enter your choice from the menu above (ie, 1, 2.1, 3, etc.) or type "checkpoint" to resume the last checkpoint: '
            ).strip().lower()
        else:
            choice = input(
                '❯❯  Enter your choice from the menu above (ie, 1, 2.1, 3, etc.) or type "checkpoint" for manual checkpoint override: '
            ).strip().lower()

        if choice == "checkpoint":
            _cp_manual = CheckpointManager()
            if not _cp_manual.load():
                _cp_manual = _create_checkpoint_for_manual_override()
                if _cp_manual is None:
                    print("\n  ↩️  Returning to menu...\n")
                    _menu_checkpoint_available = False
                    continue
                _menu_checkpoint_available = True
            _prompt_checkpoint_resume_target_override(_cp_manual)
            _resume_choice = _dispatch_checkpoint_resume(_cp_manual)
            if _resume_choice is not None:
                return _resume_choice
            continue

        if choice == "1":
            _print_banner("⚠️  WARNING ⚠️")
            print("")
            print("  This operation will FULLY AUTOMATE first-node initialization,")
            print("  format, and cluster setup. The script will auto-answer:")
            print("    • storage-availability-zone destroy warning  → no")
            print("    • second boot menu (after option 9)          → 4")
            print("    • zero disks / erase / type-yes prompts      → yes")
            print("  Node management port/IP/netmask/gateway are taken from")
            print("  retained config when available, prompted otherwise.")
            print("")
            print("  " + "*" * 58)
            print("  * CAUTION: IF THIS IS NOT THE FIRST NODE IN THE        *")
            print("  * CLUSTER DO NOT RUN THIS OPTION. RUN OPTION 2         *")
            print("  * INSTEAD TO JOIN A NEW NODE TO THE CLUSTER.            *")
            print("  " + "*" * 58)
            print("")
            print("  " + "─" * 58)
            if _menu_confirm():
                print("")
                print("  ℹ️  ONTAP requires the cluster admin password to be at least 8")
                print("  characters AND contain both letters and numbers.")
                while True:
                    _reuse_bmc_pwd = input("  Reuse the BMC login password as the cluster admin password? [Y/n]: ").strip().lower()
                    if _reuse_bmc_pwd in ("y", "n", ""):
                        break
                    print("  Please enter y or n.")
                print("")
                print("  " + "─" * 58)
                while True:
                    _proceed_init = input("  This will bring all cluster nodes to the LOADER prompt and begin\n  initialization of the first node in a new cluster. Continue? (y/N): ").strip().lower()
                    if _proceed_init in ("y", "n", ""):
                        break
                    print("  Please enter y or N.")
                if _proceed_init in ("n", ""):
                    print("\n  ↩️  Returning to menu...\n")
                    continue
                while True:
                    _ssh_ans = input("  Set up passwordless SSH to cluster management after setup? [y/N]: ").strip().lower()
                    if _ssh_ans in ("y", "n", ""):
                        break
                    print("  Please enter y or N.")
                _setup_passwordless_ssh = (_ssh_ans == "y")
                if _checkpoint:
                    _checkpoint.set_selection("setup_passwordless_ssh", _setup_passwordless_ssh)
                    _checkpoint.set_param("setup_passwordless_ssh", _setup_passwordless_ssh)
                
                # Check checkpoint for saved netboot_before_reinit preference
                _saved_nb = _checkpoint.get_selection("netboot_before_reinit") if _checkpoint else None
                if _saved_nb is not None:
                    _netboot_before_reinit = _saved_nb
                    _nb_label = "yes" if _netboot_before_reinit else "no"
                    print(f"  ℹ️   Resuming with saved preference: netboot before reinit = {_nb_label}")
                else:
                    while True:
                        _nb_ans = input("  Do you want to install a specific version of ONTAP before re-creating the cluster? [y/N]: ").strip().lower()
                        if _nb_ans in ("y", "n", ""):
                            break
                        print("  Please enter y or N.")
                    _netboot_before_reinit = (_nb_ans == "y")
                    if _checkpoint:
                        _checkpoint.set_selection("netboot_before_reinit", _netboot_before_reinit)

                if _netboot_before_reinit:
                    print("  ℹ️   Netboot-install will run at LOADER before the cluster reinit.")
                    while True:
                        while True:
                            _sip_ans = input("  Use static IP in LOADER instead of DHCP (ifconfig -auto)? [y/N]: ").strip().lower()
                            if _sip_ans in ("y", "n", ""):
                                break
                            print("  Please enter y or N.")
                        if _sip_ans in ("y", "n", ""):
                            break
                        print("  Please enter y or N.")
                    _netboot_static_ip = (_sip_ans == "y")
                print("\n  ✅ Confirmed. Option 1: Create single node cluster (automated)")
                print("     → LOADER: set-defaults + destroy storage pods + saveenv")
                print("     → Boot menu: option 9, then auto option 4 + auto setup\n")
                return 1, True, False
            print("\n  ↩️  Returning to menu...\n")
            continue

        if choice == "2.1":
            _print_banner("⚠️  NOTICE ⚠️")
            print("")
            print("  " + "*" * 58)
            print("  * CAUTION: 2.1 FORMATS AND JOINS AN AFX NODE TO AN     *")
            print("  * EXISTING CLUSTER. IF THE CLUSTER DOES NOT EXIST     *")
            print("  * ALREADY, CHOOSE NO AND SELECT OPTION 1.               *")
            print("  " + "*" * 58)
            print("")
            print("  " + "─" * 58)
            if _menu_confirm():
                while True:
                    _nb_ans = input("  Do you want to install a specific version of ONTAP before adding this node? [y/N]: ").strip().lower()
                    if _nb_ans in ("y", "n", ""):
                        break
                    print("  Please enter y or N.")
                _netboot_before_reinit = (_nb_ans == "y")
                if _netboot_before_reinit:
                    print("  ℹ️   Netboot-install will run at LOADER before the node join.")
                    while True:
                        while True:
                            _sip_ans = input("  Use static IP in LOADER instead of DHCP (ifconfig -auto)? [y/N]: ").strip().lower()
                            if _sip_ans in ("y", "n", ""):
                                break
                            print("  Please enter y or N.")
                        if _sip_ans in ("y", "n", ""):
                            break
                        print("  Please enter y or N.")
                    _netboot_static_ip = (_sip_ans == "y")
                print("\n  ✅ Confirmed. 2.1: Add node (interactive)")
                print("     → LOADER: set-defaults + saveenv (no destroy storage pods)")
                print("     → Boot menu: option 4 (Initialize and configure system)\n")
                return 2, False, False
            print("\n  ↩️  Returning to menu...\n")
            continue

        if choice == "2.2":
            _print_banner("⚠️  NOTICE ⚠️")
            print("")
            print("  2.2 will FULLY AUTOMATE adding a node to an existing")
