def get_loader_commands():
    _fw_cmds = ["setenv AUTO_FW_UPDATE false"] if _prevent_bios_fw_update else []
    _autoboot_cmds = ["setenv AUTOBOOT true"] if _force_autoboot_true else []
    # Mode 3 primary uses mode-1 LOADER commands (full cluster init); peers in
    # mode 3 are driven by their own threads with their own LOADER commands.
    if _operation_mode in (1, 3):
        cmds = [
            "set-defaults",
            "setenv bootarg.destroy.all.storage.pods true",
        ] + _fw_cmds + _autoboot_cmds
        if _physical_zeroing:
            cmds.append("setenv raid.use-physical-zeroing? true")
        else:
            cmds.append("setenv raid.use-physical-zeroing? false")
        cmds.append("setenv bootarg.init.unjoined true")
        if _diag_mode and _diag_bootargs:
            for ba in _diag_bootargs:
                cmds.append(f"setenv {ba}")
        cmds += ["saveenv", "boot_ontap menu"]
        return cmds
    else:
        cmds = [
            "set-defaults",
        ] + _fw_cmds + _autoboot_cmds
        # Physical zeroing is a per-node LOADER setting; apply it to
        # peers too when the operator opted in so the whole cluster ends
        # up with consistent raid.use-physical-zeroing? behaviour.
        if _physical_zeroing:
            cmds.append("setenv raid.use-physical-zeroing? true")
        else:
            cmds.append("setenv raid.use-physical-zeroing? false")
        cmds.append("setenv bootarg.init.unjoined true")
        if _diag_mode and _diag_bootargs:
            for ba in _diag_bootargs:
                cmds.append(f"setenv {ba}")
        cmds += ["saveenv", "boot_ontap menu"]
        return cmds


def get_boot_menu_option():
    if _operation_mode in (1, 3):
        return "9", "Initialize"
    else:
        return "4", "Initialize and configure system"


# ---------------------------------------------------------------------------
# OS / Package-manager detection
# ---------------------------------------------------------------------------

def detect_package_manager():
    if sys.platform != "linux":
        return None
    try:
        with open("/etc/os-release") as f:
            os_release = f.read().lower()
    except FileNotFoundError:
        os_release = ""
    if "ubuntu" in os_release or "debian" in os_release:
        return "apt"
    elif "rhel" in os_release or "centos" in os_release or "fedora" in os_release or "red hat" in os_release:
        if os.path.exists("/usr/bin/dnf"):
            return "dnf"
        elif os.path.exists("/usr/bin/yum"):
            return "yum"
    return None


def install_system_package(package_name, pkg_manager):
    """Attempt to install *package_name* via the system package manager.

    Returns True on success, False on failure (caller can fall back to pip).
    """
    answer = input(
        f"⚠️  System package '{package_name}' is required but not installed.\n"
        f"   Install it now using '{pkg_manager}'? [Y/N]: "
    ).strip().lower()
    if answer != "y":
        print("⚠️  Skipping system install; will attempt pip fallback.")
        return False
    try:
        cmd = ["sudo", pkg_manager, "install", "-y", package_name]
        print(f"Running: {' '.join(cmd)}")
        subprocess.check_call(cmd)
        print(f"✅ '{package_name}' installed successfully.")
        return True
    except subprocess.CalledProcessError as e:
        print(f"⚠️  System install of '{package_name}' failed ({e}); "
              f"will attempt pip fallback.")
        return False


REQUIRED_MODULES = {
    "paramiko": {
        "pip": "paramiko",
        "apt": "python3-paramiko",
        "dnf": "python3-paramiko",
        "yum": "python3-paramiko",
    },
}


def install_required_modules():
    pkg_manager = detect_package_manager()
    for module_name, pkg_info in REQUIRED_MODULES.items():
        try:
            # OPT: importlib.import_module is the modern API for dynamic imports
            importlib.import_module(module_name)
            continue
        except ImportError:
            pass
        if pkg_manager and pkg_manager in pkg_info:
            print(f"Module '{module_name}' is missing.")
            sys_ok = install_system_package(pkg_info[pkg_manager], pkg_manager)
            if sys_ok:
                try:
                    importlib.import_module(module_name)
                    continue
                except ImportError:
                    print("⚠️  System package installed but module still not importable. "
                          "Falling back to pip.")
        answer = input(
            f"⚠️  Python module '{module_name}' is not installed.\n"
            f"   Install it now via pip? [Y/N]: "
        ).strip().lower()
        if answer != "y":
            print("❌ Cannot continue without the required module. Exiting.")
            sys.exit(1)
        try:
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install", "--upgrade",
                 "pip", "setuptools", "wheel"]
            )
        except subprocess.CalledProcessError:
            pass
        try:
            subprocess.check_call(
                [sys.executable, "-m", "pip", "install", pkg_info["pip"]]
            )
            print(f"✅ Module '{module_name}' installed successfully via pip.")
        except subprocess.CalledProcessError as e:
            print(f"❌ Failed to install module '{module_name}': {e}")
            sys.exit(1)


install_required_modules()

import paramiko  # noqa: E402

# Quiet paramiko's own logger. It emits noisy ERROR-level tracebacks for
# transient failures we already handle (banner timeouts, EOF during
# negotiation, etc.). The retry loop in `_ssh_connect_with_retry` surfaces
# the same condition through its own user-friendly print, so suppressing
# paramiko's internal logging keeps the console clean.
logging.getLogger("paramiko").setLevel(logging.CRITICAL)
logging.getLogger("paramiko.transport").setLevel(logging.CRITICAL)

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------

# When True (set by 1.1/1.2 "install specific ONTAP?" prompt), netboot-install
# is performed at LOADER before the normal boot-menu/reinit flow continues.
_netboot_before_reinit = False
_netboot_pkg_preselected = None  # tuple(src_type, src_value) captured at menu-time
_mode3_peer_netboot_done = False  # True when mode-3 peer netboot/install ran with primary

# When True (set by 1.1/1.2/3 prompt), adds 'setenv raid.use-physical-zeroing? true'
# to the primary node's LOADER commands so disks are physically zeroed.
_physical_zeroing = False

# When True (set by 1/3/4.2 prompt), responds 'yes' to the ONTAP AutoSupport
# confirmation prompt ("Type yes to confirm and continue"). When False, responds 'no'.
_enable_autosupport = True

# Set to True during Boot Menu Selection when ONTAP reports that option 9/9a is
# not supported on the platform.  The second-boot-menu wait checks this flag to
# fall back to option 4 instead of looping indefinitely.
_option9_platform_unsupported = False

# When True (set by --diag flag), enables diagnostic bootarg injection at LOADER.
_diag_mode = False

# List of validated "bootarg.name.variable <value>" strings to inject at LOADER
# when _diag_mode is True. Populated by _load_diag_bootargs().
_diag_bootargs: list = []

# When True, LOADER config includes "setenv AUTO_FW_UPDATE false" to prevent
# BIOS firmware auto-updates during boot flows.
_prevent_bios_fw_update = True

# Tri-state for bootarg.init.dna verification inside LOADER env pre/post flow:
#   None  -> not decided yet (interactive prompt where applicable)
#   True  -> run check
#   False -> skip check
_bootarg_check_enabled: "bool | None" = None

# Tri-state for the entire LOADER env backup/printenv stage:
#   None  -> not decided yet (interactive prompt where applicable)
#   True  -> run pre/post printenv capture + bootarg check + diff flow
#   False -> skip that stage entirely
_loader_env_stage_enabled: "bool | None" = None

# Tri-state operator choice for AUTOBOOT handling after set-defaults:
#   None  -> not asked yet
#   True  -> force "setenv AUTOBOOT true" in LOADER command stage
#   False -> leave AUTOBOOT unchanged
_force_autoboot_true: "bool | None" = None
_force_autoboot_lock = threading.Lock()

_shutdown_event = threading.Event()
_fatal_boot_dna_event = threading.Event()
_fatal_boot_dna_lock = threading.Lock()
_fatal_boot_dna_label = ""
_client_lock    = threading.Lock()
_active_client  = None
_ctrl_c_count   = 0
_bg_mode        = False  # True when --bg flag is passed

# Runtime pause control: when this sentinel file exists, automation loops pause
# and auto-reconnect behavior is suppressed until the file is removed.
_PAUSE_SENTINEL_FILE = ".afx_pause"
_CHECKPOINT_REQUEST_FILE = ".afx_checkpoint_now"
try:
    _PAUSE_AUTO_CLEAR_SECONDS = max(
        0, int(os.environ.get("AFX_PAUSE_AUTO_CLEAR_SECONDS", "7200"))
    )
except Exception:
    _PAUSE_AUTO_CLEAR_SECONDS = 7200
_pause_state_lock = threading.Lock()
_pause_announced = False

# ── Pause wait-time tracker ──────────────────────────────────────────────────
# Mirrors the prompt-wait tracker above.  Accumulated inside _wait_if_paused()
# so that deliberate operator-initiated pauses are visible in the run summary
# and subtracted from the unaccounted-time gap alongside prompt waits.
_pause_wait_seconds = 0.0
_pause_wait_count = 0
_pause_wait_lock = threading.Lock()
_pause_wait_max = 0.0
_pause_wait_max_label = ""
_runtime_cmd_lock = threading.Lock()
_manual_checkpoint_signal_event = threading.Event()

# Primary BMC host currently in use. Set by connect_to_sp so shared BMC
# read loops can attempt a full SSH reconnect + system-console re-entry when
# console output is silent for an extended period.
_primary_bmc_host = None

# Primary BMC credentials currently in use. Populated by `connect_to_sp` so
# subsequent helpers (cluster login, etc.) can fall back to BMC creds when
# no cluster admin credentials are available.
_primary_bmc_user = None
_primary_bmc_password = None

# Shared reconnect context for primary-BMC read loops.
_primary_bmc_reconnect_ctx = {}


def _pause_sentinel_path() -> str:
    return os.path.join(_script_dir(), _PAUSE_SENTINEL_FILE)


def _checkpoint_request_path() -> str:
    return os.path.join(_script_dir(), _CHECKPOINT_REQUEST_FILE)


def _pause_requested() -> bool:
    with suppress(Exception):
        return os.path.isfile(_pause_sentinel_path())
    return False


def _create_manual_checkpoint(source: str = "operator") -> bool:
    """Persist a manual checkpoint snapshot of current run state."""
    with _runtime_cmd_lock:
        if _checkpoint is None:
            _ts_print("⚠️  Manual checkpoint requested, but no active checkpoint context is available.")
            _slog(f"Manual checkpoint request ignored ({source}): no active checkpoint", prefix="WARN")
            return False
        try:
            # Flush in-memory checkpoint state first.
            _checkpoint.save()
            _cp_path = getattr(_checkpoint, "_path", "")
            _cp_dir = os.path.dirname(_cp_path) if _cp_path else os.path.join(
                _script_dir(), CheckpointManager.CHECKPOINT_DIR
            )
            os.makedirs(_cp_dir, exist_ok=True)
            _ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            _manual_path = os.path.join(_cp_dir, f"afx_checkpoint_manual_{_ts}.json")
            if _cp_path and os.path.isfile(_cp_path):
                shutil.copy2(_cp_path, _manual_path)
            else:
                with open(_manual_path, "w", encoding="utf-8") as _mh:
                    json.dump(getattr(_checkpoint, "_data", {}), _mh, indent=2)
                    _mh.write("\n")
            _ts_print(f"💾 Manual checkpoint saved ({source}): {_manual_path}")
            _slog(f"Manual checkpoint saved ({source}): {_manual_path}")
            return True
        except Exception as exc:
            _ts_print(f"⚠️  Manual checkpoint save failed ({source}): {exc}")
            _slog(f"Manual checkpoint save failed ({source}): {exc}", prefix="WARN")
            return False


def _process_runtime_requests(context: str = "runtime loop") -> None:
    """Handle runtime control requests (checkpoint file/signal)."""
    _cp_path = _checkpoint_request_path()
    _from_file = False
    with suppress(Exception):
        if os.path.isfile(_cp_path):
            os.remove(_cp_path)
            _from_file = True
    if _from_file:
        _create_manual_checkpoint(source=f"{context} file request")
    if _manual_checkpoint_signal_event.is_set():
        _manual_checkpoint_signal_event.clear()
        _create_manual_checkpoint(source=f"{context} signal request")


def _wait_if_paused(context: str = "automation") -> None:
    """Block while runtime pause is active.

    Operators can pause/resume a live run by creating/removing the sentinel
    file returned by _pause_sentinel_path().
    """
    global _pause_announced, _pause_wait_seconds, _pause_wait_count
    global _pause_wait_max, _pause_wait_max_label
    _process_runtime_requests(context)
    _path = _pause_sentinel_path()
    _pause_started = time.monotonic()
    _next_reminder = _pause_started + 300
    _pause_was_active = False
    _non_phase_token = None
    if _session_log:
        with suppress(Exception):
            _non_phase_token = _session_log.push_non_phase_reason(
                "runtime pause wait"
            )
    while not _shutdown_event.is_set() and _pause_requested():
        _pause_was_active = True
        _process_runtime_requests(context)
        with _pause_state_lock:
            if not _pause_announced:
                _pause_announced = True
                _ts_print(
                    f"⏸️  Pause requested ({context}). "
                    "Automation and auto-reconnect are paused."
                )
                _ts_print(f"   Remove pause file to resume: {_path}")
                _slog(f"Pause requested ({context}) via {_path}; automation paused",
                      prefix="WARN")
        _now = time.monotonic()
        if _now >= _next_reminder:
            _elapsed = int(_now - _pause_started)
            _ts_print(f"⏸️  Pause still active ({context}) for {_elapsed}s.")
            _ts_print(f"   Remove pause file to resume: {_path}")
            _next_reminder = _now + 300
        if (_PAUSE_AUTO_CLEAR_SECONDS > 0
                and (_now - _pause_started) >= _PAUSE_AUTO_CLEAR_SECONDS):
            _ts_print(
                f"⏱️  Pause timeout reached ({_PAUSE_AUTO_CLEAR_SECONDS}s); "
                "auto-clearing pause sentinel."
            )
            _slog(
                f"Pause auto-cleared after {_PAUSE_AUTO_CLEAR_SECONDS}s "
                f"({context})",
                prefix="WARN",
            )
            _set_pause_state(False, source=f"auto-timeout ({context})")
            break
        time.sleep(1.0)
    with _pause_state_lock:
        if _pause_announced:
            _pause_announced = False
            _ts_print("▶️  Pause cleared. Resuming automation.")
            _slog("Pause cleared; resuming automation")
    if _pause_was_active:
        _pause_elapsed = time.monotonic() - _pause_started
        with _pause_wait_lock:
            _pause_wait_seconds += _pause_elapsed
            _pause_wait_count += 1
            if _pause_elapsed > _pause_wait_max:
                _pause_wait_max = _pause_elapsed
                _pause_wait_max_label = context
    if _session_log:
        with suppress(Exception):
            _session_log.pop_non_phase_reason(_non_phase_token)


def _pause_allows_reconnect(context: str = "reconnect") -> bool:
    """Return False when runtime pause is active and reconnect should be deferred."""
    if _pause_requested():
        _wait_if_paused(context)
        return False
    return True


def _set_pause_state(paused: bool, source: str = "operator") -> bool:
    """Create/remove pause sentinel. Returns True on success."""
    _path = _pause_sentinel_path()
    try:
        if paused:
            with open(_path, "a", encoding="utf-8"):
                pass
            _ts_print(f"⏸️  Runtime pause enabled ({source}).")
            _ts_print(f"   Sentinel: {_path}")
            _slog(f"Runtime pause enabled ({source}) via sentinel {_path}", prefix="WARN")
        else:
            with suppress(FileNotFoundError):
                os.remove(_path)
            _ts_print(f"▶️  Runtime pause cleared ({source}).")
            _slog(f"Runtime pause cleared ({source})")
        return True
    except Exception as exc:
        _ts_print(f"⚠️  Failed to update runtime pause state ({source}): {exc}")
        _slog(f"Failed to update runtime pause state ({source}): {exc}", prefix="WARN")
        return False

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

def setup_logging(debug: bool):
    if debug:
        logging.basicConfig(level=logging.DEBUG,
                            format="%(asctime)s [%(levelname)s] %(name)s: %(message)s")
        logging.getLogger("paramiko").setLevel(logging.DEBUG)
        print("🐛 Debug logging is ENABLED.")
    else:
        logging.basicConfig(level=logging.WARNING)
        logging.getLogger("paramiko").setLevel(logging.WARNING)


# ---------------------------------------------------------------------------
# SSH helpers
# ---------------------------------------------------------------------------

_ssh_log_lock = threading.Lock()
_ssh_log_file_path = None
_ssh_remediation_log_file_path = None


def _resolve_ssh_log_file() -> str:
    """Return the current SSH connection log file path, creating parent dirs.

    Preferred location is inside the active run log directory:
      logs/<run-timestamp>/SSH_logs/
    If no session logger exists yet, fall back to:
      logs/SSH_logs/
    """
    global _ssh_log_file_path

    if _session_log and getattr(_session_log, "log_dir", None):
        _ssh_base = os.path.join(_session_log.log_dir, "SSH_logs")
    else:
        _ssh_base = os.path.join(_script_dir(), "logs", "SSH_logs")

    os.makedirs(_ssh_base, exist_ok=True)

    # If we do not have a file yet, or we've transitioned into a run-specific
    # session directory, rotate to a file in the current base folder.
    if (
        not _ssh_log_file_path
        or os.path.dirname(_ssh_log_file_path) != _ssh_base
    ):
        _ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        _ssh_log_file_path = _build_numbered_log_path(
            _ssh_base,
            f"ssh_connections_{_ts}.log",
            scope_dir=(getattr(_session_log, "log_dir", "") if _session_log else _ssh_base),
        )

    return _ssh_log_file_path


def _log_ssh_event(host: str, username: str, label: str, event: str,
                   attempt: int | None = None, details: str = "",
                   reconnect: bool = False, phase: str | None = None) -> None:
    """Append one SSH connection event to the dedicated SSH log file."""
    try:
        with _ssh_log_lock:
            _path = _resolve_ssh_log_file()
            _ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
            _attempt = str(attempt) if attempt is not None else "-"
            _phase = phase
            if not _phase and _session_log:
                _phase = getattr(_session_log, "_current_phase", None)
            _phase = (_phase or "-").replace(" ", "_")
            _line = (
                f"[{_ts}] label={label} host={host} user={username} "
                f"attempt={_attempt} event={event} "
                f"reconnect={'yes' if reconnect else 'no'} phase={_phase}"
            )
            if details:
                _line += f" details={details}"
            with open(_path, "a", encoding="utf-8") as _fh:
                _fh.write(_line + "\n")
    except Exception:
        pass


def _resolve_ssh_remediation_log_file() -> str:
    """Return the SSH remediation log file path (ssh_remediation_<ts>.log).

    Mirrors the placement logic of _resolve_ssh_log_file but produces a
    separate file dedicated to remediation actions (known_hosts cleanup,
    SOL deactivate, stale-session kills, etc.).
    """
    global _ssh_remediation_log_file_path

    if _session_log and getattr(_session_log, "log_dir", None):
        _ssh_base = os.path.join(_session_log.log_dir, "SSH_logs")
    else:
        _ssh_base = os.path.join(_script_dir(), "logs", "SSH_logs")

    os.makedirs(_ssh_base, exist_ok=True)

    if (
        not _ssh_remediation_log_file_path
        or os.path.dirname(_ssh_remediation_log_file_path) != _ssh_base
    ):
        _ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        _ssh_remediation_log_file_path = _build_numbered_log_path(
            _ssh_base,
            f"ssh_remediation_{_ts}.log",
            scope_dir=(getattr(_session_log, "log_dir", "") if _session_log else _ssh_base),
        )

    return _ssh_remediation_log_file_path


def _log_ssh_remediation_event(
    host: str, action: str, outcome: str, detail: str = ""
) -> None:
    """Append one SSH remediation event to the dedicated remediation log file.

    Args:
        host:    IP or hostname of the BMC that was remediated.
        action:  Short keyword describing what was done (e.g. 'known_hosts_remove',
                 'sol_deactivate', 'drop_clients', 'kill_pid', 'stale_diagnosis').
        outcome: 'ok', 'skipped', 'failed', or 'info'.
        detail:  Optional freeform detail appended to the log line.
    """
    try:
        with _ssh_log_lock:
            _path = _resolve_ssh_remediation_log_file()
            _ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
            _phase = None
            if _session_log:
                _phase = getattr(_session_log, "_current_phase", None)
            _phase = (_phase or "-").replace(" ", "_")
            _line = (
                f"[{_ts}] host={host} action={action} outcome={outcome} phase={_phase}"
            )
            if detail:
                _line += f" detail={detail}"
            with open(_path, "a", encoding="utf-8") as _fh:
                _fh.write(_line + "\n")
    except Exception:
        pass
def _silent_ping(host):
    """Return True if `host` responds to a single ICMP ping, False otherwise."""
    import subprocess as _sp
    import platform as _pl
    _cmd = (["ping", "-n", "1", "-w", "2000", host]
            if _pl.system().lower() == "windows"
            else ["ping", "-c", "1", "-W", "2", host])
    try:
        return _sp.run(_cmd, capture_output=True, timeout=5).returncode == 0
    except Exception:
        return False


def _diagnostic_ping_precheck(host, log=None):
    """Run a lightweight ping precheck before SSH stale-session diagnostics."""
    _ok = _silent_ping(host)
    if _ok:
        print(f"  ✅ Ping OK: {host} is reachable.")
        if log is not None:
            with suppress(Exception):
                log.log(f"[{host}] ping precheck: reachable")
    else:
        print(f"  ⚠️  Ping failed: {host} did not respond. Continuing SSH diagnostics anyway.")
        if log is not None:
            with suppress(Exception):
                log.log(f"[{host}] ping precheck: no response", prefix="WARN")
    return _ok


def _print_ping_precheck_summary(results_by_host):
    """Print a compact ping precheck summary for the diagnosed BMC targets."""
    if not results_by_host:
        return
    print("\n  Ping precheck summary:")
    for _host, _ok in results_by_host.items():
        _status = "reachable" if _ok else "no response"
        _icon = "✅" if _ok else "⚠️"
        print(f"    {_icon} {_host}: {_status}")


def _remove_bmc_from_known_hosts(host: str, log=None) -> bool:
    """Remove a BMC host key entry from known_hosts via `ssh-keygen -R`."""
    if not host:
        return False
    _ssh_keygen = shutil.which("ssh-keygen")
    if not _ssh_keygen:
        print("  ⚠️  ssh-keygen not found on PATH; cannot remove known_hosts entries.")
        if log is not None:
            with suppress(Exception):
                log.log(f"[{host}] known_hosts cleanup skipped: ssh-keygen not found", prefix="WARN")
        _log_ssh_remediation_event(host, "known_hosts_remove", "skipped",
                                   "ssh-keygen not found on PATH")
        return False
    try:
        _res = subprocess.run(
            [_ssh_keygen, "-R", host],
            capture_output=True,
            text=True,
            timeout=20,
            check=False,
        )
        _combined = ((_res.stdout or "") + "\n" + (_res.stderr or "")).strip().lower()
        if _res.returncode == 0:
            if "not found in" in _combined:
                print(f"  ℹ️  No known_hosts entry found for {host}.")
                if log is not None:
                    with suppress(Exception):
                        log.log(f"[{host}] known_hosts cleanup: no entry found")
                _log_ssh_remediation_event(host, "known_hosts_remove", "skipped",
                                           "no entry found")
            else:
                print(f"  🗑️  Removed known_hosts entry for {host}.")
                if log is not None:
                    with suppress(Exception):
                        log.log(f"[{host}] known_hosts cleanup: entry removed")
                _log_ssh_remediation_event(host, "known_hosts_remove", "ok",
                                           "entry removed")
            return True
        print(f"  ⚠️  ssh-keygen -R {host} returned rc={_res.returncode}.")
        if log is not None:
            with suppress(Exception):
                log.log(
                    f"[{host}] known_hosts cleanup failed rc={_res.returncode}",
                    prefix="WARN",
                )
        _log_ssh_remediation_event(host, "known_hosts_remove", "failed",
                                   f"rc={_res.returncode}")
        return False
    except Exception as _kh_ex:
        print(f"  ⚠️  Failed to run ssh-keygen -R for {host}: {_kh_ex}")
        if log is not None:
            with suppress(Exception):
                log.log(
                    f"[{host}] known_hosts cleanup exception: {_kh_ex}",
                    prefix="WARN",
                )
        _log_ssh_remediation_event(host, "known_hosts_remove", "failed",
                                   f"exception={_kh_ex}")
        return False


def _preclean_bmc_known_hosts(host: str, log=None, context: str = "") -> bool:
    """Best-effort one-time known_hosts cleanup before first BMC SSH login."""
    _host = str(host or "").strip()
    if not _host:
        return False
    with _known_hosts_preclean_lock:
        if _host in _known_hosts_precleaned_bmcs:
            return False
        _known_hosts_precleaned_bmcs.add(_host)
    if context:
        print(f"  🧹 Proactive known_hosts cleanup for {_host} ({context})...")
    else:
        print(f"  🧹 Proactive known_hosts cleanup for {_host}...")
    return _remove_bmc_from_known_hosts(_host, log=log)


def _cleanup_known_hosts_after_boot_option(host: str, option: str, log=None) -> bool:
    """Best-effort known_hosts cleanup after boot-menu option 9/4 selections."""
    _host = str(host or "").strip()
    if not _host:
        return False
    print(f"   🧹 Proactive known_hosts cleanup after option {option} on {_host}...")
    return _remove_bmc_from_known_hosts(_host, log=log)


def _check_bmc_reachable(host):
    import socket as _sock
    import subprocess as _sp

    ok = True

    # DNS check (only for non-IP hostnames).
    _is_ip = False
    try:
        _sock.inet_pton(_sock.AF_INET, host)
        _is_ip = True
    except OSError:
        try:
            _sock.inet_pton(_sock.AF_INET6, host)
            _is_ip = True
        except OSError:
            pass

    if not _is_ip:
        try:
            resolved = _sock.getaddrinfo(host, None)[0][4][0]
            print(f"  ✅ DNS resolved: {host} → {resolved}")
        except _sock.gaierror as _e:
            print(f"  ⚠️  DNS lookup failed for '{host}': {_e}")
            ok = False

    # Ping check (one packet, 2-second timeout).
    import platform as _pl
    _ping_cmd = (["ping", "-n", "1", "-w", "2000", host]
                 if _pl.system().lower() == "windows"
                 else ["ping", "-c", "1", "-W", "2", host])
    try:
        _result = _sp.run(_ping_cmd, capture_output=True, timeout=5)
        if _result.returncode == 0:
            print(f"  ✅ Ping OK: {host} is reachable.")
        else:
            print(f"  ⚠️  Ping failed: {host} did not respond.")
            ok = False
    except Exception as _pe:
        print(f"  ⚠️  Ping check skipped: {_pe}")
        # Don't mark as failed — ping may be blocked by firewall.

    return ok


def _prompt_bmc_host(prompt_text="  BMC hostname/IP: ", allow_blank=False):
    """Prompt for a BMC hostname/IP and re-prompt until it is reachable.

    Calls :func:`_check_bmc_reachable` after each entry; on failure the user
    is asked again. Blank input re-prompts unless ``allow_blank`` is True,
    in which case an empty string is returned so the caller can treat blank
    as a cancel sentinel.
    """
    while True:
        host = input(prompt_text).strip()
        if not host:
            if allow_blank:
                return ""
            print("  ⚠️  A BMC hostname or IP address is required.")
            continue
        if _check_bmc_reachable(host):
            return host
        print("  ⚠️  Please enter a valid, reachable BMC hostname or IP address.\n")


def configure_transport(client):
    transport = client.get_transport()
    if transport is None:
        return
    transport.set_keepalive(5)
    sock = transport.sock
    if sock is not None:
        try:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
            if hasattr(socket, "TCP_KEEPIDLE"):
                sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPIDLE, 5)
            if hasattr(socket, "TCP_KEEPINTVL"):
                sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPINTVL, 5)
            if hasattr(socket, "TCP_KEEPCNT"):
                sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPCNT, 12)
        except OSError:
            pass


# ── Stale BMC SSH session helpers ────────────────────────────────────────
# These are called by the banner-retry block in _ssh_connect_with_retry to
# free up BMC SSH session slots before the next retry attempt.

def _register_bmc_client(host: str, client) -> None:
    """Remember `client` as an open SSH client to `host` so the banner-retry
    helper can forcibly close it later if the BMC's session pool stalls."""
    if not host or client is None:
        return
    with _bmc_clients_lock:
        _bmc_clients_by_host.setdefault(host, []).append(client)


def _unregister_bmc_client(host: str, client) -> None:
    """Drop `client` from the registry (call from explicit close paths)."""
    if not host or client is None:
        return
    with _bmc_clients_lock:
        lst = _bmc_clients_by_host.get(host)
        if not lst:
            return
        with suppress(ValueError):
            lst.remove(client)
        if not lst:
            _bmc_clients_by_host.pop(host, None)


def _drop_bmc_clients_for(host: str, log=None) -> int:
    """Force-close every registered paramiko SSHClient for `host`.

    Returns the count of clients dropped. The transport is closed rudely
    (no SSH_MSG_DISCONNECT) so a hung remote sshd cannot block us. Safe to
    call concurrently with other threads using those clients — they will
    see EOF and surface their own errors, which the banner retry logic
    already handles.
    """
    with _bmc_clients_lock:
        clients = _bmc_clients_by_host.pop(host, [])
    if not clients:
        return 0
    for c in clients:
        with suppress(Exception):
            t = c.get_transport()
            if t is not None:
                t.close()
        with suppress(Exception):
            c.close()
    if log is not None:
        with suppress(Exception):
            log.log(
                f"[{host}] banner-retry: closed {len(clients)} registered "
                "in-process SSH client(s) to free BMC session slot",
                prefix="WARN",
            )
    _log_ssh_remediation_event(host, "drop_clients", "ok",
                               f"closed={len(clients)}")
    return len(clients)


def _find_stale_sockets_to(host: str, port: int = 22):
    """Return a list of (pid, proc_name, laddr) tuples for ESTABLISHED TCP
    sockets from this host to `host`:`port`. Requires psutil; returns []
    if psutil is unavailable or the lookup fails.
    """
    try:
        import psutil  # type: ignore
    except Exception:
        return []
    out = []
    with suppress(Exception):
        for c in psutil.net_connections(kind="tcp"):
            try:
                if (c.status == "ESTABLISHED"
                        and c.raddr
                        and c.raddr.ip == host
                        and c.raddr.port == port):
                    pname = ""
                    if c.pid:
                        with suppress(Exception):
                            pname = psutil.Process(c.pid).name()
                    out.append((c.pid, pname, c.laddr))
            except Exception:
                continue
    return out


def _kill_stale_local_pids_for(host: str, log=None) -> int:
    """Find ESTABLISHED TCP sockets from this host to <host>:22 owned by
    *other* python processes (likely prior AFX_reinit runs that died
    without cleaning up) and SIGTERM them.

    Skips our own PID (those are handled by _drop_bmc_clients_for) and
    non-python processes (sshd, scp, the operator's interactive ssh, etc.)
    to avoid harming unrelated work.

    Returns the count of PIDs signalled. No-op if psutil unavailable.
    """
    socks = _find_stale_sockets_to(host, 22)
    if not socks:
        return 0
    our_pid = os.getpid()
    seen: "set[int]" = set()
    killed = 0
    for pid, pname, _laddr in socks:
        if not pid or pid == our_pid or pid in seen:
            continue
        seen.add(pid)
        # Only act on python processes — these are the realistic candidates
        # for a stale prior run of this script. Other binaries are left
        # alone so we don't disrupt the operator's own SSH or unrelated
        # automation.
        if "python" not in (pname or "").lower():
            if log is not None:
                with suppress(Exception):
                    log.log(
                        f"[{host}] banner-retry: stale socket from "
                        f"pid={pid} ({pname or 'unknown'}); leaving alone "
                        "(not a python process)",
                    )
            continue
        with suppress(Exception):
            print(
                f"   🧹 [{host}] sending SIGTERM to stale pid={pid} "
                f"({pname}) holding an SSH session to the BMC..."
            )
        if log is not None:
            with suppress(Exception):
                log.log(
                    f"[{host}] banner-retry: SIGTERM pid={pid} ({pname}) "
                    "(stale SSH socket to BMC)",
                    prefix="WARN",
                )
        try:
            if hasattr(signal, "SIGTERM"):
                os.kill(pid, signal.SIGTERM)
            killed += 1
        except ProcessLookupError:
            pass
        except PermissionError:
            with suppress(Exception):
                print(
                    f"   ⚠️  [{host}] no permission to signal pid={pid}; "
                    "skipping."
                )
        except Exception as _kex:
            with suppress(Exception):
                print(f"   ⚠️  [{host}] could not signal pid={pid}: {_kex}")
    if killed:
        _log_ssh_remediation_event(host, "kill_stale_pids", "ok",
                                   f"pids_killed={killed}")
    return killed


def _ipmi_sol_deactivate(host: str, username: str, password: str,
                         log=None) -> bool:
    """Call `ipmitool sol deactivate` to free any stuck SOL session on the
    BMC. Returns True if ipmitool ran (regardless of exit code), False if
    ipmitool is not available or could not be invoked. Best-effort; any
    error is swallowed.
    """
    ipmi_bin = shutil.which("ipmitool")
    if not ipmi_bin:
        return False
    if not host or not username or password is None:
        return False
    cmd = [
        ipmi_bin, "-I", "lanplus",
        "-H", host, "-U", username, "-P", password,
        "sol", "deactivate",
    ]
    try:
        # Short timeout — if ipmitool hangs the BMC is unreachable anyway.
        result = subprocess.run(
            cmd, capture_output=True, text=True, timeout=15,
        )
        rc = result.returncode
        tail = (result.stderr or result.stdout or "").strip().splitlines()[-1:] or [""]
        if log is not None:
            with suppress(Exception):
                log.log(
                    f"[{host}] banner-retry: ipmitool sol deactivate "
                    f"rc={rc} ({tail[0][:120]})",
                )
        with suppress(Exception):
            if rc == 0:
                print(f"   🧹 [{host}] ipmitool: SOL session deactivated.")
                _log_ssh_remediation_event(host, "sol_deactivate", "ok", f"rc={rc}")
            else:
                # rc != 0 is common (no session to deactivate); just log.
                print(
                    f"   ℹ️  [{host}] ipmitool sol deactivate rc={rc} "
                    "(likely no active SOL session)."
                )
                _log_ssh_remediation_event(host, "sol_deactivate", "info",
                                           f"rc={rc} no_active_session")
        return True
    except subprocess.TimeoutExpired:
        if log is not None:
            with suppress(Exception):
                log.log(
                    f"[{host}] banner-retry: ipmitool sol deactivate timed out",
                    prefix="WARN",
                )
        _log_ssh_remediation_event(host, "sol_deactivate", "failed", "timeout")
        return True
    except Exception as _iex:
        if log is not None:
            with suppress(Exception):
                log.log(
                    f"[{host}] banner-retry: ipmitool sol deactivate failed: {_iex}",
                    prefix="WARN",
                )
        _log_ssh_remediation_event(host, "sol_deactivate", "failed",
                                   f"exception={_iex}")
        return False


def _diagnose_stale_bmc_sessions(host: str, log=None) -> "dict":
    """Inspect local state for sessions that could be starving the BMC's
    SSH slot pool and print a short report. Returns a dict summarising
    findings so callers can decide how to react. Always safe (read-only).

    Reports:
      - count of in-process SSHClient objects this script still holds
        to `host` (we can close these on the next sweep);
      - count of ESTABLISHED TCP sockets to `host`:22 owned by *other*
        python PIDs on this machine (likely prior AFX_reinit runs that
        died without cleaning up — killable with --auto-clear-stale-bmc);
      - count owned by non-python PIDs (operator's interactive ssh,
        sshd, scp, etc. — left alone);
      - psutil availability (without psutil only the registry count is
        meaningful).
    """
    findings = {
        "registered_clients": 0,
        "other_python_pids": [],   # list[(pid, name)]
        "non_python_pids": [],     # list[(pid, name)]
        "our_pid_sockets": 0,
        "psutil_available": True,
    }
    with _bmc_clients_lock:
        findings["registered_clients"] = len(
            _bmc_clients_by_host.get(host, [])
        )

    try:
        import psutil  # type: ignore  # noqa: F401
    except Exception:
        findings["psutil_available"] = False

    socks = _find_stale_sockets_to(host, 22) if findings["psutil_available"] else []
    our_pid = os.getpid()
    seen: "set[int]" = set()
    for pid, pname, _laddr in socks:
        if not pid or pid in seen:
            continue
        seen.add(pid)
        if pid == our_pid:
            findings["our_pid_sockets"] += 1
            continue
        if "python" in (pname or "").lower():
            findings["other_python_pids"].append((pid, pname or "unknown"))
        else:
            findings["non_python_pids"].append((pid, pname or "unknown"))

    reg = findings["registered_clients"]
    others = findings["other_python_pids"]
    nonpy = findings["non_python_pids"]
    if not findings["psutil_available"]:
        with suppress(Exception):
            print(
                f"   🔍 [{host}] stale-session diagnosis: psutil not "
                f"installed — can only see registry ({reg} in-process "
                "client(s) held by this run). Install psutil for a full scan."
            )
        if log is not None:
            with suppress(Exception):
                log.log(
                    f"[{host}] stale-session diagnosis: psutil unavailable; "
                    f"registry={reg}"
                )
        _log_ssh_remediation_event(host, "stale_diagnosis", "info",
                                   f"psutil_unavailable registered_clients={reg}")
        return findings

    if not (reg or others or nonpy):
        with suppress(Exception):
            print(
                f"   🔍 [{host}] stale-session diagnosis: no stale local "
                "SSH sockets to BMC:22 found. BMC slot pool is likely "
                "starved server-side (try ipmitool sol deactivate)."
            )
        if log is not None:
            with suppress(Exception):
                log.log(f"[{host}] stale-session diagnosis: clean")
        _log_ssh_remediation_event(host, "stale_diagnosis", "info", "clean")
        return findings

    with suppress(Exception):
        print(f"   🔍 [{host}] stale-session diagnosis:")
        if reg:
            print(f"      • {reg} in-process SSH client(s) still held by this "
                  "run (will be force-closed before next retry)")
        if findings["our_pid_sockets"]:
            print(f"      • {findings['our_pid_sockets']} socket(s) owned by "
                  "our own PID (expected; tied to in-process clients)")
        if others:
            print(f"      • {len(others)} socket(s) owned by OTHER python "
                  "process(es) — likely stale prior AFX_reinit runs:")
            for pid, pname in others:
                print(f"          - pid={pid} ({pname})")
            if not _auto_clear_stale_bmc:
                print("      💡 Re-run with --auto-clear-stale-bmc to SIGTERM "
                      "these prior runs automatically.")
        if nonpy:
            print(f"      • {len(nonpy)} socket(s) owned by non-python "
                  "process(es) (left alone):")
            for pid, pname in nonpy:
                print(f"          - pid={pid} ({pname})")
    if log is not None:
        with suppress(Exception):
            log.log(
                f"[{host}] stale-session diagnosis: registered={reg}, "
                f"our_pid_sockets={findings['our_pid_sockets']}, "
                f"other_python={[p for p,_ in others]}, "
                f"non_python={[p for p,_ in nonpy]}"
            )
    _log_ssh_remediation_event(
        host, "stale_diagnosis", "info",
        f"registered={reg} other_python_pids={len(others)} non_python={len(nonpy)}"
    )
    return findings


def _clear_stale_bmc_sessions(host: str, username: str, password: str,
                              log=None, diagnose_first: bool = True,
                              run_known_hosts_cleanup: bool = False,
                              run_ipmi_sol_deactivate: bool = True) -> None:
    """Best-effort sweep called from the banner-retry block before each
    retry sleep. Always closes in-process SSH clients to `host` (safe).
    When `--auto-clear-stale-bmc` is set, additionally scans for stale
    local PIDs and runs `ipmitool sol deactivate`.
    """
    # (0) Diagnose: report what stale sessions exist BEFORE we touch
    # anything, so the operator can see exactly what's holding BMC slots
    # and whether --auto-clear-stale-bmc would help.
    if diagnose_first:
        with suppress(Exception):
            _diagnose_stale_bmc_sessions(host, log=log)
    if run_known_hosts_cleanup:
        with suppress(Exception):
            _remove_bmc_from_known_hosts(host, log=log)
    # (1) Always safe: drop our own registered clients to this host.
    _drop_bmc_clients_for(host, log=log)
    # (2) Always safe: ipmitool sol deactivate. Cheap; clears a frequent
    # offender (a hung SOL session keeping the BMC's session pool full).
    if run_ipmi_sol_deactivate:
        with suppress(Exception):
            _ipmi_sol_deactivate(host, username, password, log=log)
    # (3) Opt-in only: signal stale prior-run python PIDs that hold a TCP
    # socket to <host>:22. Skipped by default because it can kill the
    # operator's own concurrent script invocation.
    if _auto_clear_stale_bmc:
        with suppress(Exception):
            _kill_stale_local_pids_for(host, log=log)


def _ssh_connect_with_retry(host: str, username: str, password: str,
                            label: str = "BMC",
                            max_attempts: int = 5,
                            interactive: bool = True,
                            fallback_passwords: "list[str] | None" = None,
                            is_reconnect: bool = False
                            ) -> "tuple[paramiko.SSHClient, str, str]":
    """Open an SSH client to `host` with retry-on-auth-failure.

    On `paramiko.AuthenticationException` (or any failure mentioning
    "auth"), the function first silently tries each password in
    `fallback_passwords` (if provided) before prompting the operator.
    If all fallbacks and the interactive prompt are exhausted the last
    exception is re-raised so the caller can decide to abort.

    `interactive=False` disables the credential re-prompt — useful from
    background threads where stdin contention would be problematic. In
    that mode the function only retries transient (non-auth) failures.
    """
    # Build the ordered list of (username, password) pairs to attempt.
    # Start with the supplied creds, then silently try any fallbacks.
    _attempt_queue = [(username, password)]
    for _fb in (fallback_passwords or []):
        if _fb is not None and (username, _fb) not in _attempt_queue:
            _attempt_queue.append((username, _fb))
    _queue_idx = 0  # index into _attempt_queue for silent fallback phase
    def _ssh_event(event: str, attempt: int | None = None, details: str = ""):
        _log_ssh_event(
            host, username, label, event,
            attempt=attempt, details=details, reconnect=is_reconnect
        )

    last_exc = None
    for attempt in range(1, max_attempts + 1):
        # Pick creds: work through the silent fallback queue first, then
        # use whatever (username, password) were last set by the prompt.
        if _queue_idx < len(_attempt_queue):
            username, password = _attempt_queue[_queue_idx]
            _queue_idx += 1
        try:
            client = paramiko.SSHClient()
            client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            _silent = _queue_idx <= len(_attempt_queue) and _queue_idx > 1
            if not _silent:
                print(f"   🔌 [{label}] connecting to {host} as {username} "
                      f"(attempt {attempt}/{max_attempts})...")
            else:
                print(f"   🔌 [{label}] trying fallback credentials for {host} "
                      f"(attempt {attempt}/{max_attempts})...")
            if _session_log:
                _session_log.log(
                    f"[{label}] SSH connect to {host} as {username} "
                    f"(attempt {attempt}/{max_attempts})"
                )
            _ssh_event(
                "connect_attempt",
                attempt=attempt,
                details=f"max_attempts={max_attempts}",
            )
            client.connect(hostname=host, username=username, password=password,
                            timeout=45, banner_timeout=60, auth_timeout=45,
                            disabled_algorithms={"pubkeys": ["ssh-dss"]})
            configure_transport(client)
            _register_bmc_client(host, client)
            _ssh_event("connect_success", attempt=attempt)
            return client, username, password
        except paramiko.AuthenticationException as e:
            last_exc = e
            _can_retry = (_queue_idx < len(_attempt_queue)) or (interactive and attempt < max_attempts)
            _icon = "⚠️" if _can_retry else "❌"
            print(f"   {_icon} [{label}] authentication failed for {username}@{host}.")
            if _session_log:
                _session_log.log(
                    f"[{label}] auth failed for {username}@{host}",
                    prefix="WARN" if _can_retry else "ERROR",
                )
            _ssh_event(
                "auth_failure",
                attempt=attempt,
                details=str(e).replace("\n", " "),
            )
            # If we still have silent fallbacks to try, loop immediately.
            if _queue_idx < len(_attempt_queue):
                continue
            if not interactive or attempt >= max_attempts:
                break
            try:
                with _stdin_lock:
                    print(f"\n   \U0001F510 Re-enter credentials for {host} "
                          f"(was: {username})")
                    new_user = input(
                        f"   Enter username for {host} [{username}] (blank to keep): "
                    ).strip() or username
                    new_pass = getpass.getpass(
                        f"   Enter password for {new_user}@{host} "
                        "(blank=try blank, type SKIP to stop): "
                    )
            except (EOFError, KeyboardInterrupt):
                break
            if isinstance(new_pass, str) and new_pass.strip().upper() == "SKIP":
                print("   ⚠️  Credential retry skipped by operator.")
                break
            username, password = new_user, new_pass
            if _session_log:
                _session_log.log(
                    f"[{label}] retrying with new credentials for {host} "
                    f"(user={username})"
                )
        except Exception as e:
            last_exc = e
            msg = str(e).lower()
            # ── BMC SSH temporarily not responding ────────────────────
            # When the BMC briefly drops SSH (post-reboot, BMC service
            # restart, transient network blip) paramiko surfaces
            # "Connection reset by peer" or a ConnectionResetError. In
            # those cases the BMC usually recovers in 1–5 minutes, so
            # notify the operator and retry every 2 minutes for up to
            # 10 minutes (5 retries) before giving up entirely.
            if (isinstance(e, ConnectionResetError)
                    or "connection reset" in msg
                    or "reset by peer" in msg):
                _reset_max = 5
                _reset_interval = 120  # seconds
                print(
                    f"\n   ⚠️  [{label}] SSH to {host} is currently not "
                    f"responding (connection reset by peer)."
                )
                print(
                    f"      Will retry every {_reset_interval // 60} minute(s) "
                    f"for up to {(_reset_max * _reset_interval) // 60} minutes "
                    f"before the script exits."
                )
                if _session_log:
                    _session_log.log(
                        f"[{label}] {host} SSH not responding "
                        f"(connection reset); retrying up to {_reset_max} "
                        f"times at {_reset_interval}s intervals",
                        prefix="WARN",
                    )
                _reset_done = False
                for _r in range(1, _reset_max + 1):
                    print(
                        f"   ⏳ [{label}] waiting {_reset_interval}s before "
                        f"retry {_r}/{_reset_max}..."
                    )
                    _waited = 0
                    while _waited < _reset_interval:
                        if _shutdown_event.is_set():
                            raise last_exc
                        time.sleep(1)
                        _waited += 1
                    try:
                        client = paramiko.SSHClient()
                        client.set_missing_host_key_policy(
                            paramiko.AutoAddPolicy())
                        print(
                            f"   🔌 [{label}] retrying SSH to {host} as "
                            f"{username} (reset retry {_r}/{_reset_max})..."
                        )
                        if _session_log:
                            _session_log.log(
                                f"[{label}] SSH reset retry {_r}/{_reset_max} "
                                f"to {host} as {username}"
                            )
                        _ssh_event(
                            "reset_retry_attempt",
                            attempt=_r,
                            details=f"max={_reset_max}",
                        )
                        client.connect(
                            hostname=host, username=username,
                            password=password, timeout=45,
                            banner_timeout=60, auth_timeout=45,
                            disabled_algorithms={"pubkeys": ["ssh-dss"]},
                        )
                        configure_transport(client)
                        _register_bmc_client(host, client)
                        _ssh_event("reset_retry_success", attempt=_r)
                        return client, username, password
                    except Exception as e2:
                        last_exc = e2
                        msg2 = str(e2).lower()
                        _ssh_event(
                            "reset_retry_failure",
                            attempt=_r,
                            details=str(e2).replace("\n", " "),
                        )
                        if (isinstance(e2, ConnectionResetError)
                                or "connection reset" in msg2
                                or "reset by peer" in msg2):
                            print(
                                f"   ⚠️  [{label}] {host} still not "
                                f"responding (connection reset)."
                            )
                            continue
                        # Different failure (auth, banner, etc.) — break
                        # out and let the outer logic handle/raise it.
                        print(
                            f"   ⚠️  [{label}] retry surfaced a different "
                            f"error: {e2}"
                        )
                        _reset_done = True
                        break
                if not _reset_done:
                    print(
                        f"   ❌ [{label}] {host} SSH did not recover after "
                        f"{(_reset_max * _reset_interval) // 60} minutes; "
                        "aborting."
                    )
                    if _session_log:
                        _session_log.log(
                            f"[{label}] {host} SSH never recovered after "
                            f"{_reset_max} reset retries; aborting",
                            prefix="ERROR",
                        )
                    raise last_exc
                # _reset_done True → fall through to normal handling
                # below using last_exc for the new (non-reset) failure.
                e = last_exc
                msg = str(e).lower()
            # ── BMC SSH banner not received / SP busy ─────────────────
            # The BMC SSH daemon is slow to start (post-reboot, busy
            # serving console, etc.). Wait 60s and retry, up to 5
            # minutes total (5 retries), before falling through to the
            # normal failure path.
            # paramiko surfaces a slow/half-open transport as the bare
            # SSHException "No existing session" (raised from
            # auth_password when Transport.active is False). Treat it
            # the same as a banner timeout — the BMC just isn't ready
            # to authenticate yet.
            # "Not allowed at this time" is returned by the SP/BMC when
            # it is busy with another session; also treat as transient.
            _is_banner_err = (
                "banner" in msg
                or "no existing session" in msg
                or "not allowed at this time" in msg
            )
            if _is_banner_err:
                _bnr_max = 5
                _bnr_interval = 60  # seconds
                print(
                    f"   ⚠️  [{label}] BMC SSH not ready on "
                    f"{host} (banner timeout or SP busy). Waiting "
                    f"{_bnr_interval}s and retrying (up to "
                    f"{(_bnr_max * _bnr_interval) // 60} minutes total)..."
                )
                if _session_log:
                    _session_log.log(
                        f"[{label}] banner timeout for {host}; retrying "
                        f"up to {_bnr_max} times at {_bnr_interval}s "
                        "intervals",
                        prefix="WARN",
                    )
                _bnr_done = False
                for _b in range(1, _bnr_max + 1):
                    print(
                        f"   ⏳ [{label}] waiting {_bnr_interval}s before "
                        f"banner retry {_b}/{_bnr_max}..."
                    )
                    # Before each retry sleep, try to free up a BMC SSH
                    # session slot: close any in-process clients we still
                    # hold to this host, run 'ipmitool sol deactivate'
                    # (cheap, often unblocks a stuck SOL session), and
                    # — when --auto-clear-stale-bmc is set — SIGTERM
                    # prior-run python PIDs that still hold a TCP socket
                    # to <host>:22.
                    with suppress(Exception):
                        _clear_stale_bmc_sessions(
                            host, username, password, log=_session_log,
                        )
                    _waited = 0
                    while _waited < _bnr_interval:
                        if _shutdown_event.is_set():
                            raise last_exc
                        time.sleep(1)
                        _waited += 1
                    print(
                        f"   🔁 [{label}] banner retry window elapsed; "
                        f"attempting reconnect {_b}/{_bnr_max} now..."
                    )
                    try:
                        client = paramiko.SSHClient()
                        client.set_missing_host_key_policy(
                            paramiko.AutoAddPolicy())
                        print(
                            f"   🔌 [{label}] retrying SSH to {host} as "
                            f"{username} (banner retry {_b}/{_bnr_max})..."
                        )
                        if _session_log:
                            _session_log.log(
                                f"[{label}] SSH banner retry {_b}/{_bnr_max} "
                                f"to {host} as {username}"
                            )
                        _ssh_event(
                            "banner_retry_attempt",
                            attempt=_b,
                            details=f"max={_bnr_max}",
                        )
                        client.connect(
                            hostname=host, username=username,
                            password=password, timeout=45,
                            banner_timeout=60, auth_timeout=45,
                            disabled_algorithms={"pubkeys": ["ssh-dss"]},
                        )
                        configure_transport(client)
                        _register_bmc_client(host, client)
                        _ssh_event("banner_retry_success", attempt=_b)
                        return client, username, password
                    except Exception as eb:
                        last_exc = eb
                        msg_b = str(eb).lower()
                        _ssh_event(
                            "banner_retry_failure",
                            attempt=_b,
                            details=str(eb).replace("\n", " "),
                        )
                        if ("banner" in msg_b
                                or "no existing session" in msg_b
                                or "not allowed at this time" in msg_b):
                            print(
                                f"   ⚠️  [{label}] {host} still not "
                                "responding to SSH (banner timeout or SP busy)."
                            )
                            continue
                        # Different failure — let outer logic handle it.
                        print(
                            f"   ⚠️  [{label}] retry surfaced a different "
                            f"error: {eb}"
                        )
                        _bnr_done = True
                        break
                if not _bnr_done:
                    print(
                        f"   ❌ [{label}] {host} SSH banner never arrived "
                        f"after {(_bnr_max * _bnr_interval) // 60} minutes."
                    )
                    if _session_log:
                        _session_log.log(
                            f"[{label}] {host} SSH banner never arrived "
                            f"after {_bnr_max} retries; aborting",
                            prefix="ERROR",
                        )
                    raise last_exc
                # _bnr_done True → a non-banner failure surfaced; fall
                # through to normal handling with the new exception.
                e = last_exc
                msg = str(e).lower()
            # Map paramiko's noisy "Error reading SSH protocol banner" to a
            # clearer one-liner. The BMC is usually just slow to start its
            # SSH daemon (post-reboot, BMC busy serving console, etc.).
            # "No existing session" surfaces from auth_password when the
            # transport never came up; same underlying cause, same fix.
            if ("banner" in msg
                    or "no existing session" in msg
                    or "not allowed at this time" in msg):
                friendly = ("BMC SSH not ready "
                            "(banner timeout or SP busy — try again shortly)")
                print(f"   ⚠️  [{label}] connect attempt {attempt} failed: {friendly}")
                if _session_log:
                    _session_log.log(
                        f"[{label}] banner timeout for {host}: {e}",
                        prefix="WARN",
                    )
                _ssh_event(
                    "connect_failure_banner",
                    attempt=attempt,
                    details=str(e).replace("\n", " "),
                )
            else:
                print(f"   ⚠️  [{label}] connect attempt {attempt} failed: {e}")
                if _session_log:
                    _session_log.log(
                        f"[{label}] connect attempt {attempt} failed: {e}",
                        prefix="ERROR",
                    )
                _ssh_event(
                    "connect_failure",
                    attempt=attempt,
                    details=str(e).replace("\n", " "),
                )
            # Treat "authentication"/"auth"/"password" hints as auth failures
            # too, since some paramiko/server combos surface them as generic
            # SSHException.
            if interactive and ("authentication" in msg or "auth" in msg
                                or "password" in msg) and attempt < max_attempts:
                # Exhaust silent fallbacks before prompting.
                if _queue_idx < len(_attempt_queue):
                    continue
                try:
                    with _stdin_lock:
                        print(f"\n   \U0001F510 Re-enter credentials for {host} "
                              f"(was: {username})")
                        new_user = input(
                            f"   Enter username for {host} [{username}] (blank to keep): "
                        ).strip() or username
                        new_pass = getpass.getpass(
                            f"   Enter password for {new_user}@{host} "
                            "(blank=try blank, type SKIP to stop): "
                        )
                except (EOFError, KeyboardInterrupt):
                    break
                if isinstance(new_pass, str) and new_pass.strip().upper() == "SKIP":
                    break
                username, password = new_user, new_pass
                continue
            time.sleep(min(5 * attempt, 15))
    _ssh_event(
        "connect_exhausted",
        attempt=max_attempts,
        details=(str(last_exc).replace("\n", " ") if last_exc else "no exception detail"),
    )
    raise last_exc if last_exc else RuntimeError(
        f"Could not connect to {host} after {max_attempts} attempts"
    )


def connect_to_sp(host, username, password):
    """Connect to the primary BMC. Returns (client, username, password) so
    the caller can update stored creds if the user re-entered them after an
    initial auth failure.
    
    During checkpoint resume, uses interactive=False to avoid re-prompting for
    credentials (since original credentials are wiped during init). Relies on
    fallback blank password instead.
    """
    global _active_client, _primary_bmc_host, _primary_bmc_user
    global _primary_bmc_password, _primary_bmc_reconnect_ctx
    global _checkpoint_mode, _resume_cp_start
    _preclean_bmc_known_hosts(host, log=_session_log, context="before BMC login")
    print(f"Connecting to SP at {host} with username {username}...")
    _slog(f"Connecting to SP at {host} with username {username}")
    
    # During checkpoint resume, don't prompt for credentials; rely on fallback
    # blank password instead (original password was wiped during init).
    _in_checkpoint_resume = _checkpoint_resume_active()
    _is_interactive = not _in_checkpoint_resume
    
    # Prepare fallback passwords including blank password for post-reset recovery.
    _fallback_pw = _bmc_fallback_passwords(host, {host: password})
    
    try:
        client, username, password = _ssh_connect_with_retry(
            host, username, password, label="primary BMC", max_attempts=5,
            interactive=_is_interactive,
            fallback_passwords=_fallback_pw,
        )
    except Exception as e:
        print(f"❌ Error connecting to SP: {e}")
        _slog(f"SSH connection failed: {e}", prefix="ERROR")
        sys.exit(1)
    print("✅ Connection successful!")
    _slog("SSH connection established successfully")
    with _client_lock:
        _active_client = client
    _primary_bmc_host = host
    _primary_bmc_user = username
    _primary_bmc_password = password
    _primary_bmc_reconnect_ctx = _make_reconnect_ctx(
        host, username, password, client=client, channel=None, label="primary BMC"
    )
    return client, username, password


def is_session_alive(client, channel):
    try:
        transport = client.get_transport()
        if transport is None or not transport.is_active():
            return False
        return not channel.closed
    except Exception:
        return False


def reconnect_to_sp(host, username, password):
    """Reconnect after a session drop. Retries with the same credentials,
    falling back to prompting if the BMC's password has changed.
    """
    global _active_client, _primary_bmc_host, _primary_bmc_user
    global _primary_bmc_password, _primary_bmc_reconnect_ctx
    try:
        client, username, password = _ssh_connect_with_retry(
            host, username, password, label="reconnect", max_attempts=5,
            interactive=True,
        )
    except Exception as e:
        print(f"❌ Could not reconnect: {e}")
        _slog(f"All reconnection attempts failed: {e}", prefix="ERROR")
        return None, None
    channel = _open_shell(client)
    print("✅ Reconnected!")
    _slog("Reconnected successfully")
    with _client_lock:
        _active_client = client
    _primary_bmc_host = host
    _primary_bmc_user = username
    _primary_bmc_password = password
    _primary_bmc_reconnect_ctx = _make_reconnect_ctx(
        host, username, password, client=client, channel=channel, label="primary BMC"
    )
    return client, channel


# ---------------------------------------------------------------------------
# Keepalive thread
# ---------------------------------------------------------------------------

def keepalive_loop(client):
    logger = logging.getLogger("keepalive")
    while not _shutdown_event.is_set():
        try:
            with _client_lock:
                c = _active_client or client
            transport = c.get_transport()
            if transport and transport.is_active():
                transport.send_ignore()
                logger.debug("Keepalive sent")
        except Exception as e:
            logger.debug("Keepalive error: %s", e)
        _shutdown_event.wait(5)


# ---------------------------------------------------------------------------
# Direct channel I/O
# ---------------------------------------------------------------------------

def _reclaim_system_console(channel, node_log=None):
    """Re-enter system console after an unexpected drop to the BMC prompt
    or a session-preemption notice.
    Auto-answers 'y' to any existing-session takeover question.
    Called from within the read loops when _looks_like_bmc_drop() fires.
    """
    print("\n⚠️  BMC prompt/preemption detected – reconnecting to system console...")
    _slog("BMC prompt or session preemption seen mid-wait; re-sending 'system console'",
          prefix="WARN")
    try:
        channel.send("\r")
    except Exception:
        pass
    _pre_buf = ""
    _pre_deadline = time.monotonic() + 3
    while time.monotonic() < _pre_deadline:
        if channel.recv_ready():
            chunk = channel.recv(4096).decode("utf-8", errors="replace")
            _pre_buf += chunk
            if node_log:
                _par_write(node_log, chunk)
            if _session_log:
                _session_log.log_console(chunk)
            _pre_lower = _pre_buf.lower()
            if (_LOADER_PROMPT_RE.search(_pre_buf)
                    or any(s in _pre_lower for s in ("loader-", "::>", "::*>", "selection", "autoboot", "login:"))):
                print("✅ System console already active.")
                _slog("System console reclaim skipped because console is already active")
                return True
        time.sleep(0.1)
    # Brief pause to let the SP finish its preemption message before we send.
    time.sleep(1)
    channel.send("system console\r")
    if _session_log:
        _session_log.log_sent("system console")
    buf = ""
    _rc_deadline = time.monotonic() + 15
    while time.monotonic() < _rc_deadline:
        if channel.recv_ready():
            chunk = channel.recv(4096).decode("utf-8", errors="replace")
            buf += chunk
            if node_log:
                _par_write(node_log, chunk)
            if _session_log:
                _session_log.log_console(chunk)
            buf_lower = buf.lower()
            if "y/n" in buf_lower:
                print("⚠️  Existing console session – auto-disconnecting (y)...")
                _slog("Existing console session; auto-sending 'y'", prefix="WARN")
                channel.send("y\r")
                if _session_log:
                    _session_log.log_sent("y")
                time.sleep(1)
                print("✅ System console reconnected.")
                _slog("System console reconnected after auto-takeover")
                return True
            if any(s in buf_lower for s in
                   ("ctrl-d", "type exit", "serial", "loader-", "autoboot", "selection")):
                print("✅ System console reconnected.")
                _slog("System console reconnected")
                return True
        time.sleep(0.1)
    print("⚠️  System console reconnect timed out – continuing anyway.")
    _slog("System console reconnect timed out", prefix="WARN")
    return False


_BMC_CONSOLE_KEEPALIVE_INTERVAL = 30  # seconds between null-byte keepalives
_BMC_CONSOLE_SILENCE_RECONNECT_INTERVAL = 300  # 5 minutes with no console data
_BMC_CONSOLE_REENTRY_RETRY_INTERVAL = 15  # seconds between repeated 'system console' retries
_BMC_RECONNECT_NOTICE_LIMIT = 5


def _make_reconnect_ctx(host, user, password, client=None, channel=None, label=""):
    """Build a mutable reconnect context for BMC console watchdog use."""
    return {
        "host": host,
        "user": user,
        "password": password,
        "client": client,
        "channel": channel,
        "label": label or host or "BMC",
        "reconnect_notice_limit": _BMC_RECONNECT_NOTICE_LIMIT,
        "reconnect_notice_streak": 0,
        "reconnect_notice_suppressed": False,
    }


def _emit_reconnect_notice_with_suppression(
        state_holder, label, console_msg="", log_msg="", log_prefix="WARN",
        console_writer=None, log_writer=None):
    """Emit reconnect status with suppression after N consecutive notices."""
    if state_holder is None:
        if console_msg:
            if console_writer:
                console_writer(console_msg)
            else:
                print(console_msg)
        if log_msg:
            if log_writer:
                log_writer(log_msg, log_prefix)
            else:
                _slog(log_msg, prefix=log_prefix)
        return

    limit = state_holder.get("reconnect_notice_limit", _BMC_RECONNECT_NOTICE_LIMIT)
    streak = int(state_holder.get("reconnect_notice_streak", 0)) + 1
    suppressed = bool(state_holder.get("reconnect_notice_suppressed", False))
    state_holder["reconnect_notice_streak"] = streak

    if streak <= limit:
        if console_msg:
            if console_writer:
                console_writer(console_msg)
            else:
                print(console_msg)
        if log_msg:
            if log_writer:
                log_writer(log_msg, log_prefix)
            else:
                _slog(log_msg, prefix=log_prefix)
        return

    if not suppressed:
        _sup_msg = (
            f"ℹ️  [{label}] Suppressing repeated BMC reconnect messages "
            "until reconnect succeeds or timeout."
        )
        if console_writer:
            console_writer(_sup_msg)
        else:
            print(_sup_msg)
        _sup_log = (
            f"[{label}] suppressing repeated BMC reconnect messages after "
            f"{limit} consecutive notices"
        )
        if log_writer:
            log_writer(_sup_log, "WARN")
        else:
            _slog(_sup_log, prefix="WARN")
        state_holder["reconnect_notice_suppressed"] = True


def _reset_reconnect_notice_suppression(state_holder):
    if state_holder is None:
        return
    state_holder["reconnect_notice_streak"] = 0
    state_holder["reconnect_notice_suppressed"] = False


def _recv_loop(channel, matchers, timeout=15, node_log=None, check_bmc_drop=False,
               quiet=False, reconnect_ctx=None, cr_nudge_interval=None):
    """Shared receive loop used by direct_send_and_wait / direct_read_until /
    direct_read_until_any.

    ``matchers`` is a list of ``(lower_str, original_str)`` pairs.  The loop
    reads from *channel* until one of the matchers is found in the accumulated
    output or *timeout* seconds elapses.

    Returns ``(output, matched_original)`` where *matched_original* is the
    original (non-lower-cased) string from *matchers* that triggered the
    match, or ``None`` on timeout / shutdown.  The full accumulated *output*
    string is always returned unmodified so callers can inspect it.

    A null byte (b"\\x00") is sent every _BMC_CONSOLE_KEEPALIVE_INTERVAL
    seconds of inactivity to prevent the BMC application-level autologout from
    firing during long waits (e.g., waiting for the boot menu during a reboot).
    Null bytes are ignored by the ONTAP/LOADER console but reset the BMC's
    idle timer.

    When *cr_nudge_interval* is set (seconds), a carriage-return is sent after
    that many seconds of console silence to elicit the current prompt.
    """
    output = ""
    output_lower = ""
    start_time = time.monotonic()
    last_console_data = time.monotonic()
    last_keepalive_send = 0.0
    last_cr_nudge = time.monotonic()
    last_silence_reconnect_attempt = 0.0

    if reconnect_ctx and reconnect_ctx.get("channel") is not None:
        channel = reconnect_ctx.get("channel")

    while True:
        if _shutdown_event.is_set():
            return output, None
        _wait_if_paused("console I/O loop")
        if channel.recv_ready():
            chunk = channel.recv(4096).decode("utf-8", errors="replace")
            last_console_data = time.monotonic()
            output += chunk
            output_lower += chunk.lower()
            if len(output_lower) > 16384:
                output_lower = output_lower[-8192:]
            if node_log:
                _par_write(node_log, chunk)
            elif not quiet and not _console_quiet:
                sys.stdout.write(chunk)
                sys.stdout.flush()
            if _session_log:
                _session_log.log_console(chunk)
            if check_bmc_drop and _looks_like_bmc_drop(chunk):
                if not _pause_allows_reconnect("BMC drop detected"):
                    continue
                _rc_t = time.monotonic()
                _reclaim_system_console(channel, node_log=node_log)
                start_time += time.monotonic() - _rc_t
                last_console_data = time.monotonic()
                last_keepalive_send = 0.0
                output = ""
                output_lower = ""
                continue
            for lower_m, orig_m in matchers:
                if lower_m in output_lower:
                    return output, orig_m
        if time.monotonic() - start_time > timeout:
            _reset_reconnect_notice_suppression(reconnect_ctx)
            return output, None
        # Periodic null-byte keepalive to prevent BMC application-level
        # autologout during long waits (e.g. waiting for node to boot).
        _now = time.monotonic()
        _idle = _now - last_console_data
        if (_idle >= _BMC_CONSOLE_KEEPALIVE_INTERVAL
                and (_now - last_keepalive_send) >= _BMC_CONSOLE_KEEPALIVE_INTERVAL):
            try:
                channel.sendall(b"\x00")
            except Exception:
                pass
            last_keepalive_send = _now

        # After cr_nudge_interval seconds of console silence, send a carriage
        # return to elicit the current prompt (LOADER, boot menu, or shell).
        if (cr_nudge_interval is not None
                and _idle >= cr_nudge_interval
                and (_now - last_cr_nudge) >= cr_nudge_interval):
            try:
                channel.send("\r")
            except Exception:
                pass
            last_cr_nudge = _now

        # If this is a BMC-aware read path and console output has gone silent
        # for too long, attempt a full SSH reconnect and re-enter system console.
        if (check_bmc_drop and reconnect_ctx and reconnect_ctx.get("host")
                and _idle >= _BMC_CONSOLE_SILENCE_RECONNECT_INTERVAL
                and (_now - last_silence_reconnect_attempt) >= _BMC_CONSOLE_SILENCE_RECONNECT_INTERVAL):
            if not _pause_allows_reconnect("console silence reconnect"):
                continue
            _rc_t = _now
            last_silence_reconnect_attempt = _now
            _host = reconnect_ctx.get("host")
            _user = reconnect_ctx.get("user")
            _pw = reconnect_ctx.get("password")
            _client = reconnect_ctx.get("client")
            _label = reconnect_ctx.get("label") or _host or "BMC"
            _emit_reconnect_notice_with_suppression(
                reconnect_ctx, _label,
                console_msg=(
                    f"\n⚠️  [{_label}] No BMC console output for 5 minutes. "
                    "Reconnecting SSH/session console..."
                ),
                log_msg=f"[{_label}] no console activity for 5 minutes; reconnecting BMC SSH/system console",
                log_prefix="WARN",
            )
            try:
                try:
                    channel.close()
                except Exception:
                    pass
                try:
                    if _client:
                        _client.close()
                except Exception:
                    pass

                _new_client, _new_user, _new_pw = _ssh_connect_with_retry(
                    _host, _user, _pw,
                    label=_label,
                    max_attempts=3,
                    interactive=True,
                    is_reconnect=True,
                )
                _new_ch = _open_shell(_new_client)
                if not _reach_bmc_prompt(_new_ch, timeout=15, node_log=node_log):
                    raise RuntimeError("BMC prompt not reached after reconnect")
                _new_ch.send("system console\r")
                _sc_out, _sc_m = direct_read_until_any(
                    _new_ch,
                    ["y/n", "ctrl-d", "type exit", "serial console",
                     "boot loader", "loader-", "autoboot", "selection", "::>", "login:"],
                    timeout=20,
                    node_log=node_log,
                    quiet=True,
                )
                if _sc_m and "y/n" in _sc_m.lower():
                    _new_ch.send("y\r")
                    time.sleep(1)
                    direct_read_until_any(
                        _new_ch,
                        ["ctrl-d", "type exit", "serial console", "boot loader",
                         "loader-", "autoboot", "selection", "::>", "login:"],
                        timeout=20,
                        node_log=node_log,
                        quiet=True,
                    )
                _new_ch.send("\r")
                channel = _new_ch
                reconnect_ctx["channel"] = _new_ch
                reconnect_ctx["client"] = _new_client
                reconnect_ctx["user"] = _new_user
                reconnect_ctx["password"] = _new_pw
                _reset_reconnect_notice_suppression(reconnect_ctx)
                output = ""
                output_lower = ""
                last_console_data = time.monotonic()
                last_keepalive_send = 0.0
                start_time += time.monotonic() - _rc_t
                print(f"✅ [{_label}] BMC reconnect successful. Resuming wait.")
                _slog(f"[{_label}] BMC reconnect successful; resumed console monitoring")
                continue
            except Exception as _silence_rc_exc:
                _slog(f"[{_label}] BMC reconnect after 5m silence failed: {_silence_rc_exc}",
                      prefix="ERROR")
        time.sleep(0.1)


def direct_send_and_wait(channel, command, look_for, timeout=15, auto_respond=None,
                         node_log=None, check_bmc_drop=False, quiet=False,
                         reconnect_ctx=None):
    if _session_log and command:
        _session_log.log_sent(command)
    _rc = reconnect_ctx
    if _rc is None and check_bmc_drop and _primary_bmc_reconnect_ctx:
        _rc = _primary_bmc_reconnect_ctx
    _ch = _rc.get("channel") if (_rc and _rc.get("channel") is not None) else channel
    if command:
        _ch.send(command + "\r")
    matchers = [(look_for.lower(), look_for)] if look_for else []
    output, matched = _recv_loop(_ch, matchers, timeout, node_log, check_bmc_drop,
                                 quiet=quiet, reconnect_ctx=_rc)
    if matched is None:
        _slog(f"Timeout ({timeout}s) waiting for '{look_for}'", prefix="WARN")
    elif auto_respond:
        time.sleep(0.3)
        _ch2 = _rc.get("channel") if (_rc and _rc.get("channel") is not None) else _ch
        _ch2.send(auto_respond + "\r")
        if not quiet:
            print(f"\n✅ {_node_pfx()}Detected '{look_for}' – auto-responded with '{auto_respond}'{_elapsed_str()}")
        elif node_log:
            _par_write(node_log, f"\n>>> auto-responded to '{look_for}' with '{auto_respond}'\n")
        if _session_log:
            _session_log.log(f"Detected '{look_for}' – auto-responded with '{auto_respond}'")
            _session_log.log_sent(auto_respond)
    return output


def direct_read_until(channel, look_for, timeout=15, node_log=None, check_bmc_drop=False):
    _rc = _primary_bmc_reconnect_ctx if (check_bmc_drop and _primary_bmc_reconnect_ctx) else None
    _ch = _rc.get("channel") if (_rc and _rc.get("channel") is not None) else channel
    matchers = [(look_for.lower(), look_for)] if look_for else []
    output, matched = _recv_loop(_ch, matchers, timeout, node_log, check_bmc_drop,
                                 reconnect_ctx=_rc)
    if matched is None and _session_log:
        _session_log.log(f"Timeout ({timeout}s) waiting for '{look_for}'", prefix="WARN")
    return output


def direct_read_until_any(channel, look_for_list, timeout=15, node_log=None,
                          check_bmc_drop=False, quiet=False, reconnect_ctx=None,
                          cr_nudge_interval=None):
    _rc = reconnect_ctx
    if _rc is None and check_bmc_drop and _primary_bmc_reconnect_ctx:
        _rc = _primary_bmc_reconnect_ctx
    _ch = _rc.get("channel") if (_rc and _rc.get("channel") is not None) else channel
    matchers = [(s.lower(), s) for s in look_for_list]
    _wait_start = time.monotonic()
    output, matched = _recv_loop(_ch, matchers, timeout, node_log, check_bmc_drop,
                                 quiet=quiet, reconnect_ctx=_rc,
                                 cr_nudge_interval=cr_nudge_interval)
    _wait_elapsed = max(0.0, time.monotonic() - _wait_start)
    if matched is None and _session_log and not _shutdown_event.is_set():
        _log_wait_timeout_throttled(timeout, look_for_list, _wait_elapsed)
    return output, matched


def drain_channel(channel, seconds=2, node_log=None, quiet=False):
    output = ""
    start_time = time.monotonic()
    while time.monotonic() - start_time < seconds:
        if _shutdown_event.is_set():
            return output
        _wait_if_paused("channel drain")
        if channel.recv_ready():
            chunk = channel.recv(4096).decode("utf-8", errors="replace")
            output += chunk
            if node_log:
                _par_write(node_log, chunk)
            elif not quiet and not _console_quiet:
                sys.stdout.write(chunk)
                sys.stdout.flush()
            if _session_log:
                _session_log.log_console(chunk)
        time.sleep(0.1)
    return output


# ---------------------------------------------------------------------------
# Signal handler – force exit on second Ctrl+C
# ---------------------------------------------------------------------------

def signal_handler(sig, frame):
    global _ctrl_c_count
    _ctrl_c_count += 1

    if _ctrl_c_count == 1:
        print("\n👋 Received termination signal. Exiting now...")
        _slog("Received termination signal (Ctrl+C or SIGTERM); exiting immediately")
        _shutdown_event.set()
        _restore_terminal()
        if _session_log:
            with suppress(Exception):
                _session_log.log("Terminated by signal (first Ctrl+C / SIGTERM)")
                _session_log.set_outcome("FAIL", "terminated by signal")
                _session_log.close()
        raise SystemExit(130)
    else:
        print("\n⚡ Force exit!")
        _restore_terminal()
        if _session_log:
            try:
                _session_log.log("Force exit (second Ctrl+C)")
                _session_log.set_outcome("FAIL", "force exit (second Ctrl+C / signal)")
                _session_log.close()
            except Exception:
                pass
        os._exit(1)


def pause_toggle_signal_handler(sig, frame):
    _now_paused = not _pause_requested()
    _set_pause_state(_now_paused, source=f"signal {sig} toggle")


def pause_clear_signal_handler(sig, frame):
    _set_pause_state(False, source=f"signal {sig} clear")


def manual_checkpoint_signal_handler(sig, frame):
    _manual_checkpoint_signal_event.set()


def _print_man_page():
    """Print a man page-style reference for all CLI options."""
    # Fit to terminal width, capped at 100 columns.
    # Use plain ASCII for the horizontal rule so --help works on consoles
    # that cannot encode box-drawing Unicode characters.
    cols = min(shutil.get_terminal_size((80, 24)).columns, 100)
    rule = "-" * cols

    page = f"""
{rule}
NAME
    AFX_reinit.py — NetApp AFX cluster reinitialization automation script

SYNOPSIS
    python3 AFX_reinit.py [OPTIONS]

DESCRIPTION
    Automated BMC/SP console management tool for reinitializing NetApp AFX
    cluster nodes.  Connects to each node's Baseboard Management Controller
    (BMC) or Service Processor (SP) via SSH, drives the LOADER boot sequence,
    and automates the ONTAP cluster-setup and node-join wizards.

    Operation modes (selected interactively at startup):

      1.1   Initialize first node — interactive wizard
        1   Initialize first node — fully automated
      2.1   Add node to existing cluster — interactive wizard
           (supports password groups + blank-password fallback retries)
      2.2   Add node to existing cluster — automated (parallel multi-node)
           (supports password groups + blank-password fallback retries)
       3   End-to-end reinit: mode 1 on primary + mode 2.2 on all peers
           (same credential-grouping/fallback behavior as 2.2; reinit-only)
           ONTAP installs are handled by 4.2/4.3 before running mode 3
           includes per-node join-status output during bulk add-node polling
      4.1   ONTAP rolling upgrade (takeover / software update / giveback)
      4.2   Netboot + automated cluster reinit (strict sequencing)
      4.3   Netboot and install ONTAP image only (no reinit)
      5.1   Standalone license install
      5.2   Set up passwordless SSH to cluster management
      5.3   Create / save cluster configuration backup (JSON)
      5.4   Verify BMC SSH authentication for selected/all nodes
      5.5   Check node status (LOADER / cluster prompt)
      5.6   Cluster health and version check
      5.7   SSH diagnostics, cleanup, and known_hosts reset
      5.8   Backup LOADER environment variables (experimental)
      5.9   Compare LOADER env to defaults (diff) (experimental)
      5.10   Check boot DNA (config target picker + state-aware query)
      5.11   Build cluster_IP.json manifest for node-add workflows
      5.12   Compare and correct cluster node names and LIF IP addresses
      5.13   Show reinit-config.json in human-readable format
      5.99   Reset all nodes to LOADER prompt (parallel; disruptive command)

OPTIONS
    -h, --help
        Print this help page and exit.

    --version
        Print script version and last update timestamp, then exit.

    -c PATH, --config PATH
        Path to a JSON configuration file containing cluster and node
        parameters (BMC addresses, credentials, management IPs, etc.).
        If omitted, the script searches standard locations automatically
        and prompts for any missing values at runtime.

        Use --config-example to print an annotated template.

    --config-example
        Print an annotated example configuration file to stdout and exit.
        Redirect to a file to create a starting template:

            python3 AFX_reinit.py --config-example > reinit-config.json

    -d, --debug
        Debug mode.  Prints all raw BMC/SP and ONTAP console I/O directly
        to the terminal (in addition to the log file).  Also sets Python
        logging to DEBUG level, exposing verbose Paramiko SSH messages.
        Use this to diagnose hangs, prompt-matching failures, or SSH
        authentication issues.

    --bg
        Background mode.  Registers a SIGHUP handler so the session log is
        flushed and closed cleanly if the controlling terminal disconnects.
        Use with nohup(1) or inside a screen/tmux session.

        Note: SIGHUP is not supported on Windows.  The flag is accepted but
        has no effect on that platform.

    --screen
        Re-launch the script inside a detached GNU screen(1) session, then
        exit the outer process.  The run continues unattended in the
        background; if your SSH connection drops or times out, reattach from
        any new terminal.

        Behaviour:
          • Checks the STY environment variable.  If STY is set (already
            inside a screen session) this flag is silently ignored and the
            script proceeds normally — no recursive spawn.
          • Exits with install instructions if screen(1) is not found.
          • Automatically appends --bg to the forwarded argument list.
          • Detached session name: afx-reinit

        Reattach with:
            screen -r afx-reinit

        List all sessions:
            screen -ls

        Screen navigation tips:
            Ctrl+A Esc   Enter scrollback mode
            Arrow/PgUp/PgDn  Navigate scrollback
            q            Exit scrollback mode
            Ctrl+A d     Detach from session

    TERMINAL COLOR SETUP (SSH / PuTTY)
        Linux/macOS terminal clients:
          • Prefer a 256-color terminal profile.
          • Ensure TERM is set to xterm-256color:
                export TERM=xterm-256color
          • If needed, add to your shell profile (~/.bashrc):
                echo 'export TERM=xterm-256color' >> ~/.bashrc

        PuTTY (Windows -> Linux jump host):
          • Window > Colours: enable ANSI color and bright colors.
          • Connection > Data: set Terminal-type string to xterm-256color.
          • Save the PuTTY session and reconnect.

        Note: GNU screen is available on Linux and macOS only.  On Windows
        use WSL or a Linux jump host for equivalent functionality.

    --resume
        Resume the previous 4.2 run from its saved
        checkpoint (checkpoints/afx_checkpoint.json, located alongside this script).
        Phases already completed are skipped — when every BMC IP is
        marked install_done the run jumps straight to Step 6b
        (reconnect to LOADER + boot_ontap menu); peers marked
        peer_joined are skipped during the mode-3 parallel auto-add.

        If primary_setup_done or option3_complete is set from a prior
        run, the resume prompt warns that re-running will destroy the
        existing cluster and asks for explicit confirmation.

        Checkpoints older than 72 hours are ignored.  The file is
        deleted automatically on successful completion of mode 4.2.

    --checkpoint-status
        Print a summary of the saved checkpoint (checkpoints/afx_checkpoint.json)
        and exit.  Shows the absolute file path, run mode, created /
        updated timestamps, current phase, next expected phase, age in minutes,
        log directory, config path, BMC IPs, every completed global phase, and
        role-labeled per-node phase blocks (primary / secondary-0N). Does not
        modify the checkpoint file.

    --checkpoint-list
        Print all available checkpoint IDs grouped by mode (1, 2, 3, 4.1, 4.2,
        4.3), then exit. Useful for planning resume tests and targeted
        --test-checkpoint injection points.

    --last-status
        Read and display the summary file from the most recent AFX_reinit
        run, then exit. The summary file is created at run start and
        refreshed as phases progress, so this can show live in-progress
        status (including phases not yet completed). The summary shows
        overall result, phase timing, step timing, error/warning count,
        runtime duration, and classified non-phase timing such as
        startup/inter-phase gaps, prompt waits, and explicit pause waits.

    --show-config
        Read and display the reinit-config.json (or equivalent config file)
        in human-readable format, then exit. Passwords are masked as [set]
        or [none]. Use --config to specify the file path explicitly;
        otherwise the script searches standard locations automatically.

    --install-completion
        Install startup option tab-completion support:
          1) Installs Python module 'argcomplete' when missing.
          2) Adds completion hook blocks to ~/.bashrc and ~/.zshrc.
        Prints the exact hook command to run immediately in the current shell.

    --print-completion-hook
        Print the completion hook command only (no file changes), then exit.

    --auto-clear-stale-bmc
        On BMC SSH banner-timeout retries, scan for ESTABLISHED sockets to
        <bmc>:22 owned by other local python processes and SIGTERM them.
        Always-on cleanup (close in-process SSH clients + ipmitool SOL
        deactivate) still runs regardless of this flag.

    --diag
        Enable diagnostic bootarg injection at LOADER. Bootargs are loaded
        from bootargs.txt / bootargs (or prompted interactively), then
        applied after set-defaults and before saveenv.

    --test
        Enable checkpoint failure injection for testing checkpoint recovery logic.
        After selecting a mode, the script displays available checkpoints and prompts
        you to choose which one to inject a failure at. When that checkpoint is reached,
        the script injects a simulated failure and exits. Useful for validating resume
        procedures and recovery behavior.
        
        Supported modes: 1, 2, 3, 4.1, 4.2, 4.3
        Available checkpoints vary by mode:
          â€¢ Mode 1: 23 checkpoints (cp_1_1 through cp_1_8, including cp_1_7_1...cp_1_7_15)
          â€¢ Mode 2: 8 checkpoints (cp_2_1 through cp_2_8)
          â€¢ Mode 3: 30 checkpoints (combined primary + peers)
          â€¢ Mode 4.1: 6 checkpoints
          â€¢ Mode 4.2: 6 checkpoints (no option 6)
          â€¢ Mode 4.3: 6 checkpoints
        
        After a test failure, restart with --resume to test checkpoint recovery.
        Use with -v for verbose output to see checkpoint details.

    --test-checkpoint NODE_IP:CHECKPOINT_ID
        Inject failure at a specific checkpoint for a specific node.
        Format: '10.1.1.192:cp_1_5' (node IP, colon, checkpoint ID).
        
        Implies --test flag. Useful for testing recovery from specific failure points
        in multi-node operations or debugging particular phase transitions.
        
        Example checkpoint IDs:
          â€¢ cp_1_5  = Mode 1, checkpoint 5 (Option 4 completed)
          â€¢ cp_2_3  = Mode 2, checkpoint 3 (option 4 issued)
          â€¢ cp_4a_2 = Mode 4.1, checkpoint 2 (Image installed)

    Startup flag completion
        Startup CLI flags can be Tab-completed when argcomplete is installed
        and your shell has its completion hook enabled.
        You can set this up with:
            python3 AFX_reinit.py --install-completion
        Or print just the hook command with:
            python3 AFX_reinit.py --print-completion-hook

    Mode shortcut flags (bypass interactive menu):
        --first-node      Run mode 1 directly
        --add-nodes       Run mode 2.2 directly
        --reinit          Run mode 3 directly
        --netboot-install Run mode 4.2 directly
        --add-lic         Run mode 5.1 directly
        --passwordless    Run mode 5.2 directly
        --backup          Run mode 5.3 directly
        --verify          Run mode 5.4 directly
        --loader          Run mode 5.99 directly

CHECKPOINTS AND RECOVERY

    AFX_reinit automatically creates checkpoints during operation to enable recovery
    from failure points. Each node gets its own checkpoint file in the "checkpoints/"
    directory with independent phase tracking.

    CHECKPOINT PHASES BY MODE
       Mode 1 (Primary init):     7 phases - LOADER config → cluster created
       Mode 2 (Add nodes):        7 phases - LOADER → joined to cluster
       Mode 3 (End-to-end):      14 phases - Primary + peer in parallel (tracked independently)
       Mode 4.1 (Rolling upgrade): 6 phases - Download image → upgrade complete
       Mode 4.2 (Netboot reinit):  6 phases - LOADER → cluster initialized (no option 6)
       Mode 4.3 (Install only):    6 phases - LOADER → nodes booting

    RESUMING FROM CHECKPOINT
       1. Restart the script:       python3 AFX_reinit.py
       2. Select "Resume from last checkpoint" when prompted
       3. Script skips completed phases and continues from next pending phase

    TESTING CHECKPOINT RECOVERY
       # Interactive checkpoint selection
       python3 AFX_reinit.py --test

       # Test specific checkpoint for specific node (EXPERIMENTAL)
       python3 AFX_reinit.py --test-checkpoint 10.1.1.192:cp_1_5

    VIEWING CHECKPOINT DATA
       # Display saved checkpoint information
       python3 AFX_reinit.py --inspect-checkpoint
        
       # Display status of the most recent run
       python3 AFX_reinit.py --last-status

    CHECKPOINT FILES
       Location: checkpoints/{{node_id}}_checkpoint.json
       Format:   JSON v2 with per-node phase tracking
       Expiry:   Checkpoints older than 72 hours are ignored
       Cleanup:  Automatically deleted on successful completion
        
       Manually clear all checkpoints: rm -rf checkpoints/*.json

    For more details, see README.md section "Checkpoint System"

INTERACTIVE FEATURES

    Path Tab Completion

        When the script prompts for a file path or URL (e.g., "Path or URL: /scripts/ONTAP"),
        you can press Tab to auto-complete matching paths from the filesystem.  This feature
        is available on Linux, macOS, and Unix systems with Python's readline module.

        On each Tab press:
          • The script lists matching files and directories
          • Directory names are suffixed with "/" to indicate you can continue
          • Partial names are completed to the longest unambiguous match

        Works for:
          • Config file paths (--config or interactive prompts)
          • ONTAP image paths (mode 4.2 netboot/reinit)
          • Bootargs files (--diag)
          • License file paths (mode 5.1)
          • Any other file/URL input

        Example:
            Path or URL: /scr[TAB]
            → /scripts/
            Path or URL: /scripts/O[TAB]
            → /scripts/ONTAP/
            Path or URL: /scripts/ONTAP/ONTAP[TAB]
            → /scripts/ONTAP/ONTAP-9.15.1.img

EXAMPLES
    Interactive run (prompts for all values):
        python3 AFX_reinit.py

    Automated run with config file:
        python3 AFX_reinit.py --config configs/reinit-config.json

    Print config file template:
        python3 AFX_reinit.py --config-example > configs/reinit-config.json

    Debug a failed run:
        python3 AFX_reinit.py --debug --config configs/reinit-config.json

    Protected remote run (auto screen session):
        python3 AFX_reinit.py --screen --config configs/reinit-config.json

    Reattach to a running screen session:
        screen -r afx-reinit

    Manual nohup background run:
        nohup python3 AFX_reinit.py --bg --config configs/reinit-config.json \\
              > nohup.out 2>&1 &

    Inspect a saved 4.2 checkpoint:
        python3 AFX_reinit.py --checkpoint-status

    Resume an interrupted 4.2 run:
        python3 AFX_reinit.py --resume --config configs/reinit-config.json

    Check the result of the most recent run:
        python3 AFX_reinit.py --last-status

    Print script version metadata:
        python3 AFX_reinit.py --version

    Install startup option tab-completion:
        python3 AFX_reinit.py --install-completion

    Print completion hook command only:
        python3 AFX_reinit.py --print-completion-hook

FILES
    reinit-config.json
        Default configuration file name.  Searched in ./configs/, the script
        directory, then the current working directory.

    logs/YYYYMMDD_HHMMSS/session_<label>.log
        Full raw console transcript for the session.

    logs/YYYYMMDD_HHMMSS/summary_<label>.log
        Human-readable summary: result (PASS/FAIL/WARN), phase and step
        timing, warnings inventory, and errors inventory.

    checkpoints/afx_checkpoint.json
        Resume checkpoint written under the script's checkpoints/
        directory; deleted automatically on successful completion.  Inspect with
        --checkpoint-status; resume with --resume.  Ignored if older than
        72 hours.

ENVIRONMENT
    STY     Set by GNU screen for all child processes.  When present,
            --screen is a no-op (script is already inside a screen session).

EXIT STATUS
    0   Success (or --help / --config-example printed and exited cleanly).
    1   Fatal error (connection failure, timeout, unhandled exception, or
        screen(1) not found when --screen was requested).

SEE ALSO
    screen(1), nohup(1), ssh(1), python3(1)
    NetApp ONTAP documentation: https://docs.netapp.com/us-en/ontap/
{rule}"""
    print(page)


def _print_runtime_controls_help():
    """Print runtime pause/checkpoint controls used during active runs."""
    _pause_path = _pause_sentinel_path()
    _checkpoint_req_path = _checkpoint_request_path()
    _pid = os.getpid()
    print("\nRuntime pause/checkpoint controls:\n")
    print(f"  Pause file (toggle):    {_pause_path}")
    print("  Remove pause file to resume automation.")
    if hasattr(signal, "SIGUSR1"):
        print(f"  Signal pause toggle:    kill -USR1 {_pid}")
    if hasattr(signal, "SIGUSR2"):
        print(f"  Signal force resume:    kill -USR2 {_pid}")
    print(f"\n  Manual checkpoint file: {_checkpoint_req_path}")
    if hasattr(signal, "SIGURG"):
        print(f"  Signal checkpoint:      kill -URG {_pid}")
    print("")


def _script_last_update_timestamp() -> str:
    """Return last update timestamp for this script.

    Prefers git commit timestamp for AFX_reinit.py; falls back to file mtime.
    """
    script_path = os.path.abspath(__file__)
    script_dir = os.path.dirname(script_path)
    script_name = os.path.basename(script_path)
    try:
        ts = subprocess.check_output(
            ["git", "-C", script_dir, "log", "-1", "--format=%cI", "--", script_name],
            stderr=subprocess.DEVNULL,
            text=True,
        ).strip()
        if ts:
            return ts
    except Exception:
        pass
    return datetime.fromtimestamp(os.path.getmtime(script_path)).isoformat(timespec="seconds")


def _print_version_info() -> None:
    print(f"AFX_reinit.py version: {SCRIPT_VERSION}")
    print(f"Last update timestamp: {_script_last_update_timestamp()}")


def _version_banner_line() -> str:
    return f"AFX_reinit.py v{SCRIPT_VERSION} (last update: {_script_last_update_timestamp()})"


def _script_path_for_completion() -> str:
    try:
        return os.path.abspath(__file__)
    except NameError:
        return os.path.abspath(sys.argv[0] or "AFX_reinit.py")


def _completion_hook_line(script_path: str | None = None) -> str:
    _path = script_path or _script_path_for_completion()
    return f'eval "$(register-python-argcomplete {shlex.quote(_path)})"'


def _completion_rc_paths() -> "list[str]":
    _home = os.path.expanduser("~")
    return [os.path.join(_home, ".bashrc"), os.path.join(_home, ".zshrc")]


def _completion_hook_present(script_path: str | None = None) -> bool:
    _script = script_path or _script_path_for_completion()
    _script_base = os.path.basename(_script)
    for _rc in _completion_rc_paths():
        try:
            if not os.path.isfile(_rc):
                continue
            with open(_rc, "r", encoding="utf-8", errors="ignore") as _f:
                _txt = _f.read()
            if _COMPLETION_BLOCK_START in _txt and _COMPLETION_BLOCK_END in _txt:
                return True
            for _line in _txt.splitlines():
                _l = _line.strip()
                if "register-python-argcomplete" not in _l:
                    continue
                if _script in _l or _script_base in _l:
                    return True
        except Exception:
            continue
    return False


def _ensure_argcomplete_installed() -> bool:
    global HAS_ARGCOMPLETE, argcomplete
    if HAS_ARGCOMPLETE:
        return True
    print("📦 Installing Python module 'argcomplete'...")
    try:
        _proc = subprocess.run(
            [sys.executable, "-m", "pip", "install", "argcomplete"],
            check=False,
        )
    except Exception as _e:
        print(f"❌ Failed to run pip install for argcomplete: {_e}")
        return False
    if _proc.returncode != 0:
        print("❌ Could not install argcomplete.")
        return False
    try:
        importlib.invalidate_caches()
        argcomplete = importlib.import_module("argcomplete")
        HAS_ARGCOMPLETE = True
        print("✅ argcomplete installed.")
        return True
    except Exception as _e:
        print(f"❌ argcomplete installed but import failed: {_e}")
        return False


def _install_completion_hook_block(rc_path: str, hook_line: str) -> bool:
    try:
        _existing = ""
        if os.path.isfile(rc_path):
            with open(rc_path, "r", encoding="utf-8", errors="ignore") as _f:
                _existing = _f.read()
        _block = (
            f"{_COMPLETION_BLOCK_START}\n"
            f"# Added by AFX_reinit.py --install-completion\n"
            f"{hook_line}\n"
            f"{_COMPLETION_BLOCK_END}\n"
        )
        if _COMPLETION_BLOCK_START in _existing and _COMPLETION_BLOCK_END in _existing:
            _start = _existing.index(_COMPLETION_BLOCK_START)
            _end = _existing.index(_COMPLETION_BLOCK_END, _start)
            _end += len(_COMPLETION_BLOCK_END)
            if _end < len(_existing) and _existing[_end:_end + 1] == "\n":
                _end += 1
            _updated = _existing[:_start] + _block + _existing[_end:]
        elif hook_line in _existing:
            _updated = _existing
        else:
            _sep = "" if not _existing or _existing.endswith("\n") else "\n"
            _updated = _existing + _sep + _block
        if _updated != _existing:
            with open(rc_path, "w", encoding="utf-8") as _f:
                _f.write(_updated)
        return True
    except Exception as _e:
        print(f"❌ Could not update {rc_path}: {_e}")
        return False


def _install_completion_support() -> int:
    _script = _script_path_for_completion()
    _hook = _completion_hook_line(_script)
    if not _ensure_argcomplete_installed():
        return 1
    _ok = True
    for _rc in _completion_rc_paths():
        if _install_completion_hook_block(_rc, _hook):
            print(f"✅ Completion hook installed in {_rc}")
        else:
            _ok = False
    print("\nRun this now (or open a new shell):")
    print(f"  {_hook}")
    return 0 if _ok else 1


def _maybe_warn_missing_completion_setup(args) -> None:
    global _completion_startup_warning_shown
    if _completion_startup_warning_shown:
        return
    if not (sys.stdin and sys.stdin.isatty() and sys.stdout and sys.stdout.isatty()):
        return
    if (args.help or args.version or args.config_example
            or args.checkpoint_status or args.checkpoint_list
            or args.last_status or args.show_config
            or args.install_completion or args.print_completion_hook):
        return
    _script = _script_path_for_completion()
    _missing_module = not HAS_ARGCOMPLETE
    _missing_hook = not _completion_hook_present(_script)
    if not (_missing_module or _missing_hook):
        return
    print("\nℹ️  Startup option tab-completion is not fully configured.")
    if _missing_module:
        print("   Missing Python module: argcomplete")
    if _missing_hook:
        print("   Shell hook not found in ~/.bashrc or ~/.zshrc")
    print("   Run: python3 AFX_reinit.py --install-completion")
    print("   Or print just the hook: python3 AFX_reinit.py --print-completion-hook")
    _completion_startup_warning_shown = True


def parse_args():
    # Disable argparse's built-in -h/--help so we can provide a man-page
    # style replacement instead.
    parser = argparse.ArgumentParser(
        description="NetApp AFX BMC console automation script 🤖",
        add_help=False,
    )
    parser.add_argument("--help", "-h", action="store_true", default=False,
                        help="Print this help page and exit.")
    parser.add_argument("--version", action="store_true", default=False,
                        help="Print script version and last update timestamp, then exit.")
    parser.add_argument("--debug", "-d", action="store_true", default=False,
                        help="Debug mode: print all raw console output to the "
                             "screen instead of suppressing it to the log file. "
                             "Also enables verbose Python logging.")
    parser.add_argument("--config", "-c", default=None,
                        help="Path to a JSON config file with cluster/node "
                             "settings. Use --config-example to print the "
                             "expected format.")
    parser.add_argument("--config-example", action="store_true", default=False,
                        help="Print an example config file and exit.")
    parser.add_argument("--bg", action="store_true", default=False,
                        help="Run in background / non-interactive mode. "
                             "Handles SIGHUP so the log is closed cleanly "
                             "when the terminal closes.")
    parser.add_argument("--screen", action="store_true", default=False,
                        help="Re-launch the script inside a GNU screen session "
                             "so it keeps running if your SSH connection drops "
                             "or times out. Implies --bg. Use "
                             "'screen -r afx-reinit' to reattach. "
                             "No-op if already running inside screen.")
    parser.add_argument("--resume", action="store_true", default=False,
                        help="Resume a previous 4.2 run from its last saved "
                             "checkpoint (checkpoints/afx_checkpoint.json). Skips phases "
                             "already completed so you do not have to restart "
                             "from scratch after a failure.")
    parser.add_argument("--checkpoint-status", action="store_true", default=False,
                        help="Print a summary of the saved checkpoint "
                             "(checkpoints/afx_checkpoint.json) showing current "
                             "and next expected phase, where the last run left "
                             "off, and role-labeled per-node progress, then "
                             "exit. Does not modify the checkpoint file.")
